// grammar/Deutsch-C1.js — граматичні теми рівня C1 (мова: Deutsch, de).
// Спільний файл для всіх курсів цього рівня й мови (напр. Deutsch-C1 і Deutsch-C1-Beruf).
// Курс посилається на нього рядком  var GRAMMAR_FILE = "Deutsch-C1";  — LESSONS.grammar і поле gram
// карток (VOCAB, DIALOGE, SPRACHBAUSTEINE, SCHREIBEN, EMAILS) містять id звідси.
// id мають бути унікальними в межах УСІХ grammar/Deutsch-*.js (перевірка: node tools/check-grammar.js).
// Файл оголошує ЛИШЕ GRAMMAR_LANG і GRAMMAR: у монолітному режимі він вантажиться звичайним
// скриптом поруч із файлом курсу, і будь-яка інша глобальна змінна перезаписала б змінну курсу.
var GRAMMAR_LANG = "de";

// ── ГРАМАТИКА ────────────────────────────────────────────────
// Кожне правило: id (стабільний, на нього посилаються LESSONS.grammar
// і card.gram у VOCAB/DIALOGE/SPRACHBAUSTEINE) + title/explanation
// багатомовно. explanation підтримує <g>/<b> для підсвітки прикладів.
var GRAMMAR = [
  {
    "id": "konnektoren_folge_ausnahme",
    "title": {"de": "Konnektoren: andernfalls, folglich, außer wenn …", "en": "Connectors: andernfalls, folglich, außer wenn …", "uk": "Сполучники: andernfalls, folglich, außer wenn …", "ru": "Союзы: andernfalls, folglich, außer wenn …"},
    "explanation": {
      "de": "<b>Konnektoren zeigen, wie zwei Sätze logisch zusammenhängen.</b><br><g>Folglich</g>, <g>demnach</g> und <g>somit</g> nennen eine Folge. <g>Andernfalls</g> und <g>ansonsten</g> nennen eine negative Alternative („sonst“). <g>Außer wenn</g> und <g>es sei denn</g> nennen eine Ausnahme. Nach <g>folglich</g> und <g>andernfalls</g> steht das Verb auf Position 2, nach <g>außer wenn</g> am Satzende.<br>Beispiel: Beeil dich, <g>andernfalls</g> verpasst du den Zug.",
      "en": "<b>Connectors show how two sentences are logically related.</b><br><g>Folglich</g>, <g>demnach</g> and <g>somit</g> express a consequence. <g>Andernfalls</g> and <g>ansonsten</g> express a negative alternative (“otherwise”). <g>Außer wenn</g> and <g>es sei denn</g> express an exception. After <g>folglich</g> and <g>andernfalls</g> the verb is in second position; after <g>außer wenn</g> it goes to the end of the clause.<br>Example: Beeil dich, <g>andernfalls</g> verpasst du den Zug.<br>Hurry up, otherwise you will miss the train.",
      "uk": "<b>Сполучники показують логічний звʼязок між двома реченнями.</b><br><g>Folglich</g>, <g>demnach</g> і <g>somit</g> називають наслідок. <g>Andernfalls</g> і <g>ansonsten</g> називають негативну альтернативу («інакше»). <g>Außer wenn</g> і <g>es sei denn</g> називають виняток. Після <g>folglich</g> і <g>andernfalls</g> дієслово стоїть на другому місці, після <g>außer wenn</g> — наприкінці речення.<br>Приклад: Beeil dich, <g>andernfalls</g> verpasst du den Zug.<br>Поспішай, інакше запізнишся на потяг.",
      "ru": "<b>Коннекторы показывают логическую связь между двумя предложениями.</b><br><g>Folglich</g>, <g>demnach</g> и <g>somit</g> называют следствие. <g>Andernfalls</g> и <g>ansonsten</g> называют негативную альтернативу («иначе»). <g>Außer wenn</g> и <g>es sei denn</g> называют исключение. После <g>folglich</g> и <g>andernfalls</g> глагол стоит на втором месте, после <g>außer wenn</g> — в конце предложения.<br>Пример: Beeil dich, <g>andernfalls</g> verpasst du den Zug.<br>Поторопись, иначе опоздаешь на поезд."
    },
    "rule": {
      "de": "<b>1. Überblick</b><br>Diese Konnektoren verbinden zwei Hauptsätze oder einen Hauptsatz mit einem Nebensatz. Sie gehören vor allem zur Schrift- und Bildungssprache.<br><br><table><tr><th>Funktion</th><th>Konnektoren</th></tr><tr><td>Folge</td><td><g>folglich</g>, <g>demnach</g>, <g>infolgedessen</g>, <g>somit</g></td></tr><tr><td>negative Alternative</td><td><g>andernfalls</g>, <g>anderenfalls</g>, <g>ansonsten</g>, <g>sonst</g></td></tr><tr><td>Ausnahme</td><td><g>außer wenn</g>, <g>es sei denn</g></td></tr></table><br><br><b>2. Folge: folglich, demnach, infolgedessen, somit</b><br>Diese Wörter sind Konnektoradverbien. Sie stehen auf Position 1 des zweiten Hauptsatzes, dann folgt das Verb (Position 2). Sie können auch im Mittelfeld stehen. Vor dem zweiten Satz steht ein Komma, ein Semikolon oder ein Punkt.<br><br>Er war krank, <g>folglich</g> kam er nicht zur Besprechung.<br>Der Vertrag wurde nicht unterschrieben. Die Lieferung kann <g>somit</g> nicht erfolgen.<br>Die Preise sind gestiegen, <g>infolgedessen</g> sinkt die Nachfrage.<br>Alle Zeugen sagen dasselbe. Er ist <g>demnach</g> unschuldig.<br><br><g>Demnach</g> kann auch „laut diesen Informationen“ bedeuten: <g>Demnach</g> ist das Gebäude schon verkauft.<br><br><b>3. Negative Alternative: andernfalls, ansonsten, sonst</b><br>Diese Konnektoren nennen, was passiert, wenn die Bedingung im ersten Satz nicht erfüllt ist. Sie stehen auf Position 1 (dann Verb auf Position 2) oder im Mittelfeld. <g>Andernfalls</g> und <g>anderenfalls</g> sind formell, <g>sonst</g> ist neutral, <g>ansonsten</g> ist eher gesprochene Sprache.<br><br>Beeil dich, <g>andernfalls</g> verpasst du den Zug.<br>Die Rechnung muss bis Freitag bezahlt werden, <g>ansonsten</g> berechnen wir Mahngebühren.<br>Die Unterlagen müssen vollständig sein. Sie werden <g>andernfalls</g> nicht bearbeitet.<br><br><g>Ansonsten</g> hat auch eine zweite Bedeutung: „abgesehen davon“. Hier ist keine Bedingung gemeint: <g>Ansonsten</g> war der Urlaub schön.<br><br><b>4. Ausnahme: außer wenn, es sei denn</b><br><g>Außer wenn</g> leitet einen Nebensatz ein: Das Verb steht am Ende. Nach <g>es sei denn</g> steht ein Hauptsatz (Verb auf Position 2) oder ein dass-Satz (Verb am Ende). Der Satz mit <g>es sei denn</g> steht immer nach dem ersten Satz und wird durch ein Komma getrennt.<br><br>Ich komme morgen, <g>außer wenn</g> es stark <g>regnet</g>.<br>Wir fangen pünktlich an, <g>es sei denn</g>, der Referent <g>kommt</g> später.<br>Wir fangen pünktlich an, <g>es sei denn</g>, dass der Referent später <g>kommt</g>.<br><br>Im Deutschen steht bei der Ausnahme meist keine Verneinung, obwohl der Sinn „wenn nicht“ ist.<br><br><b>5. Stil und Verwendung</b><br><g>Folglich</g>, <g>demnach</g>, <g>somit</g>, <g>infolgedessen</g> und <g>andernfalls</g> findest du vor allem in Berichten, Verträgen und wissenschaftlichen Texten. Im Alltag sagt man meist <g>deshalb</g>, <g>also</g> und <g>sonst</g>.",
      "en": "<b>1. Overview</b><br>These connectors link two main clauses or a main clause with a subordinate clause. They belong mainly to written and formal language.<br><br><table><tr><th>Function</th><th>Connectors</th></tr><tr><td>Consequence</td><td><g>folglich</g>, <g>demnach</g>, <g>infolgedessen</g>, <g>somit</g></td></tr><tr><td>Negative alternative</td><td><g>andernfalls</g>, <g>anderenfalls</g>, <g>ansonsten</g>, <g>sonst</g></td></tr><tr><td>Exception</td><td><g>außer wenn</g>, <g>es sei denn</g></td></tr></table><br><br><b>2. Consequence: folglich, demnach, infolgedessen, somit</b><br>These words are connector adverbs. They stand in position 1 of the second main clause, followed by the verb (position 2). They can also stand in the middle field. A comma, a semicolon or a full stop comes before the second clause.<br><br>Er war krank, <g>folglich</g> kam er nicht zur Besprechung.<br>He was ill, so he did not come to the meeting.<br>Der Vertrag wurde nicht unterschrieben. Die Lieferung kann <g>somit</g> nicht erfolgen.<br>The contract was not signed. The delivery therefore cannot take place.<br>Die Preise sind gestiegen, <g>infolgedessen</g> sinkt die Nachfrage.<br>Prices have risen, as a result demand is falling.<br>Alle Zeugen sagen dasselbe. Er ist <g>demnach</g> unschuldig.<br>All the witnesses say the same thing. He is therefore innocent.<br><br><g>Demnach</g> can also mean “according to this information”: <g>Demnach</g> ist das Gebäude schon verkauft.<br><br><b>3. Negative alternative: andernfalls, ansonsten, sonst</b><br>These connectors say what happens if the condition in the first sentence is not met. They stand in position 1 (then the verb is in position 2) or in the middle field. <g>Andernfalls</g> and <g>anderenfalls</g> are formal, <g>sonst</g> is neutral, <g>ansonsten</g> is more typical of spoken language.<br><br>Beeil dich, <g>andernfalls</g> verpasst du den Zug.<br>Hurry up, otherwise you will miss the train.<br>Die Rechnung muss bis Freitag bezahlt werden, <g>ansonsten</g> berechnen wir Mahngebühren.<br>The invoice must be paid by Friday, otherwise we will charge reminder fees.<br>Die Unterlagen müssen vollständig sein. Sie werden <g>andernfalls</g> nicht bearbeitet.<br>The documents must be complete. Otherwise they will not be processed.<br><br><g>Ansonsten</g> also has a second meaning: “apart from that”. No condition is meant here: <g>Ansonsten</g> war der Urlaub schön.<br><br><b>4. Exception: außer wenn, es sei denn</b><br><g>Außer wenn</g> introduces a subordinate clause: the verb is at the end. After <g>es sei denn</g> there is either a main clause (verb in position 2) or a dass-clause (verb at the end). The clause with <g>es sei denn</g> always comes after the first clause and is separated by a comma.<br><br>Ich komme morgen, <g>außer wenn</g> es stark <g>regnet</g>.<br>I'll come tomorrow, unless it rains heavily.<br>Wir fangen pünktlich an, <g>es sei denn</g>, der Referent <g>kommt</g> später.<br>We will start on time, unless the speaker arrives later.<br>Wir fangen pünktlich an, <g>es sei denn</g>, dass der Referent später <g>kommt</g>.<br>We will start on time, unless the speaker arrives later.<br><br>In German the exception clause usually contains no negation, although the meaning is “if not”.<br><br><b>5. Style and use</b><br>You find <g>folglich</g>, <g>demnach</g>, <g>somit</g>, <g>infolgedessen</g> and <g>andernfalls</g> mainly in reports, contracts and academic texts. In everyday speech people usually say <g>deshalb</g>, <g>also</g> and <g>sonst</g>.",
      "uk": "<b>1. Огляд</b><br>Ці сполучники поєднують два головні речення або головне речення з підрядним. Вони належать передусім до писемної та офіційної мови.<br><br><table><tr><th>Функція</th><th>Сполучники</th></tr><tr><td>Наслідок</td><td><g>folglich</g>, <g>demnach</g>, <g>infolgedessen</g>, <g>somit</g></td></tr><tr><td>Негативна альтернатива</td><td><g>andernfalls</g>, <g>anderenfalls</g>, <g>ansonsten</g>, <g>sonst</g></td></tr><tr><td>Виняток</td><td><g>außer wenn</g>, <g>es sei denn</g></td></tr></table><br><br><b>2. Наслідок: folglich, demnach, infolgedessen, somit</b><br>Ці слова — сполучникові прислівники. Вони стоять на першому місці другого головного речення, далі йде дієслово (друге місце). Вони можуть стояти й у середній частині речення. Перед другим реченням ставиться кома, крапка з комою або крапка.<br><br>Er war krank, <g>folglich</g> kam er nicht zur Besprechung.<br>Він був хворий, тому не прийшов на нараду.<br>Der Vertrag wurde nicht unterschrieben. Die Lieferung kann <g>somit</g> nicht erfolgen.<br>Договір не підписано. Отже, поставка не може відбутися.<br>Die Preise sind gestiegen, <g>infolgedessen</g> sinkt die Nachfrage.<br>Ціни зросли, внаслідок цього попит падає.<br>Alle Zeugen sagen dasselbe. Er ist <g>demnach</g> unschuldig.<br>Усі свідки кажуть те саме. Отже, він невинний.<br><br><g>Demnach</g> може також означати «згідно з цією інформацією»: <g>Demnach</g> ist das Gebäude schon verkauft.<br><br><b>3. Негативна альтернатива: andernfalls, ansonsten, sonst</b><br>Ці сполучники називають те, що станеться, якщо умова з першого речення не виконана. Вони стоять на першому місці (тоді дієслово на другому) або в середній частині речення. <g>Andernfalls</g> і <g>anderenfalls</g> — офіційні, <g>sonst</g> — нейтральне, <g>ansonsten</g> більше властиве розмовній мові.<br><br>Beeil dich, <g>andernfalls</g> verpasst du den Zug.<br>Поспішай, інакше запізнишся на потяг.<br>Die Rechnung muss bis Freitag bezahlt werden, <g>ansonsten</g> berechnen wir Mahngebühren.<br>Рахунок потрібно оплатити до пʼятниці, інакше ми нарахуємо штраф за нагадування.<br>Die Unterlagen müssen vollständig sein. Sie werden <g>andernfalls</g> nicht bearbeitet.<br>Документи мають бути повними. Інакше їх не опрацюють.<br><br><g>Ansonsten</g> має ще одне значення: «окрім цього». Тут умова не мається на увазі: <g>Ansonsten</g> war der Urlaub schön.<br><br><b>4. Виняток: außer wenn, es sei denn</b><br><g>Außer wenn</g> вводить підрядне речення: дієслово стоїть наприкінці. Після <g>es sei denn</g> стоїть головне речення (дієслово на другому місці) або речення з dass (дієслово наприкінці). Речення з <g>es sei denn</g> завжди стоїть після першого речення й відокремлюється комою.<br><br>Ich komme morgen, <g>außer wenn</g> es stark <g>regnet</g>.<br>Я прийду завтра, хіба що сильно дощитиме.<br>Wir fangen pünktlich an, <g>es sei denn</g>, der Referent <g>kommt</g> später.<br>Ми почнемо вчасно, хіба що доповідач прийде пізніше.<br>Wir fangen pünktlich an, <g>es sei denn</g>, dass der Referent später <g>kommt</g>.<br>Ми почнемо вчасно, хіба що доповідач прийде пізніше.<br><br>У німецькій мові речення з винятком зазвичай не містить заперечення, хоча за змістом це «якщо не».<br><br><b>5. Стиль і вживання</b><br><g>Folglich</g>, <g>demnach</g>, <g>somit</g>, <g>infolgedessen</g> і <g>andernfalls</g> трапляються передусім у звітах, договорах і наукових текстах. У повсякденному мовленні зазвичай кажуть <g>deshalb</g>, <g>also</g> і <g>sonst</g>.",
      "ru": "<b>1. Обзор</b><br>Эти коннекторы соединяют два главных предложения или главное предложение с придаточным. Они относятся в основном к письменной и официальной речи.<br><br><table><tr><th>Функция</th><th>Коннекторы</th></tr><tr><td>Следствие</td><td><g>folglich</g>, <g>demnach</g>, <g>infolgedessen</g>, <g>somit</g></td></tr><tr><td>Негативная альтернатива</td><td><g>andernfalls</g>, <g>anderenfalls</g>, <g>ansonsten</g>, <g>sonst</g></td></tr><tr><td>Исключение</td><td><g>außer wenn</g>, <g>es sei denn</g></td></tr></table><br><br><b>2. Следствие: folglich, demnach, infolgedessen, somit</b><br>Эти слова — союзные наречия. Они стоят на первом месте второго главного предложения, затем идёт глагол (второе место). Они могут стоять и в средней части предложения. Перед вторым предложением ставится запятая, точка с запятой или точка.<br><br>Er war krank, <g>folglich</g> kam er nicht zur Besprechung.<br>Он был болен, поэтому не пришёл на совещание.<br>Der Vertrag wurde nicht unterschrieben. Die Lieferung kann <g>somit</g> nicht erfolgen.<br>Договор не подписан. Следовательно, поставка не может состояться.<br>Die Preise sind gestiegen, <g>infolgedessen</g> sinkt die Nachfrage.<br>Цены выросли, вследствие этого спрос падает.<br>Alle Zeugen sagen dasselbe. Er ist <g>demnach</g> unschuldig.<br>Все свидетели говорят одно и то же. Значит, он невиновен.<br><br><g>Demnach</g> может также значить «согласно этой информации»: <g>Demnach</g> ist das Gebäude schon verkauft.<br><br><b>3. Негативная альтернатива: andernfalls, ansonsten, sonst</b><br>Эти коннекторы называют то, что произойдёт, если условие из первого предложения не выполнено. Они стоят на первом месте (тогда глагол на втором) или в средней части предложения. <g>Andernfalls</g> и <g>anderenfalls</g> — официальные, <g>sonst</g> — нейтральное, <g>ansonsten</g> больше свойственно разговорной речи.<br><br>Beeil dich, <g>andernfalls</g> verpasst du den Zug.<br>Поторопись, иначе опоздаешь на поезд.<br>Die Rechnung muss bis Freitag bezahlt werden, <g>ansonsten</g> berechnen wir Mahngebühren.<br>Счёт нужно оплатить до пятницы, иначе мы начислим штраф за напоминание.<br>Die Unterlagen müssen vollständig sein. Sie werden <g>andernfalls</g> nicht bearbeitet.<br>Документы должны быть полными. Иначе их не станут обрабатывать.<br><br><g>Ansonsten</g> имеет и второе значение: «кроме этого». Здесь условие не подразумевается: <g>Ansonsten</g> war der Urlaub schön.<br><br><b>4. Исключение: außer wenn, es sei denn</b><br><g>Außer wenn</g> вводит придаточное предложение: глагол стоит в конце. После <g>es sei denn</g> стоит главное предложение (глагол на втором месте) или придаточное с dass (глагол в конце). Предложение с <g>es sei denn</g> всегда стоит после первого и отделяется запятой.<br><br>Ich komme morgen, <g>außer wenn</g> es stark <g>regnet</g>.<br>Я приду завтра, разве что пойдёт сильный дождь.<br>Wir fangen pünktlich an, <g>es sei denn</g>, der Referent <g>kommt</g> später.<br>Мы начнём вовремя, если только докладчик не придёт позже.<br>Wir fangen pünktlich an, <g>es sei denn</g>, dass der Referent später <g>kommt</g>.<br>Мы начнём вовремя, если только докладчик не придёт позже.<br><br>В немецком языке предложение с исключением обычно не содержит отрицания, хотя по смыслу это «если не».<br><br><b>5. Стиль и употребление</b><br><g>Folglich</g>, <g>demnach</g>, <g>somit</g>, <g>infolgedessen</g> и <g>andernfalls</g> встречаются в основном в отчётах, договорах и научных текстах. В повседневной речи обычно говорят <g>deshalb</g>, <g>also</g> и <g>sonst</g>."
    }
  },
  {
    "id": "trennbare_untrennbare_verben",
    "title": {"de": "Trennbare und untrennbare Verben", "en": "Separable and inseparable verbs", "uk": "Віддільні та невіддільні дієслова", "ru": "Отделяемые и неотделяемые глаголы"},
    "explanation": {
      "de": "<b>Das Präfix entscheidet, ob ein Verb trennbar ist.</b><br>Bei <b>trennbaren</b> Verben ist das Präfix betont und steht im Hauptsatz am Satzende: <g>ankommen</g> – Er <g>kommt</g> um acht <g>an</g>. Bei <b>untrennbaren</b> Verben (be-, ent-, er-, ver-, zer- …) ist das Präfix unbetont und bleibt fest: <g>verstehen</g> – Ich <g>verstehe</g> das. Bei <b>über-, unter-, um-, durch-, wider-</b> gibt es beide Varianten, oft mit verschiedener Bedeutung.<br>Beispiel: Er <g>liest</g> den Text <g>durch</g>. – Er <g>durchschaut</g> den Trick.",
      "en": "<b>The prefix decides whether a verb is separable.</b><br>With <b>separable</b> verbs the prefix is stressed and goes to the end of a main clause: <g>ankommen</g> – Er <g>kommt</g> um acht <g>an</g>. With <b>inseparable</b> verbs (be-, ent-, er-, ver-, zer- …) the prefix is unstressed and stays attached: <g>verstehen</g> – Ich <g>verstehe</g> das. With <b>über-, unter-, um-, durch-, wider-</b> both variants exist, often with different meanings.<br>Example: Er <g>liest</g> den Text <g>durch</g>. – Er <g>durchschaut</g> den Trick.<br>He reads the text through. – He sees through the trick.",
      "uk": "<b>Префікс визначає, чи дієслово віддільне.</b><br>У <b>віддільних</b> дієсловах префікс наголошений і в головному реченні стоїть наприкінці: <g>ankommen</g> – Er <g>kommt</g> um acht <g>an</g>. У <b>невіддільних</b> дієсловах (be-, ent-, er-, ver-, zer- …) префікс ненаголошений і лишається нерозривним: <g>verstehen</g> – Ich <g>verstehe</g> das. Префікси <b>über-, unter-, um-, durch-, wider-</b> трапляються в обох варіантах, часто з різним значенням.<br>Приклад: Er <g>liest</g> den Text <g>durch</g>. – Er <g>durchschaut</g> den Trick.<br>Він прочитує текст до кінця. – Він розгадує трюк.",
      "ru": "<b>Приставка определяет, отделяемый ли глагол.</b><br>У <b>отделяемых</b> глаголов приставка ударная и в главном предложении стоит в конце: <g>ankommen</g> – Er <g>kommt</g> um acht <g>an</g>. У <b>неотделяемых</b> глаголов (be-, ent-, er-, ver-, zer- …) приставка безударная и остаётся неразрывной: <g>verstehen</g> – Ich <g>verstehe</g> das. Приставки <b>über-, unter-, um-, durch-, wider-</b> встречаются в обоих вариантах, часто с разным значением.<br>Пример: Er <g>liest</g> den Text <g>durch</g>. – Er <g>durchschaut</g> den Trick.<br>Он прочитывает текст до конца. – Он раскусывает трюк."
    },
    "rule": {
      "de": "<b>1. Grundprinzip</b><br>Der Unterschied zeigt sich in Betonung, Satzstellung und Partizip II.<br><br><table><tr><th>trennbar</th><th>untrennbar</th></tr><tr><td>Präfix betont: <g>án</g>kommen</td><td>Präfix unbetont: <g>ver</g>stéhen</td></tr><tr><td>Er kommt um acht <g>an</g>.</td><td>Er <g>versteht</g> mich.</td></tr><tr><td>…, weil er um acht <g>ankommt</g>.</td><td>…, weil er mich <g>versteht</g>.</td></tr><tr><td><g>an</g>ge<g>kommen</g></td><td><g>ver</g><g>standen</g> (kein ge-)</td></tr><tr><td><g>an</g><g>zu</g><g>kommen</g></td><td><g>zu</g> <g>verstehen</g></td></tr></table><br><br>Beim Partizip II und beim Infinitiv mit zu steht „ge“ bzw. „zu“ bei trennbaren Verben zwischen Präfix und Stamm; bei untrennbaren Verben entfällt „ge-“.<br><br><b>2. Typische Präfixe</b><br><b>Immer untrennbar:</b> be-, emp-, ent-, er-, ge-, miss-, ver-, zer-. Beispiele: <g>bekommen</g>, <g>entscheiden</g>, <g>erklären</g>, <g>gehören</g>, <g>missverstehen</g>, <g>verlieren</g>, <g>zerstören</g>.<br><b>Meist trennbar:</b> ab-, an-, auf-, aus-, bei-, ein-, fest-, mit-, nach-, vor-, weg-, zu-, zurück-, zusammen-. Beispiele: <g>abholen</g>, <g>aufstehen</g>, <g>einladen</g>, <g>mitbringen</g>, <g>vorschlagen</g>.<br><br><b>3. Wechselpräfixe: über-, unter-, um-, durch-, wider-</b><br>Diese Präfixe können trennbar oder untrennbar sein. Als Faustregel gilt: <b>Trennbar</b> sind sie meist bei konkreter, räumlicher Bedeutung (betontes Präfix). <b>Untrennbar</b> sind sie meist bei übertragener Bedeutung (Betonung auf dem Stamm). Die Bedeutung ändert sich oft stark, deshalb lernst du diese Verben am besten einzeln.<br><br><table><tr><th>trennbar (konkret)</th><th>untrennbar (übertragen)</th></tr><tr><td>Er <g>liest</g> den Text <g>durch</g>.</td><td>Er <g>durchschaut</g> den Trick.</td></tr><tr><td>Der Lkw <g>fährt</g> das Schild <g>um</g>.</td><td>Er <g>umfährt</g> den Stau.</td></tr><tr><td>Er <g>geht</g> gut mit Kindern <g>um</g>.</td><td>Er <g>umgeht</g> das Gesetz.</td></tr><tr><td>Wir <g>setzen</g> mit der Fähre <g>über</g>.</td><td>Er <g>übersetzt</g> den Brief.</td></tr><tr><td>Ich <g>stelle</g> das Auto <g>unter</g>.</td><td>Er <g>unterstellt</g> mir Absicht.</td></tr></table><br><br>Die Beispiele bedeuten: durchlesen – durchschauen (erkennen); umfahren (anfahren und umwerfen) – umfahren (herumfahren); mit etwas umgehen (behandeln) – umgehen (vermeiden); übersetzen (ans andere Ufer fahren) – übersetzen (in eine andere Sprache); unterstellen (darunter abstellen) – unterstellen (zu Unrecht behaupten).<br><br><b>4. Besonderheiten</b><br><b>Die Verben mit „wider-“</b> sind fast immer untrennbar: <g>widersprechen</g> (Er widerspricht mir), <g>widerstehen</g>. Trennbar sind nur <g>widerspiegeln</g> (Der See spiegelt die Berge wider) und <g>widerhallen</g>.<br><b>„wiederholen“</b> im Sinn von „noch einmal sagen oder machen“ ist untrennbar: Er wiederholt die Frage.<br><b>Zwei Präfixe:</b> Entscheidend ist das erste Präfix. Ist es trennbar, bleibt das Verb trennbar: <g>vorbereiten</g> – Ich bereite die Rede vor (Partizip: vorbereitet; Infinitiv: vorzubereiten). So auch <g>anerkennen</g> – Er erkennt die Leistung an (anerkannt; anzuerkennen).",
      "en": "<b>1. Basic principle</b><br>The difference shows in stress, word order and the past participle.<br><br><table><tr><th>Separable</th><th>Inseparable</th></tr><tr><td>Prefix stressed: <g>án</g>kommen</td><td>Prefix unstressed: <g>ver</g>stéhen</td></tr><tr><td>Er kommt um acht <g>an</g>.</td><td>Er <g>versteht</g> mich.</td></tr><tr><td>…, weil er um acht <g>ankommt</g>.</td><td>…, weil er mich <g>versteht</g>.</td></tr><tr><td><g>an</g>ge<g>kommen</g></td><td><g>ver</g><g>standen</g> (no ge-)</td></tr><tr><td><g>an</g><g>zu</g><g>kommen</g></td><td><g>zu</g> <g>verstehen</g></td></tr></table><br><br>With separable verbs, “ge” and “zu” go between the prefix and the stem; with inseparable verbs “ge-” is dropped.<br><br><b>2. Typical prefixes</b><br><b>Always inseparable:</b> be-, emp-, ent-, er-, ge-, miss-, ver-, zer-. Examples: <g>bekommen</g>, <g>entscheiden</g>, <g>erklären</g>, <g>gehören</g>, <g>missverstehen</g>, <g>verlieren</g>, <g>zerstören</g>.<br><b>Mostly separable:</b> ab-, an-, auf-, aus-, bei-, ein-, fest-, mit-, nach-, vor-, weg-, zu-, zurück-, zusammen-. Examples: <g>abholen</g>, <g>aufstehen</g>, <g>einladen</g>, <g>mitbringen</g>, <g>vorschlagen</g>.<br><br><b>3. Variable prefixes: über-, unter-, um-, durch-, wider-</b><br>These prefixes can be separable or inseparable. As a rule of thumb: they are usually <b>separable</b> when the meaning is concrete and spatial (stressed prefix). They are usually <b>inseparable</b> when the meaning is figurative (stress on the stem). The meaning often changes greatly, so it is best to learn these verbs one by one.<br><br><table><tr><th>Separable (literal)</th><th>Inseparable (figurative)</th></tr><tr><td>Er <g>liest</g> den Text <g>durch</g>.</td><td>Er <g>durchschaut</g> den Trick.</td></tr><tr><td>Der Lkw <g>fährt</g> das Schild <g>um</g>.</td><td>Er <g>umfährt</g> den Stau.</td></tr><tr><td>Er <g>geht</g> gut mit Kindern <g>um</g>.</td><td>Er <g>umgeht</g> das Gesetz.</td></tr><tr><td>Wir <g>setzen</g> mit der Fähre <g>über</g>.</td><td>Er <g>übersetzt</g> den Brief.</td></tr><tr><td>Ich <g>stelle</g> das Auto <g>unter</g>.</td><td>Er <g>unterstellt</g> mir Absicht.</td></tr></table><br><br>The examples mean: to read through – to see through (to recognise); to knock down – to drive around; to deal with – to circumvent; to ferry across – to translate; to put under cover – to insinuate.<br><br><b>4. Special points</b><br><b>Verbs with “wider-”</b> are almost always inseparable: <g>widersprechen</g> (Er widerspricht mir), <g>widerstehen</g>. Only <g>widerspiegeln</g> (Der See spiegelt die Berge wider) and <g>widerhallen</g> are separable.<br><b>“wiederholen”</b> in the sense of “to say or do again” is inseparable: Er wiederholt die Frage.<br><b>Two prefixes:</b> the first prefix decides. If it is separable, the verb stays separable: <g>vorbereiten</g> – Ich bereite die Rede vor (participle: vorbereitet; infinitive: vorzubereiten). The same applies to <g>anerkennen</g> – Er erkennt die Leistung an (anerkannt; anzuerkennen).",
      "uk": "<b>1. Основний принцип</b><br>Різниця виявляється в наголосі, порядку слів і дієприкметнику ІІ.<br><br><table><tr><th>Віддільні</th><th>Невіддільні</th></tr><tr><td>Префікс наголошений: <g>án</g>kommen</td><td>Префікс ненаголошений: <g>ver</g>stéhen</td></tr><tr><td>Er kommt um acht <g>an</g>.</td><td>Er <g>versteht</g> mich.</td></tr><tr><td>…, weil er um acht <g>ankommt</g>.</td><td>…, weil er mich <g>versteht</g>.</td></tr><tr><td><g>an</g>ge<g>kommen</g></td><td><g>ver</g><g>standen</g> (без ge-)</td></tr><tr><td><g>an</g><g>zu</g><g>kommen</g></td><td><g>zu</g> <g>verstehen</g></td></tr></table><br><br>У віддільних дієсловах «ge» і «zu» стоять між префіксом і коренем; у невіддільних «ge-» не додається.<br><br><b>2. Типові префікси</b><br><b>Завжди невіддільні:</b> be-, emp-, ent-, er-, ge-, miss-, ver-, zer-. Приклади: <g>bekommen</g>, <g>entscheiden</g>, <g>erklären</g>, <g>gehören</g>, <g>missverstehen</g>, <g>verlieren</g>, <g>zerstören</g>.<br><b>Здебільшого віддільні:</b> ab-, an-, auf-, aus-, bei-, ein-, fest-, mit-, nach-, vor-, weg-, zu-, zurück-, zusammen-. Приклади: <g>abholen</g>, <g>aufstehen</g>, <g>einladen</g>, <g>mitbringen</g>, <g>vorschlagen</g>.<br><br><b>3. Змінні префікси: über-, unter-, um-, durch-, wider-</b><br>Ці префікси можуть бути віддільними або невіддільними. Практичне правило: вони <b>віддільні</b> здебільшого за конкретного, просторового значення (наголошений префікс) і <b>невіддільні</b> здебільшого за переносного значення (наголос на корені). Значення часто сильно змінюється, тому такі дієслова найкраще вчити окремо.<br><br><table><tr><th>Віддільне (буквальне)</th><th>Невіддільне (переносне)</th></tr><tr><td>Er <g>liest</g> den Text <g>durch</g>.</td><td>Er <g>durchschaut</g> den Trick.</td></tr><tr><td>Der Lkw <g>fährt</g> das Schild <g>um</g>.</td><td>Er <g>umfährt</g> den Stau.</td></tr><tr><td>Er <g>geht</g> gut mit Kindern <g>um</g>.</td><td>Er <g>umgeht</g> das Gesetz.</td></tr><tr><td>Wir <g>setzen</g> mit der Fähre <g>über</g>.</td><td>Er <g>übersetzt</g> den Brief.</td></tr><tr><td>Ich <g>stelle</g> das Auto <g>unter</g>.</td><td>Er <g>unterstellt</g> mir Absicht.</td></tr></table><br><br>Приклади означають: прочитати до кінця – розгадати; збити (проїжджаючи) – обʼїхати; поводитися з кимось – обходити (закон); переправитися на інший берег – перекласти текст; поставити під укриття – безпідставно приписувати.<br><br><b>4. Особливості</b><br><b>Дієслова з «wider-»</b> майже завжди невіддільні: <g>widersprechen</g> (Er widerspricht mir), <g>widerstehen</g>. Віддільні лише <g>widerspiegeln</g> (Der See spiegelt die Berge wider) і <g>widerhallen</g>.<br><b>«wiederholen»</b> у значенні «повторити» невіддільне: Er wiederholt die Frage.<br><b>Два префікси:</b> вирішальний перший префікс. Якщо він віддільний, дієслово лишається віддільним: <g>vorbereiten</g> – Ich bereite die Rede vor (дієприкметник: vorbereitet; інфінітив: vorzubereiten). Так само <g>anerkennen</g> – Er erkennt die Leistung an (anerkannt; anzuerkennen).",
      "ru": "<b>1. Основной принцип</b><br>Разница проявляется в ударении, порядке слов и причастии II.<br><br><table><tr><th>Отделяемые</th><th>Неотделяемые</th></tr><tr><td>Приставка ударная: <g>án</g>kommen</td><td>Приставка безударная: <g>ver</g>stéhen</td></tr><tr><td>Er kommt um acht <g>an</g>.</td><td>Er <g>versteht</g> mich.</td></tr><tr><td>…, weil er um acht <g>ankommt</g>.</td><td>…, weil er mich <g>versteht</g>.</td></tr><tr><td><g>an</g>ge<g>kommen</g></td><td><g>ver</g><g>standen</g> (без ge-)</td></tr><tr><td><g>an</g><g>zu</g><g>kommen</g></td><td><g>zu</g> <g>verstehen</g></td></tr></table><br><br>У отделяемых глаголов «ge» и «zu» стоят между приставкой и корнем; у неотделяемых «ge-» не добавляется.<br><br><b>2. Типичные приставки</b><br><b>Всегда неотделяемые:</b> be-, emp-, ent-, er-, ge-, miss-, ver-, zer-. Примеры: <g>bekommen</g>, <g>entscheiden</g>, <g>erklären</g>, <g>gehören</g>, <g>missverstehen</g>, <g>verlieren</g>, <g>zerstören</g>.<br><b>Преимущественно отделяемые:</b> ab-, an-, auf-, aus-, bei-, ein-, fest-, mit-, nach-, vor-, weg-, zu-, zurück-, zusammen-. Примеры: <g>abholen</g>, <g>aufstehen</g>, <g>einladen</g>, <g>mitbringen</g>, <g>vorschlagen</g>.<br><br><b>3. Изменяемые приставки: über-, unter-, um-, durch-, wider-</b><br>Эти приставки могут быть отделяемыми или неотделяемыми. Практическое правило: они <b>отделяемые</b> в основном при конкретном, пространственном значении (ударная приставка) и <b>неотделяемые</b> в основном при переносном значении (ударение на корне). Значение часто сильно меняется, поэтому такие глаголы лучше учить по отдельности.<br><br><table><tr><th>Отделяемое (буквальное)</th><th>Неотделяемое (переносное)</th></tr><tr><td>Er <g>liest</g> den Text <g>durch</g>.</td><td>Er <g>durchschaut</g> den Trick.</td></tr><tr><td>Der Lkw <g>fährt</g> das Schild <g>um</g>.</td><td>Er <g>umfährt</g> den Stau.</td></tr><tr><td>Er <g>geht</g> gut mit Kindern <g>um</g>.</td><td>Er <g>umgeht</g> das Gesetz.</td></tr><tr><td>Wir <g>setzen</g> mit der Fähre <g>über</g>.</td><td>Er <g>übersetzt</g> den Brief.</td></tr><tr><td>Ich <g>stelle</g> das Auto <g>unter</g>.</td><td>Er <g>unterstellt</g> mir Absicht.</td></tr></table><br><br>Примеры означают: прочитать до конца – раскусить; сбить (проезжая) – объехать; обращаться с кем-либо – обходить (закон); переправиться на другой берег – перевести текст; поставить под укрытие – необоснованно приписывать.<br><br><b>4. Особенности</b><br><b>Глаголы с «wider-»</b> почти всегда неотделяемые: <g>widersprechen</g> (Er widerspricht mir), <g>widerstehen</g>. Отделяемыми являются только <g>widerspiegeln</g> (Der See spiegelt die Berge wider) и <g>widerhallen</g>.<br><b>«wiederholen»</b> в значении «повторить» неотделяемое: Er wiederholt die Frage.<br><b>Две приставки:</b> решающей является первая приставка. Если она отделяемая, глагол остаётся отделяемым: <g>vorbereiten</g> – Ich bereite die Rede vor (причастие: vorbereitet; инфинитив: vorzubereiten). Так же <g>anerkennen</g> – Er erkennt die Leistung an (anerkannt; anzuerkennen)."
    }
  },
  {
    "id": "redewiedergabe",
    "title": {"de": "Möglichkeiten der Redewiedergabe", "en": "Ways of reporting speech", "uk": "Способи передачі чужого мовлення", "ru": "Способы передачи чужой речи"},
    "explanation": {
      "de": "<b>Mit der Redewiedergabe berichtest du, was andere gesagt haben.</b><br>Du kannst den <b>Konjunktiv I</b> benutzen: <g>Er sagt, er habe keine Zeit.</g> Der Konjunktiv I zeigt: Ich gebe die Aussage nur wieder und bestätige sie nicht selbst. Alternativen sind <b>dass-Sätze</b> mit Verben wie <g>behaupten, betonen, erklären</g> und Wendungen wie <g>laut, zufolge, nach Ansicht von</g>.<br>Beispiel: Der Minister sagte, die Lage <g>sei</g> stabil.",
      "en": "<b>Reported speech lets you report what others have said.</b><br>You can use the <b>Konjunktiv I</b>: <g>Er sagt, er habe keine Zeit.</g> The Konjunktiv I signals: I am only reporting the statement and not confirming it myself. Alternatives are <b>dass-clauses</b> with verbs such as <g>behaupten, betonen, erklären</g> and phrases such as <g>laut, zufolge, nach Ansicht von</g>.<br>Example: Der Minister sagte, die Lage <g>sei</g> stabil.<br>The minister said the situation was stable.",
      "uk": "<b>Переказ чужого мовлення дає змогу повідомити, що сказали інші.</b><br>Можна вжити <b>Konjunktiv I</b>: <g>Er sagt, er habe keine Zeit.</g> Konjunktiv I показує: я лише переказую слова й сам їх не підтверджую. Альтернативи — <b>речення з dass</b> із дієсловами на кшталт <g>behaupten, betonen, erklären</g> та звороти <g>laut, zufolge, nach Ansicht von</g>.<br>Приклад: Der Minister sagte, die Lage <g>sei</g> stabil.<br>Міністр сказав, що ситуація стабільна.",
      "ru": "<b>Передача чужой речи позволяет сообщить, что сказали другие.</b><br>Можно употребить <b>Konjunktiv I</b>: <g>Er sagt, er habe keine Zeit.</g> Konjunktiv I показывает: я лишь пересказываю слова и сам их не подтверждаю. Альтернативы — <b>придаточные с dass</b> с глаголами вроде <g>behaupten, betonen, erklären</g> и обороты <g>laut, zufolge, nach Ansicht von</g>.<br>Пример: Der Minister sagte, die Lage <g>sei</g> stabil.<br>Министр сказал, что ситуация стабильна."
    },
    "rule": {
      "de": "<b>1. Die Möglichkeiten im Überblick</b><br><table><tr><th>Mittel</th><th>Beispiel</th></tr><tr><td>Konjunktiv I</td><td>Er sagt, er <g>habe</g> keine Zeit.</td></tr><tr><td>dass-Satz (Indikativ)</td><td>Er sagt, <g>dass</g> er keine Zeit <g>hat</g>.</td></tr><tr><td><g>laut</g> / <g>zufolge</g> / <g>nach Ansicht von</g></td><td><g>Laut</g> dem Bericht steigen die Preise.</td></tr><tr><td><g>sollen</g> / <g>wollen</g></td><td>Die Preise <g>sollen</g> steigen.</td></tr></table><br><br>Der Konjunktiv I ist typisch für Zeitungen, Nachrichten und wissenschaftliche Texte. In der gesprochenen Sprache benutzt man oft den Indikativ.<br><br><b>2. Konjunktiv I: Formen</b><br>Der Konjunktiv I wird vom Infinitiv-Stamm gebildet: Stamm + <b>-e</b>, <b>-est</b>, <b>-e</b>, <b>-en</b>, <b>-et</b>, <b>-en</b>. Am häufigsten braucht man die 3. Person Singular: <g>er habe</g>, <g>er komme</g>, <g>er könne</g>, <g>er werde</g>. Bei Verben mit Vokalwechsel gibt es keinen Wechsel: <g>er fahre</g> (nicht: fährt), <g>er lese</g> (nicht: liest). Besonders ist <g>sein</g>: <g>ich sei, du seiest, er sei, wir seien, ihr seiet, sie seien</g>.<br><br><b>Ersatzform:</b> Ist der Konjunktiv I mit dem Indikativ identisch (zum Beispiel <g>ich habe</g>, <g>sie haben</g>), benutzt man den Konjunktiv II: <g>Sie sagen, sie hätten keine Zeit.</g> Bei Verben ohne eigene Konjunktiv-II-Form steht <g>würde</g> + Infinitiv.<br><br><b>3. Zeitstufen</b><br><table><tr><th>Zeitbezug</th><th>Form und Beispiel</th></tr><tr><td>gleichzeitig</td><td>Konjunktiv I Präsens:<br>Er sagte, er <g>habe</g> Kopfschmerzen.</td></tr><tr><td>vorzeitig</td><td><g>habe</g> / <g>sei</g> + Partizip II:<br>Er sagte, er <g>sei</g> krank <g>gewesen</g>.</td></tr><tr><td>nachzeitig</td><td><g>werde</g> + Infinitiv:<br>Er sagte, er <g>werde</g> morgen <g>kommen</g>.</td></tr></table><br><br>Die Zeitform des Einleitungsverbs spielt keine Rolle: <g>Er sagt</g> / <g>sagte</g> / <g>hat gesagt</g>, er sei krank gewesen.<br><br><b>4. Fragen und Aufforderungen</b><br><b>Entscheidungsfragen</b> werden mit <g>ob</g> wiedergegeben, <b>W-Fragen</b> mit dem Fragewort. <b>Aufforderungen</b> werden mit <g>sollen</g> oder <g>mögen</g> im Konjunktiv I ausgedrückt. Pronomen und Orts- und Zeitangaben passen sich der neuen Sprechsituation an.<br><br>„Kommst du morgen?“ → Sie fragte ihn, <g>ob</g> er morgen <g>komme</g>.<br>„Wann fängt der Kurs an?“ → Er wollte wissen, <g>wann</g> der Kurs <g>anfange</g>.<br>„Warte hier!“ → Sie sagte ihm, er <g>solle</g> hier <g>warten</g>.<br><br><b>5. Redewiedergabe ohne Konjunktiv I</b><br><b>Laut</b> + Dativ oder Genitiv, <b>zufolge</b> (nachgestellt + Dativ), <b>nach Angaben / Aussage / Ansicht von</b> + Dativ nennen die Quelle. Danach steht der Indikativ. Mit <b>sollen</b> gibst du ein Gerücht oder eine Meldung wieder, mit <b>wollen</b> eine Behauptung der Person selbst.<br><br><g>Laut</g> dem Bericht steigen die Preise.<br>Dem Bericht <g>zufolge</g> steigen die Preise.<br><g>Nach Ansicht der Experten</g> ist die Lage ernst.<br>Die Preise <g>sollen</g> steigen.<br><br>Verben des Sagens unterscheiden sich im Ton: <g>erklären, mitteilen, berichten</g> sind neutral, <g>behaupten, bestreiten</g> zeigen Zweifel, <g>betonen, versichern</g> zeigen Nachdruck.<br><br><b>6. Wirkung</b><br>Der Konjunktiv I sagt nichts darüber, ob die Aussage wahr oder falsch ist. Er markiert nur, dass sie von jemand anderem stammt. Wenn du Zweifel zeigen willst, benutzt du den Konjunktiv II oder Wörter wie <g>angeblich</g>: <g>Er sagt, er hätte das Auto nie gesehen.</g>",
      "en": "<b>1. Overview of the options</b><br><table><tr><th>Means</th><th>Example</th></tr><tr><td>Konjunktiv I</td><td>Er sagt, er <g>habe</g> keine Zeit.</td></tr><tr><td>dass-Satz (Indikativ)</td><td>Er sagt, <g>dass</g> er keine Zeit <g>hat</g>.</td></tr><tr><td><g>laut</g> / <g>zufolge</g> / <g>nach Ansicht von</g></td><td><g>Laut</g> dem Bericht steigen die Preise.</td></tr><tr><td><g>sollen</g> / <g>wollen</g></td><td>Die Preise <g>sollen</g> steigen.</td></tr></table><br><br>The Konjunktiv I is typical of newspapers, news and academic texts. In spoken language the indicative is often used.<br><br><b>2. Konjunktiv I: forms</b><br>The Konjunktiv I is formed from the infinitive stem: stem + <b>-e</b>, <b>-est</b>, <b>-e</b>, <b>-en</b>, <b>-et</b>, <b>-en</b>. The 3rd person singular is needed most often: <g>er habe</g>, <g>er komme</g>, <g>er könne</g>, <g>er werde</g>. Verbs with a vowel change have no change here: <g>er fahre</g> (not: fährt), <g>er lese</g> (not: liest). <g>Sein</g> is special: <g>ich sei, du seiest, er sei, wir seien, ihr seiet, sie seien</g>.<br><br><b>Substitute form:</b> If the Konjunktiv I is identical with the indicative (for example <g>ich habe</g>, <g>sie haben</g>), the Konjunktiv II is used: <g>Sie sagen, sie hätten keine Zeit.</g> For verbs without a distinct Konjunktiv II form, <g>würde</g> + infinitive is used.<br><br><b>3. Tenses</b><br><table><tr><th>Time reference</th><th>Form and example</th></tr><tr><td>simultaneous</td><td>Konjunktiv I Präsens:<br>Er sagte, er <g>habe</g> Kopfschmerzen.</td></tr><tr><td>prior</td><td><g>habe</g> / <g>sei</g> + Partizip II:<br>Er sagte, er <g>sei</g> krank <g>gewesen</g>.</td></tr><tr><td>subsequent</td><td><g>werde</g> + Infinitiv:<br>Er sagte, er <g>werde</g> morgen <g>kommen</g>.</td></tr></table><br><br>The tense of the introductory verb does not matter: <g>Er sagt</g> / <g>sagte</g> / <g>hat gesagt</g>, er sei krank gewesen.<br><br><b>4. Questions and requests</b><br><b>Yes-no questions</b> are reported with <g>ob</g>, <b>wh-questions</b> with the question word. <b>Requests</b> are expressed with <g>sollen</g> or <g>mögen</g> in the Konjunktiv I. Pronouns and place or time expressions adapt to the new speaking situation.<br><br>“Kommst du morgen?” → Sie fragte ihn, <g>ob</g> er morgen <g>komme</g>.<br>“Are you coming tomorrow?” → She asked him whether he was coming tomorrow.<br>“Wann fängt der Kurs an?” → Er wollte wissen, <g>wann</g> der Kurs <g>anfange</g>.<br>“When does the course start?” → He wanted to know when the course started.<br>“Warte hier!” → Sie sagte ihm, er <g>solle</g> hier <g>warten</g>.<br>“Wait here!” → She told him to wait here.<br><br><b>5. Reported speech without Konjunktiv I</b><br><b>Laut</b> + dative or genitive, <b>zufolge</b> (after the noun + dative) and <b>nach Angaben / Aussage / Ansicht von</b> + dative name the source. The indicative follows. With <b>sollen</b> you report a rumour or a news item, with <b>wollen</b> a claim made by the person themselves.<br><br><g>Laut</g> dem Bericht steigen die Preise.<br>According to the report, prices are rising.<br>Dem Bericht <g>zufolge</g> steigen die Preise.<br>According to the report, prices are rising.<br><g>Nach Ansicht der Experten</g> ist die Lage ernst.<br>In the experts' view the situation is serious.<br>Die Preise <g>sollen</g> steigen.<br>Prices are said to be rising.<br><br>Verbs of saying differ in tone: <g>erklären, mitteilen, berichten</g> are neutral, <g>behaupten, bestreiten</g> show doubt, <g>betonen, versichern</g> show emphasis.<br><br><b>6. Effect</b><br>The Konjunktiv I says nothing about whether the statement is true or false. It only marks that it comes from someone else. If you want to show doubt, use the Konjunktiv II or words such as <g>angeblich</g>: <g>Er sagt, er hätte das Auto nie gesehen.</g>",
      "uk": "<b>1. Огляд можливостей</b><br><table><tr><th>Засіб</th><th>Приклад</th></tr><tr><td>Konjunktiv I</td><td>Er sagt, er <g>habe</g> keine Zeit.</td></tr><tr><td>dass-Satz (Indikativ)</td><td>Er sagt, <g>dass</g> er keine Zeit <g>hat</g>.</td></tr><tr><td><g>laut</g> / <g>zufolge</g> / <g>nach Ansicht von</g></td><td><g>Laut</g> dem Bericht steigen die Preise.</td></tr><tr><td><g>sollen</g> / <g>wollen</g></td><td>Die Preise <g>sollen</g> steigen.</td></tr></table><br><br>Konjunktiv I типовий для газет, новин і наукових текстів. У розмовній мові часто вживають індикатив.<br><br><b>2. Konjunktiv I: форми</b><br>Konjunktiv I утворюється від основи інфінітива: основа + <b>-e</b>, <b>-est</b>, <b>-e</b>, <b>-en</b>, <b>-et</b>, <b>-en</b>. Найчастіше потрібна 3-тя особа однини: <g>er habe</g>, <g>er komme</g>, <g>er könne</g>, <g>er werde</g>. У дієсловах зі зміною голосного зміни немає: <g>er fahre</g> (не fährt), <g>er lese</g> (не liest). Особливе дієслово <g>sein</g>: <g>ich sei, du seiest, er sei, wir seien, ihr seiet, sie seien</g>.<br><br><b>Замінна форма:</b> якщо Konjunktiv I збігається з індикативом (наприклад, <g>ich habe</g>, <g>sie haben</g>), вживають Konjunktiv II: <g>Sie sagen, sie hätten keine Zeit.</g> У дієслів без власної форми Konjunktiv II вживають <g>würde</g> + інфінітив.<br><br><b>3. Часові форми</b><br><table><tr><th>Часове співвідношення</th><th>Форма й приклад</th></tr><tr><td>одночасність</td><td>Konjunktiv I Präsens:<br>Er sagte, er <g>habe</g> Kopfschmerzen.</td></tr><tr><td>передування</td><td><g>habe</g> / <g>sei</g> + Partizip II:<br>Er sagte, er <g>sei</g> krank <g>gewesen</g>.</td></tr><tr><td>наступність</td><td><g>werde</g> + Infinitiv:<br>Er sagte, er <g>werde</g> morgen <g>kommen</g>.</td></tr></table><br><br>Час вступного дієслова не має значення: <g>Er sagt</g> / <g>sagte</g> / <g>hat gesagt</g>, er sei krank gewesen.<br><br><b>4. Питання й заклики</b><br><b>Питання «так / ні»</b> передаються через <g>ob</g>, <b>питання з питальним словом</b> — через це слово. <b>Прохання й накази</b> передаються через <g>sollen</g> або <g>mögen</g> у Konjunktiv I. Займенники та позначення місця й часу пристосовуються до нової ситуації мовлення.<br><br>«Kommst du morgen?» → Sie fragte ihn, <g>ob</g> er morgen <g>komme</g>.<br>«Ти завтра прийдеш?» → Вона спитала його, чи він прийде завтра.<br>«Wann fängt der Kurs an?» → Er wollte wissen, <g>wann</g> der Kurs <g>anfange</g>.<br>«Коли починається курс?» → Він хотів знати, коли починається курс.<br>«Warte hier!» → Sie sagte ihm, er <g>solle</g> hier <g>warten</g>.<br>«Чекай тут!» → Вона сказала йому чекати тут.<br><br><b>5. Переказ без Konjunktiv I</b><br><b>Laut</b> + давальний або родовий, <b>zufolge</b> (після іменника + давальний), <b>nach Angaben / Aussage / Ansicht von</b> + давальний називають джерело. Після них стоїть індикатив. За допомогою <b>sollen</b> передають чутку чи повідомлення, за допомогою <b>wollen</b> — твердження самої особи.<br><br><g>Laut</g> dem Bericht steigen die Preise.<br>Згідно зі звітом ціни зростають.<br>Dem Bericht <g>zufolge</g> steigen die Preise.<br>Згідно зі звітом ціни зростають.<br><g>Nach Ansicht der Experten</g> ist die Lage ernst.<br>На думку експертів, ситуація серйозна.<br>Die Preise <g>sollen</g> steigen.<br>Кажуть, що ціни зростають.<br><br>Дієслова мовлення різняться за тоном: <g>erklären, mitteilen, berichten</g> нейтральні, <g>behaupten, bestreiten</g> виражають сумнів, <g>betonen, versichern</g> — наголос.<br><br><b>6. Вплив</b><br>Konjunktiv I нічого не говорить про те, правдиве чи хибне твердження. Він лише позначає, що воно походить від когось іншого. Щоб виразити сумнів, вживають Konjunktiv II або слова на кшталт <g>angeblich</g>: <g>Er sagt, er hätte das Auto nie gesehen.</g>",
      "ru": "<b>1. Обзор возможностей</b><br><table><tr><th>Средство</th><th>Пример</th></tr><tr><td>Konjunktiv I</td><td>Er sagt, er <g>habe</g> keine Zeit.</td></tr><tr><td>dass-Satz (Indikativ)</td><td>Er sagt, <g>dass</g> er keine Zeit <g>hat</g>.</td></tr><tr><td><g>laut</g> / <g>zufolge</g> / <g>nach Ansicht von</g></td><td><g>Laut</g> dem Bericht steigen die Preise.</td></tr><tr><td><g>sollen</g> / <g>wollen</g></td><td>Die Preise <g>sollen</g> steigen.</td></tr></table><br><br>Konjunktiv I типичен для газет, новостей и научных текстов. В разговорной речи часто употребляют индикатив.<br><br><b>2. Konjunktiv I: формы</b><br>Konjunktiv I образуется от основы инфинитива: основа + <b>-e</b>, <b>-est</b>, <b>-e</b>, <b>-en</b>, <b>-et</b>, <b>-en</b>. Чаще всего нужна 3-е лицо единственного числа: <g>er habe</g>, <g>er komme</g>, <g>er könne</g>, <g>er werde</g>. У глаголов с чередованием гласной чередования нет: <g>er fahre</g> (не fährt), <g>er lese</g> (не liest). Особый глагол <g>sein</g>: <g>ich sei, du seiest, er sei, wir seien, ihr seiet, sie seien</g>.<br><br><b>Замещающая форма:</b> если Konjunktiv I совпадает с индикативом (например, <g>ich habe</g>, <g>sie haben</g>), употребляют Konjunktiv II: <g>Sie sagen, sie hätten keine Zeit.</g> У глаголов без собственной формы Konjunktiv II употребляют <g>würde</g> + инфинитив.<br><br><b>3. Временные формы</b><br><table><tr><th>Временное соотношение</th><th>Форма и пример</th></tr><tr><td>одновременность</td><td>Konjunktiv I Präsens:<br>Er sagte, er <g>habe</g> Kopfschmerzen.</td></tr><tr><td>предшествование</td><td><g>habe</g> / <g>sei</g> + Partizip II:<br>Er sagte, er <g>sei</g> krank <g>gewesen</g>.</td></tr><tr><td>следование</td><td><g>werde</g> + Infinitiv:<br>Er sagte, er <g>werde</g> morgen <g>kommen</g>.</td></tr></table><br><br>Время вводящего глагола значения не имеет: <g>Er sagt</g> / <g>sagte</g> / <g>hat gesagt</g>, er sei krank gewesen.<br><br><b>4. Вопросы и призывы</b><br><b>Вопросы «да / нет»</b> передаются через <g>ob</g>, <b>вопросы с вопросительным словом</b> — через это слово. <b>Просьбы и приказы</b> передаются через <g>sollen</g> или <g>mögen</g> в Konjunktiv I. Местоимения и обозначения места и времени приспосабливаются к новой речевой ситуации.<br><br>«Kommst du morgen?» → Sie fragte ihn, <g>ob</g> er morgen <g>komme</g>.<br>«Ты завтра придёшь?» → Она спросила его, придёт ли он завтра.<br>«Wann fängt der Kurs an?» → Er wollte wissen, <g>wann</g> der Kurs <g>anfange</g>.<br>«Когда начинается курс?» → Он хотел знать, когда начинается курс.<br>«Warte hier!» → Sie sagte ihm, er <g>solle</g> hier <g>warten</g>.<br>«Жди здесь!» → Она сказала ему ждать здесь.<br><br><b>5. Передача речи без Konjunktiv I</b><br><b>Laut</b> + дательный или родительный, <b>zufolge</b> (после существительного + дательный), <b>nach Angaben / Aussage / Ansicht von</b> + дательный называют источник. После них стоит индикатив. С помощью <b>sollen</b> передают слух или сообщение, с помощью <b>wollen</b> — утверждение самого лица.<br><br><g>Laut</g> dem Bericht steigen die Preise.<br>Согласно отчёту, цены растут.<br>Dem Bericht <g>zufolge</g> steigen die Preise.<br>Согласно отчёту, цены растут.<br><g>Nach Ansicht der Experten</g> ist die Lage ernst.<br>По мнению экспертов, ситуация серьёзная.<br>Die Preise <g>sollen</g> steigen.<br>Говорят, что цены растут.<br><br>Глаголы речи различаются по тону: <g>erklären, mitteilen, berichten</g> нейтральные, <g>behaupten, bestreiten</g> выражают сомнение, <g>betonen, versichern</g> — нажим.<br><br><b>6. Эффект</b><br>Konjunktiv I ничего не говорит о том, истинно высказывание или ложно. Он лишь отмечает, что оно исходит от кого-то другого. Чтобы выразить сомнение, употребляют Konjunktiv II или слова вроде <g>angeblich</g>: <g>Er sagt, er hätte das Auto nie gesehen.</g>"
    }
  },
  {
    "id": "nominal_verbalstil",
    "title": {"de": "Nominal- und Verbalstil", "en": "Nominal and verbal style", "uk": "Номінальний і вербальний стиль", "ru": "Номинальный и вербальный стиль"},
    "explanation": {
      "de": "<b>Dieselbe Information kannst du mit Verben oder mit Nomen ausdrücken.</b><br>Der <b>Verbalstil</b> benutzt Verben und Nebensätze: <g>Weil</g> die Preise <g>steigen</g>, … Der <b>Nominalstil</b> ersetzt sie durch Nomen und Präpositionen: <g>Wegen des Anstiegs</g> der Preise … Er wirkt knapper und formeller und ist typisch für Fachtexte, Nachrichten und Behördensprache.<br>Beispiel: <g>Weil</g> die Preise <g>steigen</g>, kaufen weniger Leute ein. – <g>Wegen des Anstiegs</g> der Preise kaufen weniger Leute ein.",
      "en": "<b>You can express the same information with verbs or with nouns.</b><br>The <b>verbal style</b> uses verbs and subordinate clauses: <g>Weil</g> die Preise <g>steigen</g>, … The <b>nominal style</b> replaces them with nouns and prepositions: <g>Wegen des Anstiegs</g> der Preise … It sounds more concise and more formal and is typical of technical texts, news and official language.<br>Example: <g>Weil</g> die Preise <g>steigen</g>, kaufen weniger Leute ein. – <g>Wegen des Anstiegs</g> der Preise kaufen weniger Leute ein.<br>Because prices are rising, fewer people shop. – Because of the rise in prices, fewer people shop.",
      "uk": "<b>Ту саму інформацію можна передати дієсловами або іменниками.</b><br><b>Дієслівний стиль</b> вживає дієслова й підрядні речення: <g>Weil</g> die Preise <g>steigen</g>, … <b>Іменний стиль</b> замінює їх іменниками й прийменниками: <g>Wegen des Anstiegs</g> der Preise … Він звучить стисліше й офіційніше та типовий для фахових текстів, новин і мови установ.<br>Приклад: <g>Weil</g> die Preise <g>steigen</g>, kaufen weniger Leute ein. – <g>Wegen des Anstiegs</g> der Preise kaufen weniger Leute ein.<br>Оскільки ціни зростають, люди купують менше. – Через зростання цін люди купують менше.",
      "ru": "<b>Одну и ту же информацию можно передать глаголами или существительными.</b><br><b>Глагольный стиль</b> использует глаголы и придаточные предложения: <g>Weil</g> die Preise <g>steigen</g>, … <b>Именной стиль</b> заменяет их существительными и предлогами: <g>Wegen des Anstiegs</g> der Preise … Он звучит короче и официальнее и типичен для специальных текстов, новостей и языка учреждений.<br>Пример: <g>Weil</g> die Preise <g>steigen</g>, kaufen weniger Leute ein. – <g>Wegen des Anstiegs</g> der Preise kaufen weniger Leute ein.<br>Поскольку цены растут, люди покупают меньше. – Из-за роста цен люди покупают меньше."
    },
    "rule": {
      "de": "<b>1. Vergleich der Stile</b><br><table><tr><th>Verbalstil</th><th>Nominalstil</th></tr><tr><td>Die Firma <g>entwickelt</g> ein neues Produkt.</td><td>Die <g>Entwicklung</g> eines neuen Produkts …</td></tr><tr><td><g>Weil</g> es <g>stürmt</g>, fällt das Fest aus.</td><td><g>Wegen des Sturms</g> fällt das Fest aus.</td></tr><tr><td>Die Preise <g>steigen</g> <g>schnell</g>.</td><td>Der <g>schnelle Anstieg</g> der Preise …</td></tr><tr><td><g>Nachdem</g> er <g>angekommen war</g>, rief er an.</td><td><g>Nach</g> seiner <g>Ankunft</g> rief er an.</td></tr></table><br><br>Der Nominalstil ist dichter: Er braucht weniger Wörter, nennt aber oft nicht, wer etwas tut oder wann genau.<br><br><b>2. Vom Verb zum Nomen</b><br><b>1. Verb → Nomen.</b> Typische Endungen sind <g>-ung</g> (<g>entwickeln</g> → <g>die Entwicklung</g>), <g>-e</g> (<g>fragen</g> → <g>die Frage</g>), <g>-t</g> (<g>fahren</g> → <g>die Fahrt</g>), der Infinitiv als Nomen (<g>lesen</g> → <g>das Lesen</g>) und der Stamm, oft mit Vokalwechsel (<g>steigen</g> → <g>der Anstieg</g>, <g>verbieten</g> → <g>das Verbot</g>).<br><b>2. Subjekt → Genitivattribut</b> oder <g>von</g> + Dativ: <g>Die Preise steigen.</g> → <g>der Anstieg der Preise</g>.<br><b>3. Akkusativobjekt → Genitivattribut:</b> <g>Man plant das Projekt.</g> → <g>die Planung des Projekts</g>.<br><b>4. Adverb → Adjektiv:</b> <g>schnell steigen</g> → <g>der schnelle Anstieg</g>.<br><b>5. Konnektor → Präposition:</b> <g>weil</g> → <g>wegen</g>, <g>obwohl</g> → <g>trotz</g>, <g>nachdem</g> → <g>nach</g> (siehe die Themen zur Nominalisierung).<br><br><b>3. Der Genitiv: Subjekt oder Objekt?</b><br>Ein Genitiv nach dem Nomen kann ein Subjekt oder ein Objekt ersetzen. Das ist oft nicht eindeutig: <g>die Kritik des Chefs</g> kann bedeuten, dass der Chef kritisiert, oder dass er kritisiert wird. Deutlicher wird es mit <g>von</g>, <g>durch</g> oder einer anderen Präposition.<br><br><g>die Kritik</g> der Mitarbeiter <g>an</g> dem Chef<br><g>die Kritik</g> des Chefs <g>durch</g> die Presse<br><g>der Bau</g> <g>von</g> Wohnungen<br><br><b>4. Wann welcher Stil?</b><br><b>Nominalstil:</b> Fachtexte, Gutachten, Nachrichten, Verträge, wissenschaftliche Arbeiten – dort, wo es auf Kürze und Sachlichkeit ankommt.<br><b>Verbalstil:</b> Gespräche, Briefe, Erklärungen, Erzählungen – dort, wo Verständlichkeit und Lebendigkeit wichtig sind.<br><b>Vorsicht:</b> Zu viele Nomen hintereinander machen Sätze schwer lesbar (<g>die Durchführung der Überprüfung der Unterlagen</g>). Dann ist ein Verb besser: <g>die Unterlagen überprüfen</g>.",
      "en": "<b>1. Comparing the styles</b><br><table><tr><th>Verbal style</th><th>Nominal style</th></tr><tr><td>Die Firma <g>entwickelt</g> ein neues Produkt.</td><td>Die <g>Entwicklung</g> eines neuen Produkts …</td></tr><tr><td><g>Weil</g> es <g>stürmt</g>, fällt das Fest aus.</td><td><g>Wegen des Sturms</g> fällt das Fest aus.</td></tr><tr><td>Die Preise <g>steigen</g> <g>schnell</g>.</td><td>Der <g>schnelle Anstieg</g> der Preise …</td></tr><tr><td><g>Nachdem</g> er <g>angekommen war</g>, rief er an.</td><td><g>Nach</g> seiner <g>Ankunft</g> rief er an.</td></tr></table><br><br>The nominal style is denser: it needs fewer words, but often does not say who does something or exactly when.<br><br><b>2. From verb to noun</b><br><b>1. Verb → noun.</b> Typical endings are <g>-ung</g> (<g>entwickeln</g> → <g>die Entwicklung</g>), <g>-e</g> (<g>fragen</g> → <g>die Frage</g>), <g>-t</g> (<g>fahren</g> → <g>die Fahrt</g>), the infinitive as a noun (<g>lesen</g> → <g>das Lesen</g>) and the stem, often with a vowel change (<g>steigen</g> → <g>der Anstieg</g>, <g>verbieten</g> → <g>das Verbot</g>).<br><b>2. Subject → genitive attribute</b> or <g>von</g> + dative: <g>Die Preise steigen.</g> → <g>der Anstieg der Preise</g>.<br><b>3. Accusative object → genitive attribute:</b> <g>Man plant das Projekt.</g> → <g>die Planung des Projekts</g>.<br><b>4. Adverb → adjective:</b> <g>schnell steigen</g> → <g>der schnelle Anstieg</g>.<br><b>5. Connector → preposition:</b> <g>weil</g> → <g>wegen</g>, <g>obwohl</g> → <g>trotz</g>, <g>nachdem</g> → <g>nach</g> (see the topics on nominalisation).<br><br><b>3. The genitive: subject or object?</b><br>A genitive after a noun can stand for a subject or an object. This is often ambiguous: <g>die Kritik des Chefs</g> can mean that the boss criticises or that he is criticised. It becomes clearer with <g>von</g>, <g>durch</g> or another preposition.<br><br><g>die Kritik</g> der Mitarbeiter <g>an</g> dem Chef<br>the employees' criticism of the boss<br><g>die Kritik</g> des Chefs <g>durch</g> die Presse<br>the criticism of the boss by the press<br><g>der Bau</g> <g>von</g> Wohnungen<br>the construction of flats<br><br><b>4. When to use which style?</b><br><b>Nominal style:</b> technical texts, expert reports, news, contracts, academic papers – wherever brevity and objectivity matter.<br><b>Verbal style:</b> conversations, letters, explanations, narratives – wherever clarity and liveliness matter.<br><b>Caution:</b> too many nouns in a row make sentences hard to read (<g>die Durchführung der Überprüfung der Unterlagen</g>). A verb is then better: <g>die Unterlagen überprüfen</g>.",
      "uk": "<b>1. Порівняння стилів</b><br><table><tr><th>Дієслівний стиль</th><th>Іменний стиль</th></tr><tr><td>Die Firma <g>entwickelt</g> ein neues Produkt.</td><td>Die <g>Entwicklung</g> eines neuen Produkts …</td></tr><tr><td><g>Weil</g> es <g>stürmt</g>, fällt das Fest aus.</td><td><g>Wegen des Sturms</g> fällt das Fest aus.</td></tr><tr><td>Die Preise <g>steigen</g> <g>schnell</g>.</td><td>Der <g>schnelle Anstieg</g> der Preise …</td></tr><tr><td><g>Nachdem</g> er <g>angekommen war</g>, rief er an.</td><td><g>Nach</g> seiner <g>Ankunft</g> rief er an.</td></tr></table><br><br>Іменний стиль щільніший: він потребує менше слів, але часто не називає, хто що робить або коли саме.<br><br><b>2. Від дієслова до іменника</b><br><b>1. Дієслово → іменник.</b> Типові закінчення: <g>-ung</g> (<g>entwickeln</g> → <g>die Entwicklung</g>), <g>-e</g> (<g>fragen</g> → <g>die Frage</g>), <g>-t</g> (<g>fahren</g> → <g>die Fahrt</g>), інфінітив як іменник (<g>lesen</g> → <g>das Lesen</g>) та основа, часто зі зміною голосного (<g>steigen</g> → <g>der Anstieg</g>, <g>verbieten</g> → <g>das Verbot</g>).<br><b>2. Підмет → означення в родовому відмінку</b> або <g>von</g> + давальний: <g>Die Preise steigen.</g> → <g>der Anstieg der Preise</g>.<br><b>3. Додаток у знахідному → означення в родовому:</b> <g>Man plant das Projekt.</g> → <g>die Planung des Projekts</g>.<br><b>4. Прислівник → прикметник:</b> <g>schnell steigen</g> → <g>der schnelle Anstieg</g>.<br><b>5. Сполучник → прийменник:</b> <g>weil</g> → <g>wegen</g>, <g>obwohl</g> → <g>trotz</g>, <g>nachdem</g> → <g>nach</g> (див. теми про номіналізацію).<br><br><b>3. Родовий відмінок: підмет чи додаток?</b><br>Родовий відмінок після іменника може заміняти підмет або додаток. Це часто неоднозначно: <g>die Kritik des Chefs</g> може означати, що шеф критикує або що критикують його. Чіткіше стає з <g>von</g>, <g>durch</g> або іншим прийменником.<br><br><g>die Kritik</g> der Mitarbeiter <g>an</g> dem Chef<br>критика працівників на адресу шефа<br><g>die Kritik</g> des Chefs <g>durch</g> die Presse<br>критика шефа з боку преси<br><g>der Bau</g> <g>von</g> Wohnungen<br>будівництво квартир<br><br><b>4. Коли який стиль?</b><br><b>Іменний стиль:</b> фахові тексти, експертні висновки, новини, договори, наукові роботи — там, де важливі стислість і обʼєктивність.<br><b>Дієслівний стиль:</b> розмови, листи, пояснення, розповіді — там, де важливі зрозумілість і жвавість.<br><b>Обережно:</b> забагато іменників поспіль ускладнюють читання (<g>die Durchführung der Überprüfung der Unterlagen</g>). Тоді краще дієслово: <g>die Unterlagen überprüfen</g>.",
      "ru": "<b>1. Сравнение стилей</b><br><table><tr><th>Глагольный стиль</th><th>Именной стиль</th></tr><tr><td>Die Firma <g>entwickelt</g> ein neues Produkt.</td><td>Die <g>Entwicklung</g> eines neuen Produkts …</td></tr><tr><td><g>Weil</g> es <g>stürmt</g>, fällt das Fest aus.</td><td><g>Wegen des Sturms</g> fällt das Fest aus.</td></tr><tr><td>Die Preise <g>steigen</g> <g>schnell</g>.</td><td>Der <g>schnelle Anstieg</g> der Preise …</td></tr><tr><td><g>Nachdem</g> er <g>angekommen war</g>, rief er an.</td><td><g>Nach</g> seiner <g>Ankunft</g> rief er an.</td></tr></table><br><br>Именной стиль плотнее: он требует меньше слов, но часто не называет, кто что делает или когда именно.<br><br><b>2. От глагола к существительному</b><br><b>1. Глагол → существительное.</b> Типичные окончания: <g>-ung</g> (<g>entwickeln</g> → <g>die Entwicklung</g>), <g>-e</g> (<g>fragen</g> → <g>die Frage</g>), <g>-t</g> (<g>fahren</g> → <g>die Fahrt</g>), инфинитив как существительное (<g>lesen</g> → <g>das Lesen</g>) и основа, часто с чередованием гласной (<g>steigen</g> → <g>der Anstieg</g>, <g>verbieten</g> → <g>das Verbot</g>).<br><b>2. Подлежащее → определение в родительном падеже</b> или <g>von</g> + дательный: <g>Die Preise steigen.</g> → <g>der Anstieg der Preise</g>.<br><b>3. Дополнение в винительном → определение в родительном:</b> <g>Man plant das Projekt.</g> → <g>die Planung des Projekts</g>.<br><b>4. Наречие → прилагательное:</b> <g>schnell steigen</g> → <g>der schnelle Anstieg</g>.<br><b>5. Союз → предлог:</b> <g>weil</g> → <g>wegen</g>, <g>obwohl</g> → <g>trotz</g>, <g>nachdem</g> → <g>nach</g> (см. темы о номинализации).<br><br><b>3. Родительный падеж: подлежащее или дополнение?</b><br>Родительный падеж после существительного может заменять подлежащее или дополнение. Это часто неоднозначно: <g>die Kritik des Chefs</g> может значить, что шеф критикует или что критикуют его. Яснее становится с <g>von</g>, <g>durch</g> или другим предлогом.<br><br><g>die Kritik</g> der Mitarbeiter <g>an</g> dem Chef<br>критика сотрудников в адрес шефа<br><g>die Kritik</g> des Chefs <g>durch</g> die Presse<br>критика шефа со стороны прессы<br><g>der Bau</g> <g>von</g> Wohnungen<br>строительство квартир<br><br><b>4. Когда какой стиль?</b><br><b>Именной стиль:</b> специальные тексты, экспертные заключения, новости, договоры, научные работы — там, где важны краткость и объективность.<br><b>Глагольный стиль:</b> разговоры, письма, объяснения, рассказы — там, где важны понятность и живость.<br><b>Осторожно:</b> слишком много существительных подряд затрудняют чтение (<g>die Durchführung der Überprüfung der Unterlagen</g>). Тогда лучше глагол: <g>die Unterlagen überprüfen</g>."
    }
  },
  {
    "id": "subjekt_objektsaetze",
    "title": {"de": "Subjekt- und Objektsätze", "en": "Subject and object clauses", "uk": "Підметові та додаткові речення", "ru": "Подлежащные и дополнительные предложения"},
    "explanation": {
      "de": "<b>Ein Nebensatz kann die Rolle von Subjekt oder Objekt übernehmen.</b><br>Der Nebensatz beginnt mit <g>dass, ob</g> oder einem Fragewort (<g>wer, was, wie, wo …</g>). Er kann auch ein Infinitiv mit <g>zu</g> sein. Ein <b>Subjektsatz</b> beantwortet die Frage „Wer / Was?“: <g>Wer fleißig lernt</g>, hat Erfolg. Ein <b>Objektsatz</b> ergänzt das Verb: Ich weiß nicht, <g>ob er kommt</g>. Im Hauptsatz steht oft ein Platzhalter: <g>Es</g> freut mich, <g>dass du da bist</g>.<br>Beispiel: <g>Es</g> freut mich, <g>dass du da bist</g>.",
      "en": "<b>A subordinate clause can take the role of subject or object.</b><br>The subordinate clause begins with <g>dass, ob</g> or a question word (<g>wer, was, wie, wo …</g>). It can also be an infinitive with <g>zu</g>. A <b>subject clause</b> answers the question “who / what?”: <g>Wer fleißig lernt</g>, hat Erfolg. An <b>object clause</b> complements the verb: Ich weiß nicht, <g>ob er kommt</g>. The main clause often contains a placeholder: <g>Es</g> freut mich, <g>dass du da bist</g>.<br>Example: <g>Es</g> freut mich, <g>dass du da bist</g>.<br>I am glad that you are here.",
      "uk": "<b>Підрядне речення може виконувати роль підмета або додатка.</b><br>Підрядне речення починається з <g>dass, ob</g> або питального слова (<g>wer, was, wie, wo …</g>). Воно може бути й інфінітивом із <g>zu</g>. <b>Підрядне підметове</b> відповідає на питання «хто / що?»: <g>Wer fleißig lernt</g>, hat Erfolg. <b>Підрядне додаткове</b> доповнює дієслово: Ich weiß nicht, <g>ob er kommt</g>. У головному реченні часто стоїть слово-замінник: <g>Es</g> freut mich, <g>dass du da bist</g>.<br>Приклад: <g>Es</g> freut mich, <g>dass du da bist</g>.<br>Я радий, що ти тут.",
      "ru": "<b>Придаточное предложение может выполнять роль подлежащего или дополнения.</b><br>Придаточное предложение начинается с <g>dass, ob</g> или вопросительного слова (<g>wer, was, wie, wo …</g>). Оно может быть и инфинитивом с <g>zu</g>. <b>Подлежащное придаточное</b> отвечает на вопрос «кто / что?»: <g>Wer fleißig lernt</g>, hat Erfolg. <b>Дополнительное придаточное</b> дополняет глагол: Ich weiß nicht, <g>ob er kommt</g>. В главном предложении часто стоит слово-заместитель: <g>Es</g> freut mich, <g>dass du da bist</g>.<br>Пример: <g>Es</g> freut mich, <g>dass du da bist</g>.<br>Я рад, что ты здесь."
    },
    "rule": {
      "de": "<b>1. Einleitung des Nebensatzes</b><br><table><tr><th>Einleitung</th><th>Verwendung und Beispiel</th></tr><tr><td><g>dass</g></td><td>Tatsache oder Aussage:<br>Ich weiß, <g>dass</g> er krank ist.</td></tr><tr><td><g>ob</g></td><td>Entscheidungsfrage:<br>Ich frage mich, <g>ob</g> er kommt.</td></tr><tr><td><g>w</g>-Fragewort</td><td>Informationsfrage:<br>Ich weiß nicht, <g>wann</g> er kommt.</td></tr><tr><td><g>wer</g> / <g>was</g></td><td>allgemein (Subjektsatz):<br><g>Wer</g> rastet, der rostet.</td></tr><tr><td><g>zu</g> + Infinitiv</td><td>gleiches Subjekt:<br>Er hofft, bald <g>zu gewinnen</g>.</td></tr></table><br><br><b>2. Subjektsätze</b><br>Subjektsätze stehen nach Verben und Ausdrücken wie <g>freuen, stimmen, gehören, scheinen, klar sein, wichtig sein</g>. Steht der Nebensatz am Satzanfang, folgt das Verb des Hauptsatzes direkt danach; der Platzhalter <g>es</g> entfällt. Steht er hinter dem Hauptsatz, ist <g>es</g> meist nötig.<br><br><g>Dass du kommst</g>, freut mich.<br><g>Es</g> freut mich, <g>dass du kommst</g>.<br><g>Ob er Recht hat</g>, ist noch unklar.<br><g>Wer zuerst kommt</g>, mahlt zuerst.<br><br><b>3. Objektsätze</b><br>Objektsätze ergänzen Verben wie <g>wissen, glauben, meinen, sagen, fragen, hoffen, vermuten</g>. Nach Verben des Sagens und Denkens kann <g>dass</g> wegfallen; dann gilt die Hauptsatzstellung (Verb auf Position 2): <g>Ich glaube, er kommt noch.</g> Bei Verben mit Präposition steht im Hauptsatz oft ein <b>Korrelat</b> (<g>darauf, davon, dafür …</g>).<br><br>Ich weiß, <g>dass</g> er krank <g>ist</g>.<br>Ich weiß nicht, <g>ob</g> er <g>kommt</g>.<br>Sie fragt, <g>wo</g> der Bahnhof <g>ist</g>.<br>Ich glaube, er <g>kommt</g> noch.<br><br><b>4. Das Korrelat</b><br>Bei Verben und Adjektiven mit fester Präposition kann im Hauptsatz ein Korrelat aus <b>da(r)</b> + Präposition stehen. Es ist oft fakultativ, bei einigen Verben aber üblich, zum Beispiel <g>abhängen von</g> und <g>sich verlassen auf</g>. Steht der Nebensatz vor dem Hauptsatz, ist das Korrelat meist nötig.<br><br>Ich freue mich (<g>darüber</g>), <g>dass</g> du <g>kommst</g>.<br>Es hängt <g>davon</g> ab, <g>ob</g> das Wetter <g>hält</g>.<br>Ich verlasse mich <g>darauf</g>, <g>dass</g> du pünktlich <g>bist</g>.<br><br><b>5. Nebensatz oder Infinitivsatz?</b><br>Bei <b>gleichem Subjekt</b> im Haupt- und Nebensatz steht oft ein Infinitiv mit <g>zu</g>. Bei <b>verschiedenen Subjekten</b> braucht man <g>dass</g>. Der Infinitivsatz steht nach Verben wie <g>hoffen, planen, beschließen, versuchen</g>.<br><br>Er hofft, die Prüfung <g>zu bestehen</g>.<br>Er hofft, <g>dass</g> sie die Prüfung <g>besteht</g>.",
      "en": "<b>1. Introducing the subordinate clause</b><br><table><tr><th>Introduction</th><th>Use and example</th></tr><tr><td><g>dass</g></td><td>Fact or statement:<br>Ich weiß, <g>dass</g> er krank ist.</td></tr><tr><td><g>ob</g></td><td>Yes-no question:<br>Ich frage mich, <g>ob</g> er kommt.</td></tr><tr><td><g>w</g>-question word</td><td>Information question:<br>Ich weiß nicht, <g>wann</g> er kommt.</td></tr><tr><td><g>wer</g> / <g>was</g></td><td>general statement (subject clause):<br><g>Wer</g> rastet, der rostet.</td></tr><tr><td><g>zu</g> + Infinitiv</td><td>same subject:<br>Er hofft, bald <g>zu gewinnen</g>.</td></tr></table><br><br><b>2. Subject clauses</b><br>Subject clauses follow verbs and expressions such as <g>freuen, stimmen, gehören, scheinen, klar sein, wichtig sein</g>. If the subordinate clause comes first, the verb of the main clause follows directly; the placeholder <g>es</g> is dropped. If it follows the main clause, <g>es</g> is usually needed.<br><br><g>Dass du kommst</g>, freut mich.<br>I'm glad that you are coming.<br><g>Es</g> freut mich, <g>dass du kommst</g>.<br>I'm glad that you are coming.<br><g>Ob er Recht hat</g>, ist noch unklar.<br>Whether he is right is still unclear.<br><g>Wer zuerst kommt</g>, mahlt zuerst.<br>First come, first served.<br><br><b>3. Object clauses</b><br>Object clauses complement verbs such as <g>wissen, glauben, meinen, sagen, fragen, hoffen, vermuten</g>. After verbs of saying and thinking <g>dass</g> can be dropped; main-clause word order then applies (verb in position 2): <g>Ich glaube, er kommt noch.</g> With verbs that take a preposition, the main clause often contains a <b>correlate</b> (<g>darauf, davon, dafür …</g>).<br><br>Ich weiß, <g>dass</g> er krank <g>ist</g>.<br>I know that he is ill.<br>Ich weiß nicht, <g>ob</g> er <g>kommt</g>.<br>I don't know whether he is coming.<br>Sie fragt, <g>wo</g> der Bahnhof <g>ist</g>.<br>She asks where the station is.<br>Ich glaube, er <g>kommt</g> noch.<br>I think he will still come.<br><br><b>4. The correlate</b><br>With verbs and adjectives that take a fixed preposition, the main clause can contain a correlate made of <b>da(r)</b> + preposition. It is often optional, but with some verbs it is customary, for example <g>abhängen von</g> and <g>sich verlassen auf</g>. If the subordinate clause comes before the main clause, the correlate is usually required.<br><br>Ich freue mich (<g>darüber</g>), <g>dass</g> du <g>kommst</g>.<br>I'm pleased that you are coming.<br>Es hängt <g>davon</g> ab, <g>ob</g> das Wetter <g>hält</g>.<br>It depends on whether the weather holds.<br>Ich verlasse mich <g>darauf</g>, <g>dass</g> du pünktlich <g>bist</g>.<br>I rely on you being on time.<br><br><b>5. Subordinate clause or infinitive clause?</b><br>When the main and subordinate clauses have the <b>same subject</b>, an infinitive with <g>zu</g> is often used. With <b>different subjects</b> you need <g>dass</g>. The infinitive clause follows verbs such as <g>hoffen, planen, beschließen, versuchen</g>.<br><br>Er hofft, die Prüfung <g>zu bestehen</g>.<br>He hopes to pass the exam.<br>Er hofft, <g>dass</g> sie die Prüfung <g>besteht</g>.<br>He hopes that she will pass the exam.",
      "uk": "<b>1. Вступне слово підрядного речення</b><br><table><tr><th>Вступне слово</th><th>Вживання й приклад</th></tr><tr><td><g>dass</g></td><td>Факт або твердження:<br>Ich weiß, <g>dass</g> er krank ist.</td></tr><tr><td><g>ob</g></td><td>Питання «так / ні»:<br>Ich frage mich, <g>ob</g> er kommt.</td></tr><tr><td>питальне слово на <g>w</g></td><td>Питання про інформацію:<br>Ich weiß nicht, <g>wann</g> er kommt.</td></tr><tr><td><g>wer</g> / <g>was</g></td><td>загальне твердження (підметове):<br><g>Wer</g> rastet, der rostet.</td></tr><tr><td><g>zu</g> + Infinitiv</td><td>той самий підмет:<br>Er hofft, bald <g>zu gewinnen</g>.</td></tr></table><br><br><b>2. Підметові речення</b><br>Підметові речення стоять після дієслів і виразів на кшталт <g>freuen, stimmen, gehören, scheinen, klar sein, wichtig sein</g>. Якщо підрядне речення стоїть на початку, дієслово головного речення йде одразу за ним; слово-замінник <g>es</g> відпадає. Якщо воно стоїть після головного, <g>es</g> зазвичай потрібне.<br><br><g>Dass du kommst</g>, freut mich.<br>Мені приємно, що ти приходиш.<br><g>Es</g> freut mich, <g>dass du kommst</g>.<br>Мені приємно, що ти приходиш.<br><g>Ob er Recht hat</g>, ist noch unklar.<br>Чи має він рацію, поки неясно.<br><g>Wer zuerst kommt</g>, mahlt zuerst.<br>Хто перший прийшов, той перший змеле.<br><br><b>3. Додаткові речення</b><br>Додаткові речення доповнюють дієслова на кшталт <g>wissen, glauben, meinen, sagen, fragen, hoffen, vermuten</g>. Після дієслів мовлення й мислення <g>dass</g> може випадати; тоді діє порядок слів головного речення (дієслово на другому місці): <g>Ich glaube, er kommt noch.</g> У дієслів із прийменником у головному реченні часто стоїть <b>коррелят</b> (<g>darauf, davon, dafür …</g>).<br><br>Ich weiß, <g>dass</g> er krank <g>ist</g>.<br>Я знаю, що він хворий.<br>Ich weiß nicht, <g>ob</g> er <g>kommt</g>.<br>Я не знаю, чи він прийде.<br>Sie fragt, <g>wo</g> der Bahnhof <g>ist</g>.<br>Вона питає, де вокзал.<br>Ich glaube, er <g>kommt</g> noch.<br>Я думаю, він ще прийде.<br><br><b>4. Коррелят</b><br>У дієслів і прикметників із сталим прийменником у головному реченні може стояти коррелят із <b>da(r)</b> + прийменник. Він часто факультативний, але в деяких дієслів уживається звичайно, наприклад <g>abhängen von</g> і <g>sich verlassen auf</g>. Якщо підрядне речення стоїть перед головним, коррелят зазвичай потрібний.<br><br>Ich freue mich (<g>darüber</g>), <g>dass</g> du <g>kommst</g>.<br>Я радий, що ти приходиш.<br>Es hängt <g>davon</g> ab, <g>ob</g> das Wetter <g>hält</g>.<br>Це залежить від того, чи тримається погода.<br>Ich verlasse mich <g>darauf</g>, <g>dass</g> du pünktlich <g>bist</g>.<br>Я розраховую на те, що ти будеш вчасно.<br><br><b>5. Підрядне речення чи інфінітивне?</b><br>Якщо головне й підрядне речення мають <b>однаковий підмет</b>, часто вживають інфінітив із <g>zu</g>. За <b>різних підметів</b> потрібен <g>dass</g>. Інфінітивне речення стоїть після дієслів на кшталт <g>hoffen, planen, beschließen, versuchen</g>.<br><br>Er hofft, die Prüfung <g>zu bestehen</g>.<br>Він сподівається скласти іспит.<br>Er hofft, <g>dass</g> sie die Prüfung <g>besteht</g>.<br>Він сподівається, що вона складе іспит.",
      "ru": "<b>1. Вводное слово придаточного</b><br><table><tr><th>Вводное слово</th><th>Употребление и пример</th></tr><tr><td><g>dass</g></td><td>Факт или утверждение:<br>Ich weiß, <g>dass</g> er krank ist.</td></tr><tr><td><g>ob</g></td><td>Вопрос «да / нет»:<br>Ich frage mich, <g>ob</g> er kommt.</td></tr><tr><td>вопросительное слово на <g>w</g></td><td>Вопрос об информации:<br>Ich weiß nicht, <g>wann</g> er kommt.</td></tr><tr><td><g>wer</g> / <g>was</g></td><td>общее утверждение (подлежащное):<br><g>Wer</g> rastet, der rostet.</td></tr><tr><td><g>zu</g> + Infinitiv</td><td>то же подлежащее:<br>Er hofft, bald <g>zu gewinnen</g>.</td></tr></table><br><br><b>2. Подлежащные предложения</b><br>Подлежащные предложения стоят после глаголов и выражений вроде <g>freuen, stimmen, gehören, scheinen, klar sein, wichtig sein</g>. Если придаточное стоит в начале, глагол главного предложения идёт сразу за ним; слово-заместитель <g>es</g> отпадает. Если оно стоит после главного, <g>es</g> обычно нужно.<br><br><g>Dass du kommst</g>, freut mich.<br>Мне приятно, что ты приходишь.<br><g>Es</g> freut mich, <g>dass du kommst</g>.<br>Мне приятно, что ты приходишь.<br><g>Ob er Recht hat</g>, ist noch unklar.<br>Прав ли он, пока неясно.<br><g>Wer zuerst kommt</g>, mahlt zuerst.<br>Кто первым пришёл, тот первым и мелет.<br><br><b>3. Дополнительные предложения</b><br>Дополнительные предложения дополняют глаголы вроде <g>wissen, glauben, meinen, sagen, fragen, hoffen, vermuten</g>. После глаголов речи и мышления <g>dass</g> может опускаться; тогда действует порядок слов главного предложения (глагол на втором месте): <g>Ich glaube, er kommt noch.</g> У глаголов с предлогом в главном предложении часто стоит <b>коррелят</b> (<g>darauf, davon, dafür …</g>).<br><br>Ich weiß, <g>dass</g> er krank <g>ist</g>.<br>Я знаю, что он болен.<br>Ich weiß nicht, <g>ob</g> er <g>kommt</g>.<br>Я не знаю, придёт ли он.<br>Sie fragt, <g>wo</g> der Bahnhof <g>ist</g>.<br>Она спрашивает, где вокзал.<br>Ich glaube, er <g>kommt</g> noch.<br>Я думаю, он ещё придёт.<br><br><b>4. Коррелят</b><br>У глаголов и прилагательных с постоянным предлогом в главном предложении может стоять коррелят из <b>da(r)</b> + предлог. Он часто факультативен, но у некоторых глаголов употребляется обычно, например <g>abhängen von</g> и <g>sich verlassen auf</g>. Если придаточное стоит перед главным, коррелят обычно нужен.<br><br>Ich freue mich (<g>darüber</g>), <g>dass</g> du <g>kommst</g>.<br>Я рад, что ты приходишь.<br>Es hängt <g>davon</g> ab, <g>ob</g> das Wetter <g>hält</g>.<br>Это зависит от того, продержится ли погода.<br>Ich verlasse mich <g>darauf</g>, <g>dass</g> du pünktlich <g>bist</g>.<br>Я рассчитываю на то, что ты будешь вовремя.<br><br><b>5. Придаточное или инфинитивное?</b><br>Если у главного и придаточного предложений <b>одинаковое подлежащее</b>, часто употребляют инфинитив с <g>zu</g>. При <b>разных подлежащих</b> нужен <g>dass</g>. Инфинитивное предложение стоит после глаголов вроде <g>hoffen, planen, beschließen, versuchen</g>.<br><br>Er hofft, die Prüfung <g>zu bestehen</g>.<br>Он надеется сдать экзамен.<br>Er hofft, <g>dass</g> sie die Prüfung <g>besteht</g>.<br>Он надеется, что она сдаст экзамен."
    }
  },
  {
    "id": "weiterfuehrende_nebensaetze",
    "title": {"de": "Weiterführende Nebensätze", "en": "Continuative relative clauses", "uk": "Продовжувальні підрядні речення", "ru": "Присоединительные придаточные предложения"},
    "explanation": {
      "de": "<b>Ein weiterführender Nebensatz kommentiert den ganzen Satz davor.</b><br>Er bezieht sich nicht auf ein einzelnes Wort, sondern auf den <b>ganzen Hauptsatz</b>. Er beginnt mit <g>was</g> oder mit <g>wo(r)-</g> + Präposition (<g>wodurch, wofür, weshalb, weswegen</g>). Das Verb steht am Ende, und der Nebensatz steht nach dem Hauptsatz.<br>Beispiel: Sie arbeitet viel, <g>weswegen</g> sie kaum Freizeit <g>hat</g>.",
      "en": "<b>A continuative clause comments on the whole preceding clause.</b><br>It does not refer to a single word but to the <b>whole main clause</b>. It begins with <g>was</g> or with <g>wo(r)-</g> + preposition (<g>wodurch, wofür, weshalb, weswegen</g>). The verb is at the end, and the subordinate clause follows the main clause.<br>Example: Sie arbeitet viel, <g>weswegen</g> sie kaum Freizeit <g>hat</g>.<br>She works a lot, which is why she has hardly any free time.",
      "uk": "<b>Продовжувальне підрядне речення коментує все попереднє речення.</b><br>Воно стосується не окремого слова, а <b>всього головного речення</b>. Починається з <g>was</g> або з <g>wo(r)-</g> + прийменник (<g>wodurch, wofür, weshalb, weswegen</g>). Дієслово стоїть наприкінці, а підрядне речення йде після головного.<br>Приклад: Sie arbeitet viel, <g>weswegen</g> sie kaum Freizeit <g>hat</g>.<br>Вона багато працює, через що майже не має вільного часу.",
      "ru": "<b>Продолжающее придаточное предложение комментирует всё предыдущее предложение.</b><br>Оно относится не к отдельному слову, а ко <b>всему главному предложению</b>. Начинается с <g>was</g> или с <g>wo(r)-</g> + предлог (<g>wodurch, wofür, weshalb, weswegen</g>). Глагол стоит в конце, а придаточное идёт после главного.<br>Пример: Sie arbeitet viel, <g>weswegen</g> sie kaum Freizeit <g>hat</g>.<br>Она много работает, из-за чего почти не имеет свободного времени."
    },
    "rule": {
      "de": "<b>1. Funktion und Bildung</b><br>Der weiterführende Nebensatz fügt eine Information, Bewertung oder Folge zum ganzen Sachverhalt hinzu. Er steht nach einem Komma und fast immer hinter dem Hauptsatz. Das Bezugswort ist der ganze Satz, deshalb benutzt man <g>was</g> (nicht <g>das</g>).<br><br>Er hat die Prüfung bestanden, <g>was</g> alle <g>freut</g>.<br>Der Zug hatte Verspätung, <g>was</g> ich nicht <g>wusste</g>.<br><br><b>2. wo(r)- + Präposition</b><br>Die Präposition hängt vom Verb oder vom Sinn des Satzes ab. Vor Vokal steht <g>wor-</g>: <g>worüber, worauf, woran</g>.<br><br><table><tr><th>Konnektor</th><th>Bedeutung und Beispiel</th></tr><tr><td><g>wodurch</g></td><td>Mittel, Ursache:<br>Er arbeitet viel, <g>wodurch</g> er Erfolg hat.</td></tr><tr><td><g>weshalb</g> / <g>weswegen</g></td><td>Folge:<br>Sie ist krank, <g>weshalb</g> sie zu Hause bleibt.</td></tr><tr><td><g>woraufhin</g></td><td>zeitliche Folge:<br>Er schwieg, <g>woraufhin</g> sie ging.</td></tr><tr><td><g>wobei</g></td><td>Zusatz, Einschränkung:<br>Er gewann, <g>wobei</g> er Glück hatte.</td></tr><tr><td><g>worüber</g> / <g>wofür</g> / <g>woran</g></td><td>nach Verb + Präposition:<br>Er kam zu spät, <g>worüber</g> sie sich ärgerte.</td></tr></table><br><br><b>3. Abgrenzung zum Relativsatz</b><br>Ein Relativsatz bezieht sich auf <b>ein Nomen oder Pronomen</b>. Nach <g>alles, nichts, etwas, vieles, das</g> steht ebenfalls <g>was</g>, aber das ist ein Relativsatz. Ein weiterführender Satz bezieht sich auf <b>den ganzen Satz</b>.<br><br>Alles, <g>was</g> er sagt, stimmt.<br>Er sagt immer die Wahrheit, <g>was</g> ich sehr <g>schätze</g>.<br><br><b>4. Wichtig</b><br>Der weiterführende Nebensatz steht <b>nie vor</b> dem Hauptsatz. Das Verb steht am Satzende. Das Komma ist Pflicht. Das Pronomen <g>was</g> bezieht sich nie auf ein einzelnes Nomen.",
      "en": "<b>1. Function and formation</b><br>The continuative clause adds information, an evaluation or a consequence to the whole situation. It follows a comma and almost always stands after the main clause. The reference is the whole sentence, which is why <g>was</g> (not <g>das</g>) is used.<br><br>Er hat die Prüfung bestanden, <g>was</g> alle <g>freut</g>.<br>He passed the exam, which pleases everyone.<br>Der Zug hatte Verspätung, <g>was</g> ich nicht <g>wusste</g>.<br>The train was late, which I did not know.<br><br><b>2. wo(r)- + preposition</b><br>The preposition depends on the verb or on the meaning of the sentence. Before a vowel <g>wor-</g> is used: <g>worüber, worauf, woran</g>.<br><br><table><tr><th>Connector</th><th>Meaning and example</th></tr><tr><td><g>wodurch</g></td><td>means, cause:<br>Er arbeitet viel, <g>wodurch</g> er Erfolg hat.</td></tr><tr><td><g>weshalb</g> / <g>weswegen</g></td><td>consequence:<br>Sie ist krank, <g>weshalb</g> sie zu Hause bleibt.</td></tr><tr><td><g>woraufhin</g></td><td>following event:<br>Er schwieg, <g>woraufhin</g> sie ging.</td></tr><tr><td><g>wobei</g></td><td>addition, qualification:<br>Er gewann, <g>wobei</g> er Glück hatte.</td></tr><tr><td><g>worüber</g> / <g>wofür</g> / <g>woran</g></td><td>after verb + preposition:<br>Er kam zu spät, <g>worüber</g> sie sich ärgerte.</td></tr></table><br><br><b>3. Difference from the relative clause</b><br>A relative clause refers to <b>a noun or pronoun</b>. After <g>alles, nichts, etwas, vieles, das</g> <g>was</g> also follows, but that is a relative clause. A continuative clause refers to <b>the whole sentence</b>.<br><br>Alles, <g>was</g> er sagt, stimmt.<br>Everything he says is true. (relative clause)<br>Er sagt immer die Wahrheit, <g>was</g> ich sehr <g>schätze</g>.<br>He always tells the truth, which I appreciate very much. (continuative)<br><br><b>4. Important</b><br>The continuative clause <b>never comes before</b> the main clause. The verb is at the end. The comma is obligatory. The pronoun <g>was</g> never refers to a single noun.",
      "uk": "<b>1. Функція й утворення</b><br>Продовжувальне підрядне речення додає інформацію, оцінку або наслідок до всієї ситуації. Воно стоїть після коми й майже завжди після головного речення. Опорним є все речення, тому вживають <g>was</g> (а не <g>das</g>).<br><br>Er hat die Prüfung bestanden, <g>was</g> alle <g>freut</g>.<br>Він склав іспит, що всіх радує.<br>Der Zug hatte Verspätung, <g>was</g> ich nicht <g>wusste</g>.<br>Потяг запізнювався, чого я не знав.<br><br><b>2. wo(r)- + прийменник</b><br>Прийменник залежить від дієслова або від змісту речення. Перед голосним стоїть <g>wor-</g>: <g>worüber, worauf, woran</g>.<br><br><table><tr><th>Сполучник</th><th>Значення й приклад</th></tr><tr><td><g>wodurch</g></td><td>засіб, причина:<br>Er arbeitet viel, <g>wodurch</g> er Erfolg hat.</td></tr><tr><td><g>weshalb</g> / <g>weswegen</g></td><td>наслідок:<br>Sie ist krank, <g>weshalb</g> sie zu Hause bleibt.</td></tr><tr><td><g>woraufhin</g></td><td>наступна подія:<br>Er schwieg, <g>woraufhin</g> sie ging.</td></tr><tr><td><g>wobei</g></td><td>доповнення, обмеження:<br>Er gewann, <g>wobei</g> er Glück hatte.</td></tr><tr><td><g>worüber</g> / <g>wofür</g> / <g>woran</g></td><td>після дієслова + прийменник:<br>Er kam zu spät, <g>worüber</g> sie sich ärgerte.</td></tr></table><br><br><b>3. Відмінність від означального речення</b><br>Означальне речення стосується <b>іменника або займенника</b>. Після <g>alles, nichts, etwas, vieles, das</g> теж стоїть <g>was</g>, але це означальне речення. Продовжувальне речення стосується <b>всього речення</b>.<br><br>Alles, <g>was</g> er sagt, stimmt.<br>Усе, що він каже, правда. (означальне)<br>Er sagt immer die Wahrheit, <g>was</g> ich sehr <g>schätze</g>.<br>Він завжди каже правду, що я дуже цінюю. (продовжувальне)<br><br><b>4. Важливо</b><br>Продовжувальне підрядне речення <b>ніколи не стоїть перед</b> головним. Дієслово стоїть наприкінці. Кома обовʼязкова. Займенник <g>was</g> ніколи не стосується окремого іменника.",
      "ru": "<b>1. Функция и образование</b><br>Продолжающее придаточное добавляет информацию, оценку или следствие ко всей ситуации. Оно стоит после запятой и почти всегда после главного предложения. Опорным является всё предложение, поэтому употребляют <g>was</g> (а не <g>das</g>).<br><br>Er hat die Prüfung bestanden, <g>was</g> alle <g>freut</g>.<br>Он сдал экзамен, что всех радует.<br>Der Zug hatte Verspätung, <g>was</g> ich nicht <g>wusste</g>.<br>Поезд опаздывал, чего я не знал.<br><br><b>2. wo(r)- + предлог</b><br>Предлог зависит от глагола или от смысла предложения. Перед гласной стоит <g>wor-</g>: <g>worüber, worauf, woran</g>.<br><br><table><tr><th>Коннектор</th><th>Значение и пример</th></tr><tr><td><g>wodurch</g></td><td>средство, причина:<br>Er arbeitet viel, <g>wodurch</g> er Erfolg hat.</td></tr><tr><td><g>weshalb</g> / <g>weswegen</g></td><td>следствие:<br>Sie ist krank, <g>weshalb</g> sie zu Hause bleibt.</td></tr><tr><td><g>woraufhin</g></td><td>последующее событие:<br>Er schwieg, <g>woraufhin</g> sie ging.</td></tr><tr><td><g>wobei</g></td><td>дополнение, ограничение:<br>Er gewann, <g>wobei</g> er Glück hatte.</td></tr><tr><td><g>worüber</g> / <g>wofür</g> / <g>woran</g></td><td>после глагола + предлога:<br>Er kam zu spät, <g>worüber</g> sie sich ärgerte.</td></tr></table><br><br><b>3. Отличие от определительного придаточного</b><br>Определительное придаточное относится к <b>существительному или местоимению</b>. После <g>alles, nichts, etwas, vieles, das</g> тоже стоит <g>was</g>, но это определительное придаточное. Продолжающее предложение относится ко <b>всему предложению</b>.<br><br>Alles, <g>was</g> er sagt, stimmt.<br>Всё, что он говорит, правда. (определительное)<br>Er sagt immer die Wahrheit, <g>was</g> ich sehr <g>schätze</g>.<br>Он всегда говорит правду, что я очень ценю. (продолжающее)<br><br><b>4. Важно</b><br>Продолжающее придаточное <b>никогда не стоит перед</b> главным. Глагол стоит в конце. Запятая обязательна. Местоимение <g>was</g> никогда не относится к отдельному существительному."
    }
  },
  {
    "id": "nominalisierung_temporalsaetze",
    "title": {"de": "Nominalisierung und Verbalisierung von Temporalsätzen", "en": "Nominalisation and verbalisation of temporal clauses", "uk": "Номіналізація та вербалізація часових речень", "ru": "Номинализация и вербализация временных предложений"},
    "explanation": {
      "de": "<b>Zeitliche Nebensätze lassen sich in Nominalgruppen umwandeln.</b><br>Aus einer Konjunktion wird eine Präposition, aus dem Verb ein Nomen: <b>während</b> → <g>während</g> + Genitiv, <b>nachdem</b> → <g>nach</g> + Dativ, <b>bevor</b> → <g>vor</g> + Dativ, <b>seit</b> → <g>seit</g> + Dativ, <b>bis</b> → <g>bis zu</g> + Dativ, <b>sobald</b> → <g>mit</g> + Dativ. Das Subjekt wird zum Possessivartikel oder zum Genitiv.<br>Beispiel: <g>Nachdem</g> er <g>angekommen war</g>, rief er an. – <g>Nach</g> seiner <g>Ankunft</g> rief er an.",
      "en": "<b>Temporal clauses can be turned into noun phrases.</b><br>A conjunction becomes a preposition and the verb becomes a noun: <b>während</b> → <g>während</g> + genitive, <b>nachdem</b> → <g>nach</g> + dative, <b>bevor</b> → <g>vor</g> + dative, <b>seit</b> → <g>seit</g> + dative, <b>bis</b> → <g>bis zu</g> + dative, <b>sobald</b> → <g>mit</g> + dative. The subject becomes a possessive article or a genitive.<br>Example: <g>Nachdem</g> er <g>angekommen war</g>, rief er an. – <g>Nach</g> seiner <g>Ankunft</g> rief er an.<br>After he had arrived, he called. – After his arrival he called.",
      "uk": "<b>Часові підрядні речення можна перетворити на іменникові групи.</b><br>Сполучник стає прийменником, а дієслово — іменником: <b>während</b> → <g>während</g> + родовий, <b>nachdem</b> → <g>nach</g> + давальний, <b>bevor</b> → <g>vor</g> + давальний, <b>seit</b> → <g>seit</g> + давальний, <b>bis</b> → <g>bis zu</g> + давальний, <b>sobald</b> → <g>mit</g> + давальний. Підмет перетворюється на присвійний артикль або родовий відмінок.<br>Приклад: <g>Nachdem</g> er <g>angekommen war</g>, rief er an. – <g>Nach</g> seiner <g>Ankunft</g> rief er an.<br>Після того як він приїхав, він зателефонував. – Після його приїзду він зателефонував.",
      "ru": "<b>Временные придаточные можно превратить в именные группы.</b><br>Союз становится предлогом, а глагол — существительным: <b>während</b> → <g>während</g> + родительный, <b>nachdem</b> → <g>nach</g> + дательный, <b>bevor</b> → <g>vor</g> + дательный, <b>seit</b> → <g>seit</g> + дательный, <b>bis</b> → <g>bis zu</g> + дательный, <b>sobald</b> → <g>mit</g> + дательный. Подлежащее становится притяжательным артиклем или родительным падежом.<br>Пример: <g>Nachdem</g> er <g>angekommen war</g>, rief er an. – <g>Nach</g> seiner <g>Ankunft</g> rief er an.<br>После того как он приехал, он позвонил. – После его приезда он позвонил."
    },
    "rule": {
      "de": "<b>1. Konjunktion → Präposition</b><br><table><tr><th>Nebensatz</th><th>Nominalgruppe</th></tr><tr><td><g>während</g> er <g>arbeitete</g></td><td><g>während</g> seiner <g>Arbeit</g> (Gen.) / <g>bei</g> der <g>Arbeit</g></td></tr><tr><td><g>nachdem</g> er <g>angekommen war</g></td><td><g>nach</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>bevor</g> / <g>ehe</g> er <g>abreiste</g></td><td><g>vor</g> seiner <g>Abreise</g> (Dat.)</td></tr><tr><td><g>seit</g> / <g>seitdem</g> er hier <g>wohnt</g></td><td><g>seit</g> seinem <g>Einzug</g> (Dat.)</td></tr><tr><td><g>bis</g> er <g>zurückkommt</g></td><td><g>bis zu</g> seiner <g>Rückkehr</g> (Dat.)</td></tr><tr><td><g>sobald</g> er <g>ankommt</g></td><td><g>mit</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>als</g> / <g>wenn</g> er <g>ankam</g></td><td><g>bei</g> seiner <g>Ankunft</g> (Dat.)</td></tr></table><br><br><g>während</g> ist als Präposition formell; in der gesprochenen Sprache steht oft der Dativ. <g>bei</g> betont, dass etwas gleichzeitig passiert. Weitere Möglichkeiten: <g>im Laufe</g> / <g>im Verlauf</g> + Genitiv, <g>zu Beginn</g> / <g>am Ende</g> + Genitiv.<br><br><b>2. Vom Satz zur Nominalgruppe</b><br><b>1.</b> Das Verb wird zum Nomen (<g>ankommen</g> → <g>die Ankunft</g>).<br><b>2.</b> Das Subjekt wird zum Possessivartikel (<g>er</g> → <g>seine</g>) oder zum Genitiv (<g>der Zug</g> → <g>die Ankunft des Zuges</g>).<br><b>3.</b> Die Konjunktion wird zur passenden Präposition.<br><b>4.</b> Tempus, Modus und Modalverb gehen verloren; Adverbien werden zu Adjektiven.<br><br><g>Während</g> die Gäste <g>feierten</g>, räumte er auf.<br><g>Während</g> der <g>Feier</g> der Gäste räumte er auf.<br><g>Bevor</g> wir <g>abfuhren</g>, tankten wir.<br><g>Vor</g> unserer <g>Abfahrt</g> tankten wir.<br><br><b>3. Zurück zum Nebensatz</b><br>Bei der Verbalisierung muss man zuerst klären, <b>wer</b> etwas tut, und dann das Verb, die Zeitform und die Konjunktion wählen. Vorzeitigkeit („nachdem“) verlangt Perfekt oder Plusquamperfekt im Nebensatz.<br><br><g>Nach</g> dem <g>Essen</g> gingen wir spazieren.<br><g>Nachdem</g> wir <g>gegessen hatten</g>, gingen wir spazieren.",
      "en": "<b>1. Conjunction → preposition</b><br><table><tr><th>Subordinate clause</th><th>Noun phrase</th></tr><tr><td><g>während</g> er <g>arbeitete</g></td><td><g>während</g> seiner <g>Arbeit</g> (Gen.) / <g>bei</g> der <g>Arbeit</g></td></tr><tr><td><g>nachdem</g> er <g>angekommen war</g></td><td><g>nach</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>bevor</g> / <g>ehe</g> er <g>abreiste</g></td><td><g>vor</g> seiner <g>Abreise</g> (Dat.)</td></tr><tr><td><g>seit</g> / <g>seitdem</g> er hier <g>wohnt</g></td><td><g>seit</g> seinem <g>Einzug</g> (Dat.)</td></tr><tr><td><g>bis</g> er <g>zurückkommt</g></td><td><g>bis zu</g> seiner <g>Rückkehr</g> (Dat.)</td></tr><tr><td><g>sobald</g> er <g>ankommt</g></td><td><g>mit</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>als</g> / <g>wenn</g> er <g>ankam</g></td><td><g>bei</g> seiner <g>Ankunft</g> (Dat.)</td></tr></table><br><br><g>während</g> as a preposition is formal; in spoken language the dative is often used. <g>bei</g> stresses that something happens at the same time. Further options: <g>im Laufe</g> / <g>im Verlauf</g> + genitive, <g>zu Beginn</g> / <g>am Ende</g> + genitive.<br><br><b>2. From clause to noun phrase</b><br><b>1.</b> The verb becomes a noun (<g>ankommen</g> → <g>die Ankunft</g>).<br><b>2.</b> The subject becomes a possessive article (<g>er</g> → <g>seine</g>) or a genitive (<g>der Zug</g> → <g>die Ankunft des Zuges</g>).<br><b>3.</b> The conjunction becomes the matching preposition.<br><b>4.</b> Tense, mood and modal verb are lost; adverbs become adjectives.<br><br><g>Während</g> die Gäste <g>feierten</g>, räumte er auf.<br>While the guests were celebrating, he tidied up.<br><g>Während</g> der <g>Feier</g> der Gäste räumte er auf.<br>During the guests' celebration he tidied up.<br><g>Bevor</g> wir <g>abfuhren</g>, tankten wir.<br>Before we left, we filled up the car.<br><g>Vor</g> unserer <g>Abfahrt</g> tankten wir.<br>Before our departure we filled up the car.<br><br><b>3. Back to the subordinate clause</b><br>When turning a noun phrase back into a clause, you must first clarify <b>who</b> does something, and then choose the verb, the tense and the conjunction. Prior action (“nachdem”) requires the perfect or past perfect in the subordinate clause.<br><br><g>Nach</g> dem <g>Essen</g> gingen wir spazieren.<br>After the meal we went for a walk.<br><g>Nachdem</g> wir <g>gegessen hatten</g>, gingen wir spazieren.<br>After we had eaten, we went for a walk.",
      "uk": "<b>1. Сполучник → прийменник</b><br><table><tr><th>Підрядне речення</th><th>Іменникова група</th></tr><tr><td><g>während</g> er <g>arbeitete</g></td><td><g>während</g> seiner <g>Arbeit</g> (Gen.) / <g>bei</g> der <g>Arbeit</g></td></tr><tr><td><g>nachdem</g> er <g>angekommen war</g></td><td><g>nach</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>bevor</g> / <g>ehe</g> er <g>abreiste</g></td><td><g>vor</g> seiner <g>Abreise</g> (Dat.)</td></tr><tr><td><g>seit</g> / <g>seitdem</g> er hier <g>wohnt</g></td><td><g>seit</g> seinem <g>Einzug</g> (Dat.)</td></tr><tr><td><g>bis</g> er <g>zurückkommt</g></td><td><g>bis zu</g> seiner <g>Rückkehr</g> (Dat.)</td></tr><tr><td><g>sobald</g> er <g>ankommt</g></td><td><g>mit</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>als</g> / <g>wenn</g> er <g>ankam</g></td><td><g>bei</g> seiner <g>Ankunft</g> (Dat.)</td></tr></table><br><br><g>während</g> як прийменник — офіційне; у розмовній мові часто стоїть давальний відмінок. <g>bei</g> підкреслює одночасність. Інші можливості: <g>im Laufe</g> / <g>im Verlauf</g> + родовий, <g>zu Beginn</g> / <g>am Ende</g> + родовий.<br><br><b>2. Від речення до іменникової групи</b><br><b>1.</b> Дієслово стає іменником (<g>ankommen</g> → <g>die Ankunft</g>).<br><b>2.</b> Підмет стає присвійним артиклем (<g>er</g> → <g>seine</g>) або родовим відмінком (<g>der Zug</g> → <g>die Ankunft des Zuges</g>).<br><b>3.</b> Сполучник стає відповідним прийменником.<br><b>4.</b> Час, спосіб і модальне дієслово зникають; прислівники стають прикметниками.<br><br><g>Während</g> die Gäste <g>feierten</g>, räumte er auf.<br>Поки гості святкували, він прибирав.<br><g>Während</g> der <g>Feier</g> der Gäste räumte er auf.<br>Під час святкування гостей він прибирав.<br><g>Bevor</g> wir <g>abfuhren</g>, tankten wir.<br>Перш ніж ми поїхали, ми заправили авто.<br><g>Vor</g> unserer <g>Abfahrt</g> tankten wir.<br>Перед нашим відʼїздом ми заправили авто.<br><br><b>3. Назад до підрядного речення</b><br>Під час повернення до підрядного речення спершу треба зʼясувати, <b>хто</b> що робить, а потім обрати дієслово, час і сполучник. Попередня дія («nachdem») вимагає Perfekt або Plusquamperfekt у підрядному реченні.<br><br><g>Nach</g> dem <g>Essen</g> gingen wir spazieren.<br>Після їжі ми пішли гуляти.<br><g>Nachdem</g> wir <g>gegessen hatten</g>, gingen wir spazieren.<br>Після того як ми поїли, ми пішли гуляти.",
      "ru": "<b>1. Союз → предлог</b><br><table><tr><th>Придаточное</th><th>Именная группа</th></tr><tr><td><g>während</g> er <g>arbeitete</g></td><td><g>während</g> seiner <g>Arbeit</g> (Gen.) / <g>bei</g> der <g>Arbeit</g></td></tr><tr><td><g>nachdem</g> er <g>angekommen war</g></td><td><g>nach</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>bevor</g> / <g>ehe</g> er <g>abreiste</g></td><td><g>vor</g> seiner <g>Abreise</g> (Dat.)</td></tr><tr><td><g>seit</g> / <g>seitdem</g> er hier <g>wohnt</g></td><td><g>seit</g> seinem <g>Einzug</g> (Dat.)</td></tr><tr><td><g>bis</g> er <g>zurückkommt</g></td><td><g>bis zu</g> seiner <g>Rückkehr</g> (Dat.)</td></tr><tr><td><g>sobald</g> er <g>ankommt</g></td><td><g>mit</g> seiner <g>Ankunft</g> (Dat.)</td></tr><tr><td><g>als</g> / <g>wenn</g> er <g>ankam</g></td><td><g>bei</g> seiner <g>Ankunft</g> (Dat.)</td></tr></table><br><br><g>während</g> как предлог — официальное; в разговорной речи часто стоит дательный. <g>bei</g> подчёркивает одновременность. Другие возможности: <g>im Laufe</g> / <g>im Verlauf</g> + родительный, <g>zu Beginn</g> / <g>am Ende</g> + родительный.<br><br><b>2. От предложения к именной группе</b><br><b>1.</b> Глагол становится существительным (<g>ankommen</g> → <g>die Ankunft</g>).<br><b>2.</b> Подлежащее становится притяжательным артиклем (<g>er</g> → <g>seine</g>) или родительным падежом (<g>der Zug</g> → <g>die Ankunft des Zuges</g>).<br><b>3.</b> Союз становится подходящим предлогом.<br><b>4.</b> Время, наклонение и модальный глагол исчезают; наречия становятся прилагательными.<br><br><g>Während</g> die Gäste <g>feierten</g>, räumte er auf.<br>Пока гости праздновали, он убирал.<br><g>Während</g> der <g>Feier</g> der Gäste räumte er auf.<br>Во время праздника гостей он убирал.<br><g>Bevor</g> wir <g>abfuhren</g>, tankten wir.<br>Прежде чем мы уехали, мы заправились.<br><g>Vor</g> unserer <g>Abfahrt</g> tankten wir.<br>Перед нашим отъездом мы заправились.<br><br><b>3. Обратно к придаточному</b><br>При возвращении к придаточному сначала нужно выяснить, <b>кто</b> что делает, а затем выбрать глагол, время и союз. Предшествующее действие («nachdem») требует Perfekt или Plusquamperfekt в придаточном.<br><br><g>Nach</g> dem <g>Essen</g> gingen wir spazieren.<br>После еды мы пошли гулять.<br><g>Nachdem</g> wir <g>gegessen hatten</g>, gingen wir spazieren.<br>После того как мы поели, мы пошли гулять."
    }
  },
  {
    "id": "nominalisierung_kausal_modalsaetze",
    "title": {"de": "Nominalisierung und Verbalisierung von Kausal- und Modalsätzen", "en": "Nominalisation and verbalisation of causal and modal clauses", "uk": "Номіналізація та вербалізація причинових і способу дії речень", "ru": "Номинализация и вербализация причинных предложений и предложений образа действия"},
    "explanation": {
      "de": "<b>Gründe und Mittel kannst du mit Präpositionen statt mit Nebensätzen ausdrücken.</b><br>Kausalsätze mit <b>weil, da</b> werden zu <g>wegen, aufgrund, infolge</g> + Genitiv oder <g>dank</g> + Dativ / Genitiv. Modalsätze mit <b>indem</b> oder <b>dadurch, dass</b> werden zu <g>durch</g> + Akkusativ oder <g>mithilfe von</g> + Dativ, Sätze mit <b>ohne dass</b> zu <g>ohne</g> + Akkusativ. Das Verb wird zum Nomen.<br>Beispiel: <g>Weil</g> es <g>stürmte</g>, fiel das Fest aus. – <g>Wegen des Sturms</g> fiel das Fest aus.",
      "en": "<b>You can express reasons and means with prepositions instead of subordinate clauses.</b><br>Causal clauses with <b>weil, da</b> become <g>wegen, aufgrund, infolge</g> + genitive or <g>dank</g> + dative / genitive. Modal clauses with <b>indem</b> or <b>dadurch, dass</b> become <g>durch</g> + accusative or <g>mithilfe von</g> + dative, clauses with <b>ohne dass</b> become <g>ohne</g> + accusative. The verb becomes a noun.<br>Example: <g>Weil</g> es <g>stürmte</g>, fiel das Fest aus. – <g>Wegen des Sturms</g> fiel das Fest aus.<br>Because there was a storm, the party was cancelled. – Because of the storm, the party was cancelled.",
      "uk": "<b>Причини й засоби можна передавати прийменниками замість підрядних речень.</b><br>Причинові речення з <b>weil, da</b> перетворюються на <g>wegen, aufgrund, infolge</g> + родовий або <g>dank</g> + давальний / родовий. Речення способу дії з <b>indem</b> або <b>dadurch, dass</b> — на <g>durch</g> + знахідний або <g>mithilfe von</g> + давальний, речення з <b>ohne dass</b> — на <g>ohne</g> + знахідний. Дієслово стає іменником.<br>Приклад: <g>Weil</g> es <g>stürmte</g>, fiel das Fest aus. – <g>Wegen des Sturms</g> fiel das Fest aus.<br>Оскільки була буря, свято скасували. – Через бурю свято скасували.",
      "ru": "<b>Причины и средства можно выражать предлогами вместо придаточных.</b><br>Причинные предложения с <b>weil, da</b> превращаются в <g>wegen, aufgrund, infolge</g> + родительный или <g>dank</g> + дательный / родительный. Предложения образа действия с <b>indem</b> или <b>dadurch, dass</b> — в <g>durch</g> + винительный или <g>mithilfe von</g> + дательный, предложения с <b>ohne dass</b> — в <g>ohne</g> + винительный. Глагол становится существительным.<br>Пример: <g>Weil</g> es <g>stürmte</g>, fiel das Fest aus. – <g>Wegen des Sturms</g> fiel das Fest aus.<br>Поскольку была буря, праздник отменили. – Из-за бури праздник отменили."
    },
    "rule": {
      "de": "<b>1. Kausalsätze</b><br><table><tr><th>Präposition</th><th>Verwendung und Beispiel</th></tr><tr><td><g>wegen</g> + Gen.</td><td>neutral:<br><g>Wegen</g> des <g>Sturms</g> fiel das Fest aus.</td></tr><tr><td><g>aufgrund</g> + Gen. / <g>von</g> + Dat.</td><td>formell:<br><g>Aufgrund</g> der <g>Verspätung</g> fällt der Termin aus.</td></tr><tr><td><g>infolge</g> + Gen.</td><td>Folge eines Ereignisses, oft negativ:<br><g>Infolge</g> des <g>Streiks</g> fielen Züge aus.</td></tr><tr><td><g>dank</g> + Dat. / Gen.</td><td>positiver Grund:<br><g>Dank</g> deiner <g>Hilfe</g> habe ich es geschafft.</td></tr><tr><td><g>aus</g> + Dat.</td><td>Gefühl oder Motiv, ohne Artikel:<br><g>Aus Angst</g> sagte er nichts.</td></tr><tr><td><g>vor</g> + Dat.</td><td>Ursache einer Reaktion, ohne Artikel:<br><g>Vor Müdigkeit</g> schlief er ein.</td></tr></table><br><br>Bei Plural ohne Artikel steht nach <g>aufgrund</g> meist <g>von</g> + Dativ: <g>aufgrund von Bauarbeiten</g>.<br><br><b>2. Modalsätze</b><br><table><tr><th>Nebensatz</th><th>Nominalgruppe</th></tr><tr><td><g>indem</g> / <g>dadurch, dass</g> er <g>übt</g></td><td><g>durch</g> <g>Üben</g> (Akk.)</td></tr><tr><td><g>indem</g> er einen <g>Schlüssel benutzt</g></td><td><g>mit</g> / <g>mithilfe</g> eines <g>Schlüssels</g></td></tr><tr><td><g>ohne dass</g> sie <g>fragt</g></td><td><g>ohne</g> ihr <g>Fragen</g> (Akk.)</td></tr><tr><td><g>(an)statt dass</g> er <g>hilft</g></td><td><g>(an)statt</g> seiner <g>Hilfe</g> (Gen.)</td></tr></table><br><br>Er wird besser, <g>indem</g> er jeden Tag <g>übt</g>.<br>Er wird besser <g>durch</g> tägliches <g>Üben</g>.<br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Er ging <g>ohne</g> <g>Abschied</g>.<br><br><b>3. Umwandlung Schritt für Schritt</b><br><b>1.</b> Verb → Nomen (<g>stürmen</g> → <g>der Sturm</g>).<br><b>2.</b> Subjekt → Genitiv oder Possessivartikel; ein allgemeines Subjekt (<g>man, es</g>) entfällt.<br><b>3.</b> Adverb → Adjektiv (<g>stark regnen</g> → <g>starker Regen</g>).<br><b>4.</b> Konjunktion → Präposition mit dem richtigen Kasus.<br>Beim Rückweg bestimmst du das Verb, das Subjekt und die Zeitform neu.<br><br><g>Weil</g> es <g>stark regnete</g>, blieben wir zu Hause.<br><g>Wegen</g> des <g>starken Regens</g> blieben wir zu Hause.",
      "en": "<b>1. Causal clauses</b><br><table><tr><th>Preposition</th><th>Use and example</th></tr><tr><td><g>wegen</g> + Gen.</td><td>neutral:<br><g>Wegen</g> des <g>Sturms</g> fiel das Fest aus.</td></tr><tr><td><g>aufgrund</g> + Gen. / <g>von</g> + Dat.</td><td>formal:<br><g>Aufgrund</g> der <g>Verspätung</g> fällt der Termin aus.</td></tr><tr><td><g>infolge</g> + Gen.</td><td>consequence of an event, often negative:<br><g>Infolge</g> des <g>Streiks</g> fielen Züge aus.</td></tr><tr><td><g>dank</g> + Dat. / Gen.</td><td>positive reason:<br><g>Dank</g> deiner <g>Hilfe</g> habe ich es geschafft.</td></tr><tr><td><g>aus</g> + Dat.</td><td>feeling or motive, without article:<br><g>Aus Angst</g> sagte er nichts.</td></tr><tr><td><g>vor</g> + Dat.</td><td>cause of a reaction, without article:<br><g>Vor Müdigkeit</g> schlief er ein.</td></tr></table><br><br>With a plural noun without article, <g>aufgrund</g> is usually followed by <g>von</g> + dative: <g>aufgrund von Bauarbeiten</g>.<br><br><b>2. Modal clauses</b><br><table><tr><th>Subordinate clause</th><th>Noun phrase</th></tr><tr><td><g>indem</g> / <g>dadurch, dass</g> er <g>übt</g></td><td><g>durch</g> <g>Üben</g> (Akk.)</td></tr><tr><td><g>indem</g> er einen <g>Schlüssel benutzt</g></td><td><g>mit</g> / <g>mithilfe</g> eines <g>Schlüssels</g></td></tr><tr><td><g>ohne dass</g> sie <g>fragt</g></td><td><g>ohne</g> ihr <g>Fragen</g> (Akk.)</td></tr><tr><td><g>(an)statt dass</g> er <g>hilft</g></td><td><g>(an)statt</g> seiner <g>Hilfe</g> (Gen.)</td></tr></table><br><br>Er wird besser, <g>indem</g> er jeden Tag <g>übt</g>.<br>He gets better by practising every day.<br>Er wird besser <g>durch</g> tägliches <g>Üben</g>.<br>He gets better through daily practice.<br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>He left without saying goodbye.<br>Er ging <g>ohne</g> <g>Abschied</g>.<br>He left without a farewell.<br><br><b>3. Step-by-step conversion</b><br><b>1.</b> Verb → noun (<g>stürmen</g> → <g>der Sturm</g>).<br><b>2.</b> Subject → genitive or possessive article; a general subject (<g>man, es</g>) is dropped.<br><b>3.</b> Adverb → adjective (<g>stark regnen</g> → <g>starker Regen</g>).<br><b>4.</b> Conjunction → preposition with the correct case.<br>When converting back, you determine the verb, the subject and the tense again.<br><br><g>Weil</g> es <g>stark regnete</g>, blieben wir zu Hause.<br>Because it rained heavily, we stayed at home.<br><g>Wegen</g> des <g>starken Regens</g> blieben wir zu Hause.<br>Because of the heavy rain we stayed at home.",
      "uk": "<b>1. Причинові речення</b><br><table><tr><th>Прийменник</th><th>Вживання й приклад</th></tr><tr><td><g>wegen</g> + Gen.</td><td>нейтрально:<br><g>Wegen</g> des <g>Sturms</g> fiel das Fest aus.</td></tr><tr><td><g>aufgrund</g> + Gen. / <g>von</g> + Dat.</td><td>офіційно:<br><g>Aufgrund</g> der <g>Verspätung</g> fällt der Termin aus.</td></tr><tr><td><g>infolge</g> + Gen.</td><td>наслідок події, часто негативний:<br><g>Infolge</g> des <g>Streiks</g> fielen Züge aus.</td></tr><tr><td><g>dank</g> + Dat. / Gen.</td><td>позитивна причина:<br><g>Dank</g> deiner <g>Hilfe</g> habe ich es geschafft.</td></tr><tr><td><g>aus</g> + Dat.</td><td>почуття або мотив, без артикля:<br><g>Aus Angst</g> sagte er nichts.</td></tr><tr><td><g>vor</g> + Dat.</td><td>причина реакції, без артикля:<br><g>Vor Müdigkeit</g> schlief er ein.</td></tr></table><br><br>Перед іменником у множині без артикля після <g>aufgrund</g> зазвичай стоїть <g>von</g> + давальний: <g>aufgrund von Bauarbeiten</g>.<br><br><b>2. Речення способу дії</b><br><table><tr><th>Підрядне речення</th><th>Іменникова група</th></tr><tr><td><g>indem</g> / <g>dadurch, dass</g> er <g>übt</g></td><td><g>durch</g> <g>Üben</g> (Akk.)</td></tr><tr><td><g>indem</g> er einen <g>Schlüssel benutzt</g></td><td><g>mit</g> / <g>mithilfe</g> eines <g>Schlüssels</g></td></tr><tr><td><g>ohne dass</g> sie <g>fragt</g></td><td><g>ohne</g> ihr <g>Fragen</g> (Akk.)</td></tr><tr><td><g>(an)statt dass</g> er <g>hilft</g></td><td><g>(an)statt</g> seiner <g>Hilfe</g> (Gen.)</td></tr></table><br><br>Er wird besser, <g>indem</g> er jeden Tag <g>übt</g>.<br>Він стає кращим, тренуючись щодня.<br>Er wird besser <g>durch</g> tägliches <g>Üben</g>.<br>Він стає кращим завдяки щоденному тренуванню.<br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Він пішов, не попрощавшись.<br>Er ging <g>ohne</g> <g>Abschied</g>.<br>Він пішов без прощання.<br><br><b>3. Перетворення крок за кроком</b><br><b>1.</b> Дієслово → іменник (<g>stürmen</g> → <g>der Sturm</g>).<br><b>2.</b> Підмет → родовий відмінок або присвійний артикль; загальний підмет (<g>man, es</g>) відпадає.<br><b>3.</b> Прислівник → прикметник (<g>stark regnen</g> → <g>starker Regen</g>).<br><b>4.</b> Сполучник → прийменник із правильним відмінком.<br>У зворотному напрямку ти заново визначаєш дієслово, підмет і час.<br><br><g>Weil</g> es <g>stark regnete</g>, blieben wir zu Hause.<br>Оскільки йшов сильний дощ, ми залишилися вдома.<br><g>Wegen</g> des <g>starken Regens</g> blieben wir zu Hause.<br>Через сильний дощ ми залишилися вдома.",
      "ru": "<b>1. Причинные предложения</b><br><table><tr><th>Предлог</th><th>Употребление и пример</th></tr><tr><td><g>wegen</g> + Gen.</td><td>нейтрально:<br><g>Wegen</g> des <g>Sturms</g> fiel das Fest aus.</td></tr><tr><td><g>aufgrund</g> + Gen. / <g>von</g> + Dat.</td><td>официально:<br><g>Aufgrund</g> der <g>Verspätung</g> fällt der Termin aus.</td></tr><tr><td><g>infolge</g> + Gen.</td><td>следствие события, часто негативное:<br><g>Infolge</g> des <g>Streiks</g> fielen Züge aus.</td></tr><tr><td><g>dank</g> + Dat. / Gen.</td><td>положительная причина:<br><g>Dank</g> deiner <g>Hilfe</g> habe ich es geschafft.</td></tr><tr><td><g>aus</g> + Dat.</td><td>чувство или мотив, без артикля:<br><g>Aus Angst</g> sagte er nichts.</td></tr><tr><td><g>vor</g> + Dat.</td><td>причина реакции, без артикля:<br><g>Vor Müdigkeit</g> schlief er ein.</td></tr></table><br><br>Перед существительным во множественном числе без артикля после <g>aufgrund</g> обычно стоит <g>von</g> + дательный: <g>aufgrund von Bauarbeiten</g>.<br><br><b>2. Предложения образа действия</b><br><table><tr><th>Придаточное</th><th>Именная группа</th></tr><tr><td><g>indem</g> / <g>dadurch, dass</g> er <g>übt</g></td><td><g>durch</g> <g>Üben</g> (Akk.)</td></tr><tr><td><g>indem</g> er einen <g>Schlüssel benutzt</g></td><td><g>mit</g> / <g>mithilfe</g> eines <g>Schlüssels</g></td></tr><tr><td><g>ohne dass</g> sie <g>fragt</g></td><td><g>ohne</g> ihr <g>Fragen</g> (Akk.)</td></tr><tr><td><g>(an)statt dass</g> er <g>hilft</g></td><td><g>(an)statt</g> seiner <g>Hilfe</g> (Gen.)</td></tr></table><br><br>Er wird besser, <g>indem</g> er jeden Tag <g>übt</g>.<br>Он становится лучше, тренируясь каждый день.<br>Er wird besser <g>durch</g> tägliches <g>Üben</g>.<br>Он становится лучше благодаря ежедневным тренировкам.<br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Он ушёл, не попрощавшись.<br>Er ging <g>ohne</g> <g>Abschied</g>.<br>Он ушёл без прощания.<br><br><b>3. Преобразование шаг за шагом</b><br><b>1.</b> Глагол → существительное (<g>stürmen</g> → <g>der Sturm</g>).<br><b>2.</b> Подлежащее → родительный падеж или притяжательный артикль; общее подлежащее (<g>man, es</g>) отпадает.<br><b>3.</b> Наречие → прилагательное (<g>stark regnen</g> → <g>starker Regen</g>).<br><b>4.</b> Союз → предлог с правильным падежом.<br>При обратном преобразовании ты заново определяешь глагол, подлежащее и время.<br><br><g>Weil</g> es <g>stark regnete</g>, blieben wir zu Hause.<br>Поскольку шёл сильный дождь, мы остались дома.<br><g>Wegen</g> des <g>starken Regens</g> blieben wir zu Hause.<br>Из-за сильного дождя мы остались дома."
    }
  },
  {
    "id": "negative_konsekutivsaetze",
    "title": {"de": "Negative Konsekutivsätze: zu …, um zu / als dass", "en": "Negative consecutive clauses: zu …, um zu / als dass", "uk": "Заперечні наслідкові речення: zu …, um zu / als dass", "ru": "Отрицательные следственные предложения: zu …, um zu / als dass"},
    "explanation": {
      "de": "<b>Mit „zu“ drückst du aus, dass etwas zu stark ist, um eine Folge zuzulassen.</b><br>Mit <b>zu + Adjektiv + um … zu</b> oder <b>zu + Adjektiv + als dass</b> sagst du: Etwas ist <b>zu</b> stark, <b>sodass</b> eine Folge nicht möglich ist. Nach <g>als dass</g> steht meist der <b>Konjunktiv II</b>. Beide Konstruktionen sind inhaltlich negativ, auch wenn kein „nicht“ im Satz steht.<br>Beispiel: Er ist <g>zu</g> müde, <g>um</g> noch <g>zu arbeiten</g>.",
      "en": "<b>With “zu” you say that something is too much to allow a consequence.</b><br>With <b>zu + adjective + um … zu</b> or <b>zu + adjective + als dass</b> you say: something is <b>too</b> much, <b>so that</b> a consequence is not possible. After <g>als dass</g> the <b>Konjunktiv II</b> usually follows. Both constructions are negative in meaning, even though there is no “nicht” in the sentence.<br>Example: Er ist <g>zu</g> müde, <g>um</g> noch <g>zu arbeiten</g>.<br>He is too tired to work any more.",
      "uk": "<b>За допомогою «zu» ти кажеш, що чогось занадто, щоб був можливий наслідок.</b><br>За допомогою <b>zu + прикметник + um … zu</b> або <b>zu + прикметник + als dass</b> ти кажеш: чогось <b>занадто</b> багато, <b>тому</b> наслідок неможливий. Після <g>als dass</g> зазвичай стоїть <b>Konjunktiv II</b>. Обидві конструкції за змістом заперечні, хоча в реченні немає «nicht».<br>Приклад: Er ist <g>zu</g> müde, <g>um</g> noch <g>zu arbeiten</g>.<br>Він надто втомлений, щоб ще працювати.",
      "ru": "<b>С помощью «zu» ты говоришь, что чего-то слишком много, чтобы было возможно следствие.</b><br>С помощью <b>zu + прилагательное + um … zu</b> или <b>zu + прилагательное + als dass</b> ты говоришь: чего-то <b>слишком</b> много, <b>поэтому</b> следствие невозможно. После <g>als dass</g> обычно стоит <b>Konjunktiv II</b>. Обе конструкции по смыслу отрицательные, хотя в предложении нет «nicht».<br>Пример: Er ist <g>zu</g> müde, <g>um</g> noch <g>zu arbeiten</g>.<br>Он слишком устал, чтобы ещё работать."
    },
    "rule": {
      "de": "<b>1. zu … um … zu</b><br>Diese Konstruktion benutzt du bei <b>gleichem Subjekt</b>. Das Verb im Infinitivsatz steht positiv, die Bedeutung ist aber negativ: „zu müde, um zu arbeiten“ = „so müde, dass er nicht arbeiten kann“.<br><br>Sie ist <g>zu</g> klug, <g>um</g> darauf <g>hereinzufallen</g>.<br>Die Aufgabe ist <g>zu</g> schwer, <g>um</g> sie allein <g>zu lösen</g>.<br><br><b>2. zu … als dass</b><br><g>Als dass</g> leitet einen Nebensatz ein (Verb am Ende). Er steht im <b>Konjunktiv II</b>, oft mit einem Modalverb (<g>könnte, dürfte, würde</g>). Man benutzt diese Konstruktion auch bei <b>verschiedenen Subjekten</b> oder wenn der Satz unpersönlich ist.<br><br>Es ist <g>zu</g> spät, <g>als dass</g> wir noch <g>anfangen könnten</g>.<br>Das Risiko ist <g>zu</g> groß, <g>als dass</g> man es <g>eingehen dürfte</g>.<br>Es war <g>zu</g> spät, <g>als dass</g> wir noch etwas <g>hätten ändern können</g>.<br><br><b>3. Umformungen</b><br><table><tr><th>negative Konsekutivkonstruktion</th><th>Umschreibung</th></tr><tr><td>Er ist <g>zu</g> müde, <g>um</g> zu arbeiten.</td><td>Er ist <g>so</g> müde, <g>dass</g> er <g>nicht</g> arbeiten kann.</td></tr><tr><td>Es ist <g>zu</g> spät, <g>als dass</g> wir anfangen könnten.</td><td>Es ist <g>so</g> spät, <g>dass</g> wir <g>nicht mehr</g> anfangen können.</td></tr><tr><td>Er ist <g>nicht</g> alt <g>genug</g>, <g>um</g> zu wählen.</td><td>Er ist <g>zu</g> jung, <g>um</g> zu wählen.</td></tr></table><br><br>Bei <b>genug</b> wird die positive Eigenschaft verneint (<g>nicht alt genug</g>), bei <b>zu</b> steht die Eigenschaft ohne Verneinung (<g>zu jung</g>). Die Konstruktion mit <g>so … dass</g> kann man auch ohne Konjunktiv II benutzen.",
      "en": "<b>1. zu … um … zu</b><br>You use this construction with the <b>same subject</b>. The verb in the infinitive clause is positive, but the meaning is negative: “too tired to work” = “so tired that he cannot work”.<br><br>Sie ist <g>zu</g> klug, <g>um</g> darauf <g>hereinzufallen</g>.<br>She is too clever to fall for that.<br>Die Aufgabe ist <g>zu</g> schwer, <g>um</g> sie allein <g>zu lösen</g>.<br>The task is too difficult to solve alone.<br><br><b>2. zu … als dass</b><br><g>Als dass</g> introduces a subordinate clause (verb at the end). It is in the <b>Konjunktiv II</b>, often with a modal verb (<g>könnte, dürfte, würde</g>). This construction is also used with <b>different subjects</b> or when the sentence is impersonal.<br><br>Es ist <g>zu</g> spät, <g>als dass</g> wir noch <g>anfangen könnten</g>.<br>It is too late for us to start now.<br>Das Risiko ist <g>zu</g> groß, <g>als dass</g> man es <g>eingehen dürfte</g>.<br>The risk is too great to be taken.<br>Es war <g>zu</g> spät, <g>als dass</g> wir noch etwas <g>hätten ändern können</g>.<br>It was too late for us to change anything.<br><br><b>3. Paraphrases</b><br><table><tr><th>Negative consecutive construction</th><th>Paraphrase</th></tr><tr><td>Er ist <g>zu</g> müde, <g>um</g> zu arbeiten.</td><td>Er ist <g>so</g> müde, <g>dass</g> er <g>nicht</g> arbeiten kann.</td></tr><tr><td>Es ist <g>zu</g> spät, <g>als dass</g> wir anfangen könnten.</td><td>Es ist <g>so</g> spät, <g>dass</g> wir <g>nicht mehr</g> anfangen können.</td></tr><tr><td>Er ist <g>nicht</g> alt <g>genug</g>, <g>um</g> zu wählen.</td><td>Er ist <g>zu</g> jung, <g>um</g> zu wählen.</td></tr></table><br><br>With <b>genug</b> the positive quality is negated (<g>nicht alt genug</g>); with <b>zu</b> the quality appears without negation (<g>zu jung</g>). The construction with <g>so … dass</g> can also be used without the Konjunktiv II.",
      "uk": "<b>1. zu … um … zu</b><br>Цю конструкцію вживають за <b>однакового підмета</b>. Дієслово в інфінітивному реченні стоїть у ствердній формі, але значення заперечне: «надто втомлений, щоб працювати» = «так утомлений, що не може працювати».<br><br>Sie ist <g>zu</g> klug, <g>um</g> darauf <g>hereinzufallen</g>.<br>Вона надто розумна, щоб на це піддатися.<br>Die Aufgabe ist <g>zu</g> schwer, <g>um</g> sie allein <g>zu lösen</g>.<br>Завдання надто складне, щоб розвʼязати його самому.<br><br><b>2. zu … als dass</b><br><g>Als dass</g> вводить підрядне речення (дієслово наприкінці). Воно стоїть у <b>Konjunktiv II</b>, часто з модальним дієсловом (<g>könnte, dürfte, würde</g>). Цю конструкцію вживають і за <b>різних підметів</b>, і в безособових реченнях.<br><br>Es ist <g>zu</g> spät, <g>als dass</g> wir noch <g>anfangen könnten</g>.<br>Вже надто пізно, щоб ми могли починати.<br>Das Risiko ist <g>zu</g> groß, <g>als dass</g> man es <g>eingehen dürfte</g>.<br>Ризик надто великий, щоб на нього можна було йти.<br>Es war <g>zu</g> spät, <g>als dass</g> wir noch etwas <g>hätten ändern können</g>.<br>Було надто пізно, щоб ми могли щось змінити.<br><br><b>3. Перефразування</b><br><table><tr><th>Заперечна конструкція наслідку</th><th>Перефразування</th></tr><tr><td>Er ist <g>zu</g> müde, <g>um</g> zu arbeiten.</td><td>Er ist <g>so</g> müde, <g>dass</g> er <g>nicht</g> arbeiten kann.</td></tr><tr><td>Es ist <g>zu</g> spät, <g>als dass</g> wir anfangen könnten.</td><td>Es ist <g>so</g> spät, <g>dass</g> wir <g>nicht mehr</g> anfangen können.</td></tr><tr><td>Er ist <g>nicht</g> alt <g>genug</g>, <g>um</g> zu wählen.</td><td>Er ist <g>zu</g> jung, <g>um</g> zu wählen.</td></tr></table><br><br>З <b>genug</b> заперечується позитивна властивість (<g>nicht alt genug</g>), із <b>zu</b> властивість стоїть без заперечення (<g>zu jung</g>). Конструкцію з <g>so … dass</g> можна вживати й без Konjunktiv II.",
      "ru": "<b>1. zu … um … zu</b><br>Эту конструкцию употребляют при <b>одинаковом подлежащем</b>. Глагол в инфинитивном предложении стоит в утвердительной форме, но значение отрицательное: «слишком устал, чтобы работать» = «так устал, что не может работать».<br><br>Sie ist <g>zu</g> klug, <g>um</g> darauf <g>hereinzufallen</g>.<br>Она слишком умна, чтобы на это попасться.<br>Die Aufgabe ist <g>zu</g> schwer, <g>um</g> sie allein <g>zu lösen</g>.<br>Задание слишком сложное, чтобы решить его самому.<br><br><b>2. zu … als dass</b><br><g>Als dass</g> вводит придаточное предложение (глагол в конце). Оно стоит в <b>Konjunktiv II</b>, часто с модальным глаголом (<g>könnte, dürfte, würde</g>). Эту конструкцию употребляют и при <b>разных подлежащих</b>, и в безличных предложениях.<br><br>Es ist <g>zu</g> spät, <g>als dass</g> wir noch <g>anfangen könnten</g>.<br>Уже слишком поздно, чтобы мы могли начинать.<br>Das Risiko ist <g>zu</g> groß, <g>als dass</g> man es <g>eingehen dürfte</g>.<br>Риск слишком велик, чтобы на него можно было идти.<br>Es war <g>zu</g> spät, <g>als dass</g> wir noch etwas <g>hätten ändern können</g>.<br>Было слишком поздно, чтобы мы могли что-то изменить.<br><br><b>3. Перефразирования</b><br><table><tr><th>Отрицательная конструкция следствия</th><th>Перефразирование</th></tr><tr><td>Er ist <g>zu</g> müde, <g>um</g> zu arbeiten.</td><td>Er ist <g>so</g> müde, <g>dass</g> er <g>nicht</g> arbeiten kann.</td></tr><tr><td>Es ist <g>zu</g> spät, <g>als dass</g> wir anfangen könnten.</td><td>Es ist <g>so</g> spät, <g>dass</g> wir <g>nicht mehr</g> anfangen können.</td></tr><tr><td>Er ist <g>nicht</g> alt <g>genug</g>, <g>um</g> zu wählen.</td><td>Er ist <g>zu</g> jung, <g>um</g> zu wählen.</td></tr></table><br><br>С <b>genug</b> отрицается положительное свойство (<g>nicht alt genug</g>), с <b>zu</b> свойство стоит без отрицания (<g>zu jung</g>). Конструкцию с <g>so … dass</g> можно употреблять и без Konjunktiv II."
    }
  },
  {
    "id": "nominalisierung_konzessiv_finalsaetze",
    "title": {"de": "Nominalisierung und Verbalisierung von Konzessiv- und Finalsätzen", "en": "Nominalisation and verbalisation of concessive and final clauses", "uk": "Номіналізація та вербалізація допустових і цільових речень", "ru": "Номинализация и вербализация уступительных и целевых предложений"},
    "explanation": {
      "de": "<b>Gegengründe und Ziele kannst du mit Präpositionen ausdrücken.</b><br>Konzessivsätze mit <b>obwohl</b> werden zu <g>trotz</g> + Genitiv oder <g>ungeachtet</g> + Genitiv. Finalsätze mit <b>damit</b> oder <b>um … zu</b> werden zu <g>zu</g> + Dativ, <g>für</g> + Akkusativ oder <g>zwecks</g> + Genitiv. Das Verb wird zum Nomen.<br>Beispiel: <g>Obwohl</g> es <g>regnete</g>, gingen wir spazieren. – <g>Trotz des Regens</g> gingen wir spazieren.",
      "en": "<b>You can express concessions and purposes with prepositions.</b><br>Concessive clauses with <b>obwohl</b> become <g>trotz</g> + genitive or <g>ungeachtet</g> + genitive. Final clauses with <b>damit</b> or <b>um … zu</b> become <g>zu</g> + dative, <g>für</g> + accusative or <g>zwecks</g> + genitive. The verb becomes a noun.<br>Example: <g>Obwohl</g> es <g>regnete</g>, gingen wir spazieren. – <g>Trotz des Regens</g> gingen wir spazieren.<br>Although it was raining, we went for a walk. – Despite the rain, we went for a walk.",
      "uk": "<b>Протиставні причини й мету можна передавати прийменниками.</b><br>Допустові речення з <b>obwohl</b> перетворюються на <g>trotz</g> + родовий або <g>ungeachtet</g> + родовий. Цільові речення з <b>damit</b> або <b>um … zu</b> — на <g>zu</g> + давальний, <g>für</g> + знахідний або <g>zwecks</g> + родовий. Дієслово стає іменником.<br>Приклад: <g>Obwohl</g> es <g>regnete</g>, gingen wir spazieren. – <g>Trotz des Regens</g> gingen wir spazieren.<br>Хоча йшов дощ, ми пішли гуляти. – Попри дощ ми пішли гуляти.",
      "ru": "<b>Уступку и цель можно выражать предлогами.</b><br>Уступительные предложения с <b>obwohl</b> превращаются в <g>trotz</g> + родительный или <g>ungeachtet</g> + родительный. Целевые предложения с <b>damit</b> или <b>um … zu</b> — в <g>zu</g> + дательный, <g>für</g> + винительный или <g>zwecks</g> + родительный. Глагол становится существительным.<br>Пример: <g>Obwohl</g> es <g>regnete</g>, gingen wir spazieren. – <g>Trotz des Regens</g> gingen wir spazieren.<br>Хотя шёл дождь, мы пошли гулять. – Несмотря на дождь, мы пошли гулять."
    },
    "rule": {
      "de": "<b>1. Konzessivsätze: obwohl → trotz</b><br><table><tr><th>Nebensatz</th><th>Nominalgruppe</th></tr><tr><td><g>obwohl</g> / <g>obgleich</g> / <g>wenngleich</g> es <g>regnete</g></td><td><g>trotz</g> des <g>Regens</g> (Gen.)</td></tr><tr><td><g>obwohl</g> er <g>krank war</g></td><td><g>ungeachtet</g> seiner <g>Krankheit</g> (Gen.)</td></tr><tr><td><g>obwohl</g> sie sehr <g>vorsichtig war</g></td><td><g>bei</g> aller <g>Vorsicht</g> (Dat.)</td></tr><tr><td><g>obwohl</g> alle <g>widersprachen</g></td><td>allen <g>Widersprüchen</g> <g>zum Trotz</g> (Dat.)</td></tr></table><br><br><g>Trotz</g> steht im geschriebenen Deutsch mit Genitiv, im gesprochenen oft mit Dativ. <g>Ungeachtet</g> und <g>unbeschadet</g> sind sehr formell. Beim Rückweg wird aus dem Nomen wieder ein Verb: <g>trotz seiner Müdigkeit</g> → <g>obwohl er müde war</g>.<br><br><b>2. Finalsätze: damit / um … zu</b><br><table><tr><th>Nebensatz</th><th>Nominalgruppe</th></tr><tr><td><g>um</g> sich <g>zu erholen</g></td><td><g>zur</g> <g>Erholung</g> (Dat.)</td></tr><tr><td><g>damit</g> die Kinder <g>lernen</g></td><td><g>für</g> das <g>Lernen</g> der Kinder (Akk.)</td></tr><tr><td><g>um</g> die Lage <g>zu klären</g></td><td><g>zwecks</g> <g>Klärung</g> der Lage (Gen.)</td></tr><tr><td><g>damit</g> das Projekt <g>gelingt</g></td><td><g>im Interesse</g> des <g>Projekts</g> (Gen.)</td></tr></table><br><br><g>zu</g> + Dativ ist die häufigste Form. <g>Zwecks</g> ist Amts- und Geschäftssprache; das Nomen steht oft ohne Artikel: <g>zwecks Klärung</g>. Bei verschiedenen Subjekten (<g>damit</g>) braucht man oft eine freiere Formulierung.<br><br><g>Um</g> sich <g>zu erholen</g>, fuhr er weg.<br><g>Zur Erholung</g> fuhr er weg.<br>Er gab mir Geld, <g>damit</g> ich <g>studieren konnte</g>.<br>Er gab mir Geld <g>für</g> mein <g>Studium</g>.<br><br><b>3. Praktische Hinweise</b><br>Der Nominalstil verliert Informationen: Zeit, Modus und oft das Subjekt. Prüfe beim Umformen deshalb, ob der Sinn gleich bleibt. Konzessive Präpositionen (<g>trotz</g>) und finale (<g>zu, für</g>) lassen sich nicht verwechseln: <g>trotz</g> nennt einen Gegengrund, <g>zu / für</g> ein Ziel.",
      "en": "<b>1. Concessive clauses: obwohl → trotz</b><br><table><tr><th>Subordinate clause</th><th>Noun phrase</th></tr><tr><td><g>obwohl</g> / <g>obgleich</g> / <g>wenngleich</g> es <g>regnete</g></td><td><g>trotz</g> des <g>Regens</g> (Gen.)</td></tr><tr><td><g>obwohl</g> er <g>krank war</g></td><td><g>ungeachtet</g> seiner <g>Krankheit</g> (Gen.)</td></tr><tr><td><g>obwohl</g> sie sehr <g>vorsichtig war</g></td><td><g>bei</g> aller <g>Vorsicht</g> (Dat.)</td></tr><tr><td><g>obwohl</g> alle <g>widersprachen</g></td><td>allen <g>Widersprüchen</g> <g>zum Trotz</g> (Dat.)</td></tr></table><br><br>In written German <g>trotz</g> takes the genitive, in spoken German often the dative. <g>Ungeachtet</g> and <g>unbeschadet</g> are very formal. When converting back, the noun becomes a verb again: <g>trotz seiner Müdigkeit</g> → <g>obwohl er müde war</g>.<br><br><b>2. Final clauses: damit / um … zu</b><br><table><tr><th>Subordinate clause</th><th>Noun phrase</th></tr><tr><td><g>um</g> sich <g>zu erholen</g></td><td><g>zur</g> <g>Erholung</g> (Dat.)</td></tr><tr><td><g>damit</g> die Kinder <g>lernen</g></td><td><g>für</g> das <g>Lernen</g> der Kinder (Akk.)</td></tr><tr><td><g>um</g> die Lage <g>zu klären</g></td><td><g>zwecks</g> <g>Klärung</g> der Lage (Gen.)</td></tr><tr><td><g>damit</g> das Projekt <g>gelingt</g></td><td><g>im Interesse</g> des <g>Projekts</g> (Gen.)</td></tr></table><br><br><g>zu</g> + dative is the most common form. <g>Zwecks</g> belongs to official and business language; the noun often has no article: <g>zwecks Klärung</g>. With different subjects (<g>damit</g>) a freer formulation is often needed.<br><br><g>Um</g> sich <g>zu erholen</g>, fuhr er weg.<br>To recover, he went away.<br><g>Zur Erholung</g> fuhr er weg.<br>He went away for a rest.<br>Er gab mir Geld, <g>damit</g> ich <g>studieren konnte</g>.<br>He gave me money so that I could study.<br>Er gab mir Geld <g>für</g> mein <g>Studium</g>.<br>He gave me money for my studies.<br><br><b>3. Practical notes</b><br>The nominal style loses information: tense, mood and often the subject. When converting, check that the meaning stays the same. Concessive prepositions (<g>trotz</g>) and final ones (<g>zu, für</g>) must not be confused: <g>trotz</g> names a counter-reason, <g>zu / für</g> a goal.",
      "uk": "<b>1. Допустові речення: obwohl → trotz</b><br><table><tr><th>Підрядне речення</th><th>Іменникова група</th></tr><tr><td><g>obwohl</g> / <g>obgleich</g> / <g>wenngleich</g> es <g>regnete</g></td><td><g>trotz</g> des <g>Regens</g> (Gen.)</td></tr><tr><td><g>obwohl</g> er <g>krank war</g></td><td><g>ungeachtet</g> seiner <g>Krankheit</g> (Gen.)</td></tr><tr><td><g>obwohl</g> sie sehr <g>vorsichtig war</g></td><td><g>bei</g> aller <g>Vorsicht</g> (Dat.)</td></tr><tr><td><g>obwohl</g> alle <g>widersprachen</g></td><td>allen <g>Widersprüchen</g> <g>zum Trotz</g> (Dat.)</td></tr></table><br><br>У писемній німецькій <g>trotz</g> вживається з родовим, у розмовній часто з давальним. <g>Ungeachtet</g> і <g>unbeschadet</g> дуже офіційні. У зворотному напрямку іменник знову стає дієсловом: <g>trotz seiner Müdigkeit</g> → <g>obwohl er müde war</g>.<br><br><b>2. Цільові речення: damit / um … zu</b><br><table><tr><th>Підрядне речення</th><th>Іменникова група</th></tr><tr><td><g>um</g> sich <g>zu erholen</g></td><td><g>zur</g> <g>Erholung</g> (Dat.)</td></tr><tr><td><g>damit</g> die Kinder <g>lernen</g></td><td><g>für</g> das <g>Lernen</g> der Kinder (Akk.)</td></tr><tr><td><g>um</g> die Lage <g>zu klären</g></td><td><g>zwecks</g> <g>Klärung</g> der Lage (Gen.)</td></tr><tr><td><g>damit</g> das Projekt <g>gelingt</g></td><td><g>im Interesse</g> des <g>Projekts</g> (Gen.)</td></tr></table><br><br><g>zu</g> + давальний — найпоширеніша форма. <g>Zwecks</g> належить до канцелярської й ділової мови; іменник часто стоїть без артикля: <g>zwecks Klärung</g>. За різних підметів (<g>damit</g>) часто потрібне вільніше формулювання.<br><br><g>Um</g> sich <g>zu erholen</g>, fuhr er weg.<br>Щоб відпочити, він поїхав.<br><g>Zur Erholung</g> fuhr er weg.<br>Він поїхав на відпочинок.<br>Er gab mir Geld, <g>damit</g> ich <g>studieren konnte</g>.<br>Він дав мені гроші, щоб я міг учитися.<br>Er gab mir Geld <g>für</g> mein <g>Studium</g>.<br>Він дав мені гроші на моє навчання.<br><br><b>3. Практичні поради</b><br>Іменний стиль втрачає інформацію: час, спосіб і часто підмет. Тому під час перетворення перевіряй, чи зміст лишається тим самим. Допустові прийменники (<g>trotz</g>) і цільові (<g>zu, für</g>) не можна плутати: <g>trotz</g> називає протиставну причину, <g>zu / für</g> — мету.",
      "ru": "<b>1. Уступительные предложения: obwohl → trotz</b><br><table><tr><th>Придаточное</th><th>Именная группа</th></tr><tr><td><g>obwohl</g> / <g>obgleich</g> / <g>wenngleich</g> es <g>regnete</g></td><td><g>trotz</g> des <g>Regens</g> (Gen.)</td></tr><tr><td><g>obwohl</g> er <g>krank war</g></td><td><g>ungeachtet</g> seiner <g>Krankheit</g> (Gen.)</td></tr><tr><td><g>obwohl</g> sie sehr <g>vorsichtig war</g></td><td><g>bei</g> aller <g>Vorsicht</g> (Dat.)</td></tr><tr><td><g>obwohl</g> alle <g>widersprachen</g></td><td>allen <g>Widersprüchen</g> <g>zum Trotz</g> (Dat.)</td></tr></table><br><br>В письменной немецкой речи <g>trotz</g> употребляется с родительным, в разговорной часто с дательным. <g>Ungeachtet</g> и <g>unbeschadet</g> очень официальны. При обратном преобразовании существительное снова становится глаголом: <g>trotz seiner Müdigkeit</g> → <g>obwohl er müde war</g>.<br><br><b>2. Целевые предложения: damit / um … zu</b><br><table><tr><th>Придаточное</th><th>Именная группа</th></tr><tr><td><g>um</g> sich <g>zu erholen</g></td><td><g>zur</g> <g>Erholung</g> (Dat.)</td></tr><tr><td><g>damit</g> die Kinder <g>lernen</g></td><td><g>für</g> das <g>Lernen</g> der Kinder (Akk.)</td></tr><tr><td><g>um</g> die Lage <g>zu klären</g></td><td><g>zwecks</g> <g>Klärung</g> der Lage (Gen.)</td></tr><tr><td><g>damit</g> das Projekt <g>gelingt</g></td><td><g>im Interesse</g> des <g>Projekts</g> (Gen.)</td></tr></table><br><br><g>zu</g> + дательный — самая частая форма. <g>Zwecks</g> относится к канцелярскому и деловому языку; существительное часто стоит без артикля: <g>zwecks Klärung</g>. При разных подлежащих (<g>damit</g>) часто нужна более свободная формулировка.<br><br><g>Um</g> sich <g>zu erholen</g>, fuhr er weg.<br>Чтобы отдохнуть, он уехал.<br><g>Zur Erholung</g> fuhr er weg.<br>Он уехал на отдых.<br>Er gab mir Geld, <g>damit</g> ich <g>studieren konnte</g>.<br>Он дал мне деньги, чтобы я мог учиться.<br>Er gab mir Geld <g>für</g> mein <g>Studium</g>.<br>Он дал мне деньги на моё обучение.<br><br><b>3. Практические замечания</b><br>Именной стиль теряет информацию: время, наклонение и часто подлежащее. Поэтому при преобразовании проверяй, сохраняется ли смысл. Уступительные предлоги (<g>trotz</g>) и целевые (<g>zu, für</g>) нельзя путать: <g>trotz</g> называет противоположную причину, <g>zu / für</g> — цель."
    }
  },
  {
    "id": "funktionsverbgefuege",
    "title": {"de": "Funktionsverbgefüge", "en": "Verb-noun phrases (Funktionsverbgefüge)", "uk": "Дієслівно-іменникові звороти (Funktionsverbgefüge)", "ru": "Глагольно-именные обороты (Funktionsverbgefüge)"},
    "explanation": {
      "de": "<b>Ein Funktionsverbgefüge ersetzt ein einfaches Verb durch Nomen + Verb.</b><br>Das Nomen trägt die Bedeutung, das <b>Funktionsverb</b> (<g>treffen, stellen, nehmen, bringen, kommen …</g>) hat seine eigene Bedeutung fast verloren: <g>eine Entscheidung treffen</g> = <g>entscheiden</g>. Solche Gefüge sind typisch für Nachrichten, Verwaltung und Fachtexte. Sie sind fest: Du musst das richtige Verb zum Nomen lernen.<br>Beispiel: Die Stadt <g>trifft</g> noch heute eine <g>Entscheidung</g>.",
      "en": "<b>A Funktionsverbgefüge replaces a simple verb with noun + verb.</b><br>The noun carries the meaning; the <b>function verb</b> (<g>treffen, stellen, nehmen, bringen, kommen …</g>) has almost lost its own meaning: <g>eine Entscheidung treffen</g> = <g>entscheiden</g>. Such phrases are typical of news, administration and technical texts. They are fixed: you must learn the right verb for each noun.<br>Example: Die Stadt <g>trifft</g> noch heute eine <g>Entscheidung</g>.<br>The city will make a decision today.",
      "uk": "<b>Funktionsverbgefüge замінює просте дієслово сполученням іменника з дієсловом.</b><br>Значення несе іменник, а <b>функційне дієслово</b> (<g>treffen, stellen, nehmen, bringen, kommen …</g>) майже втратило власне значення: <g>eine Entscheidung treffen</g> = <g>entscheiden</g>. Такі звороти типові для новин, адміністративної та фахової мови. Вони усталені: до кожного іменника треба вивчити правильне дієслово.<br>Приклад: Die Stadt <g>trifft</g> noch heute eine <g>Entscheidung</g>.<br>Місто ухвалить рішення ще сьогодні.",
      "ru": "<b>Funktionsverbgefüge заменяет простой глагол сочетанием существительного с глаголом.</b><br>Значение несёт существительное, а <b>функциональный глагол</b> (<g>treffen, stellen, nehmen, bringen, kommen …</g>) почти утратил собственное значение: <g>eine Entscheidung treffen</g> = <g>entscheiden</g>. Такие обороты типичны для новостей, административной и специальной речи. Они устойчивы: к каждому существительному нужно выучить правильный глагол.<br>Пример: Die Stadt <g>trifft</g> noch heute eine <g>Entscheidung</g>.<br>Город примет решение ещё сегодня."
    },
    "rule": {
      "de": "<b>1. Was ist ein Funktionsverbgefüge?</b><br>Ein Funktionsverbgefüge besteht aus einem <b>Nomen</b> (oft mit Präposition) und einem <b>Funktionsverb</b>. Das Nomen ist meist von einem Verb abgeleitet (<g>entscheiden</g> → <g>die Entscheidung</g>). Anders als bei Redewendungen (<g>ins Gras beißen</g>) behält das Nomen seine normale Bedeutung.<br><br><b>2. Wichtige Verbindungen</b><br><table><tr><th>Funktionsverbgefüge</th><th>einfaches Verb</th></tr><tr><td><g>eine Entscheidung treffen</g></td><td><g>entscheiden</g></td></tr><tr><td><g>Kritik üben an</g></td><td><g>kritisieren</g></td></tr><tr><td><g>Hilfe leisten</g></td><td><g>helfen</g></td></tr><tr><td><g>in Betracht ziehen</g></td><td><g>erwägen</g></td></tr><tr><td><g>in Frage stellen</g></td><td><g>bezweifeln</g></td></tr><tr><td><g>zur Verfügung stellen</g></td><td><g>bereitstellen</g></td></tr><tr><td><g>zur Diskussion stellen</g></td><td><g>diskutieren</g></td></tr><tr><td><g>Einfluss nehmen auf</g></td><td><g>beeinflussen</g></td></tr><tr><td><g>Rücksicht nehmen auf</g></td><td><g>berücksichtigen</g></td></tr><tr><td><g>unter Beweis stellen</g></td><td><g>beweisen</g></td></tr><tr><td><g>in Kauf nehmen</g></td><td><g>hinnehmen</g></td></tr><tr><td><g>Stellung nehmen zu</g></td><td><g>sich äußern zu</g></td></tr></table><br><br>Die Bedeutung ist nicht immer ganz gleich: <g>Hilfe leisten</g> klingt formeller als <g>helfen</g>, und <g>in Frage stellen</g> ist schwächer als <g>bestreiten</g>.<br><br><b>3. Bedeutungsnuancen</b><br>Mit Funktionsverbgefügen kannst du etwas ausdrücken, was das einfache Verb nicht ausdrücken kann: den <b>Beginn</b>, die <b>Dauer</b>, das <b>Ende</b>, eine <b>Veranlassung</b> oder ein <b>Passiv</b>.<br><br><table><tr><th>Nuance</th><th>Beispiel</th></tr><tr><td>Beginn</td><td><g>in Bewegung geraten</g> / <g>zum Einsatz kommen</g></td></tr><tr><td>Dauer</td><td><g>in Betrieb sein</g> / <g>in Kraft bleiben</g></td></tr><tr><td>Ende</td><td><g>zum Abschluss kommen</g> / <g>zu Ende gehen</g></td></tr><tr><td>Veranlassung</td><td><g>in Gang setzen</g> / <g>zur Anwendung bringen</g></td></tr><tr><td>Passiv</td><td><g>Anwendung finden</g> = angewendet werden</td></tr></table><br><br>Das neue Gesetz <g>tritt</g> morgen <g>in Kraft</g>.<br>Die Methode <g>findet</g> breite <g>Anwendung</g>.<br>Der Chef <g>setzt</g> das Projekt <g>in Gang</g>.<br><br><b>4. Grammatik</b><br>Das Funktionsverb wird normal konjugiert (Position 2 im Hauptsatz, am Ende im Nebensatz). Das Nomen kann ein Adjektiv bekommen: <g>eine schwere Entscheidung treffen</g>. Artikel und Präposition sind meist fest: <g>zur Verfügung stellen</g>, nicht <g>in die Verfügung</g>. Die Verneinung steht vor dem Nomen oder als <g>kein</g>: <g>keine Entscheidung treffen</g>, <g>nicht in Frage kommen</g>.<br><br>Er <g>übt</g> scharfe <g>Kritik</g> an dem Plan.<br>Es ist wichtig, dass die Stadt schnell eine <g>Entscheidung</g> <g>trifft</g>.<br><br><b>5. Stil und Fehler</b><br>Funktionsverbgefüge gehören zur Schriftsprache. Im Gespräch sagst du lieber das einfache Verb. Viele Gefüge hintereinander wirken bürokratisch. <b>Typischer Fehler:</b> das falsche Verb. Man sagt <g>eine Entscheidung treffen</g> (nicht <g>machen</g>), <g>Kritik üben</g> (nicht <g>machen</g>) und <g>eine Frage stellen</g> (nicht <g>geben</g>).",
      "en": "<b>1. What is a Funktionsverbgefüge?</b><br>A Funktionsverbgefüge consists of a <b>noun</b> (often with a preposition) and a <b>function verb</b>. The noun is usually derived from a verb (<g>entscheiden</g> → <g>die Entscheidung</g>). Unlike idioms (<g>ins Gras beißen</g>), the noun keeps its normal meaning.<br><br><b>2. Important combinations</b><br><table><tr><th>Funktionsverbgefüge</th><th>simple verb</th></tr><tr><td><g>eine Entscheidung treffen</g></td><td><g>entscheiden</g></td></tr><tr><td><g>Kritik üben an</g></td><td><g>kritisieren</g></td></tr><tr><td><g>Hilfe leisten</g></td><td><g>helfen</g></td></tr><tr><td><g>in Betracht ziehen</g></td><td><g>erwägen</g></td></tr><tr><td><g>in Frage stellen</g></td><td><g>bezweifeln</g></td></tr><tr><td><g>zur Verfügung stellen</g></td><td><g>bereitstellen</g></td></tr><tr><td><g>zur Diskussion stellen</g></td><td><g>diskutieren</g></td></tr><tr><td><g>Einfluss nehmen auf</g></td><td><g>beeinflussen</g></td></tr><tr><td><g>Rücksicht nehmen auf</g></td><td><g>berücksichtigen</g></td></tr><tr><td><g>unter Beweis stellen</g></td><td><g>beweisen</g></td></tr><tr><td><g>in Kauf nehmen</g></td><td><g>hinnehmen</g></td></tr><tr><td><g>Stellung nehmen zu</g></td><td><g>sich äußern zu</g></td></tr></table><br><br>The meaning is not always exactly the same: <g>Hilfe leisten</g> sounds more formal than <g>helfen</g>, and <g>in Frage stellen</g> is weaker than <g>bestreiten</g>.<br><br><b>3. Shades of meaning</b><br>With Funktionsverbgefüge you can express what the simple verb cannot: the <b>beginning</b>, the <b>duration</b>, the <b>end</b>, a <b>causation</b> or a <b>passive</b>.<br><br><table><tr><th>Nuance</th><th>Example</th></tr><tr><td>beginning</td><td><g>in Bewegung geraten</g> / <g>zum Einsatz kommen</g></td></tr><tr><td>duration</td><td><g>in Betrieb sein</g> / <g>in Kraft bleiben</g></td></tr><tr><td>end</td><td><g>zum Abschluss kommen</g> / <g>zu Ende gehen</g></td></tr><tr><td>causation</td><td><g>in Gang setzen</g> / <g>zur Anwendung bringen</g></td></tr><tr><td>passive</td><td><g>Anwendung finden</g> = angewendet werden</td></tr></table><br><br>Das neue Gesetz <g>tritt</g> morgen <g>in Kraft</g>.<br>The new law comes into force tomorrow.<br>Die Methode <g>findet</g> breite <g>Anwendung</g>.<br>The method is widely used.<br>Der Chef <g>setzt</g> das Projekt <g>in Gang</g>.<br>The boss gets the project going.<br><br><b>4. Grammar</b><br>The function verb is conjugated normally (position 2 in a main clause, at the end in a subordinate clause). The noun can take an adjective: <g>eine schwere Entscheidung treffen</g>. Article and preposition are mostly fixed: <g>zur Verfügung stellen</g>, not <g>in die Verfügung</g>. Negation stands before the noun or as <g>kein</g>: <g>keine Entscheidung treffen</g>, <g>nicht in Frage kommen</g>.<br><br>Er <g>übt</g> scharfe <g>Kritik</g> an dem Plan.<br>He sharply criticises the plan.<br>Es ist wichtig, dass die Stadt schnell eine <g>Entscheidung</g> <g>trifft</g>.<br>It is important that the city makes a decision quickly.<br><br><b>5. Style and mistakes</b><br>Funktionsverbgefüge belong to written language. In conversation you prefer the simple verb. Too many in a row sound bureaucratic. <b>Typical mistake:</b> the wrong verb. You say <g>eine Entscheidung treffen</g> (not <g>machen</g>), <g>Kritik üben</g> (not <g>machen</g>) and <g>eine Frage stellen</g> (not <g>geben</g>).",
      "uk": "<b>1. Що таке Funktionsverbgefüge?</b><br>Funktionsverbgefüge складається з <b>іменника</b> (часто з прийменником) і <b>функційного дієслова</b>. Іменник зазвичай утворений від дієслова (<g>entscheiden</g> → <g>die Entscheidung</g>). На відміну від ідіом (<g>ins Gras beißen</g>), іменник зберігає своє звичайне значення.<br><br><b>2. Важливі сполучення</b><br><table><tr><th>Funktionsverbgefüge</th><th>просте дієслово</th></tr><tr><td><g>eine Entscheidung treffen</g></td><td><g>entscheiden</g></td></tr><tr><td><g>Kritik üben an</g></td><td><g>kritisieren</g></td></tr><tr><td><g>Hilfe leisten</g></td><td><g>helfen</g></td></tr><tr><td><g>in Betracht ziehen</g></td><td><g>erwägen</g></td></tr><tr><td><g>in Frage stellen</g></td><td><g>bezweifeln</g></td></tr><tr><td><g>zur Verfügung stellen</g></td><td><g>bereitstellen</g></td></tr><tr><td><g>zur Diskussion stellen</g></td><td><g>diskutieren</g></td></tr><tr><td><g>Einfluss nehmen auf</g></td><td><g>beeinflussen</g></td></tr><tr><td><g>Rücksicht nehmen auf</g></td><td><g>berücksichtigen</g></td></tr><tr><td><g>unter Beweis stellen</g></td><td><g>beweisen</g></td></tr><tr><td><g>in Kauf nehmen</g></td><td><g>hinnehmen</g></td></tr><tr><td><g>Stellung nehmen zu</g></td><td><g>sich äußern zu</g></td></tr></table><br><br>Значення не завжди цілком однакове: <g>Hilfe leisten</g> звучить офіційніше, ніж <g>helfen</g>, а <g>in Frage stellen</g> слабше, ніж <g>bestreiten</g>.<br><br><b>3. Відтінки значення</b><br>За допомогою Funktionsverbgefüge можна передати те, чого просте дієслово не передає: <b>початок</b>, <b>тривалість</b>, <b>завершення</b>, <b>спонукання</b> або <b>пасив</b>.<br><br><table><tr><th>Відтінок</th><th>Приклад</th></tr><tr><td>початок</td><td><g>in Bewegung geraten</g> / <g>zum Einsatz kommen</g></td></tr><tr><td>тривалість</td><td><g>in Betrieb sein</g> / <g>in Kraft bleiben</g></td></tr><tr><td>завершення</td><td><g>zum Abschluss kommen</g> / <g>zu Ende gehen</g></td></tr><tr><td>спонукання</td><td><g>in Gang setzen</g> / <g>zur Anwendung bringen</g></td></tr><tr><td>пасив</td><td><g>Anwendung finden</g> = angewendet werden</td></tr></table><br><br>Das neue Gesetz <g>tritt</g> morgen <g>in Kraft</g>.<br>Новий закон набирає чинності завтра.<br>Die Methode <g>findet</g> breite <g>Anwendung</g>.<br>Цей метод широко застосовують.<br>Der Chef <g>setzt</g> das Projekt <g>in Gang</g>.<br>Керівник запускає проєкт.<br><br><b>4. Граматика</b><br>Функційне дієслово відмінюється звичайно (друге місце в головному реченні, наприкінці в підрядному). Іменник може мати прикметник: <g>eine schwere Entscheidung treffen</g>. Артикль і прийменник здебільшого сталі: <g>zur Verfügung stellen</g>, а не <g>in die Verfügung</g>. Заперечення стоїть перед іменником або як <g>kein</g>: <g>keine Entscheidung treffen</g>, <g>nicht in Frage kommen</g>.<br><br>Er <g>übt</g> scharfe <g>Kritik</g> an dem Plan.<br>Він різко критикує цей план.<br>Es ist wichtig, dass die Stadt schnell eine <g>Entscheidung</g> <g>trifft</g>.<br>Важливо, щоб місто швидко ухвалило рішення.<br><br><b>5. Стиль і помилки</b><br>Funktionsverbgefüge належать до писемної мови. У розмові краще вжити просте дієслово. Багато таких зворотів поспіль звучать канцелярсько. <b>Типова помилка:</b> неправильне дієслово. Кажуть <g>eine Entscheidung treffen</g> (не <g>machen</g>), <g>Kritik üben</g> (не <g>machen</g>) і <g>eine Frage stellen</g> (не <g>geben</g>).",
      "ru": "<b>1. Что такое Funktionsverbgefüge?</b><br>Funktionsverbgefüge состоит из <b>существительного</b> (часто с предлогом) и <b>функционального глагола</b>. Существительное обычно образовано от глагола (<g>entscheiden</g> → <g>die Entscheidung</g>). В отличие от идиом (<g>ins Gras beißen</g>), существительное сохраняет своё обычное значение.<br><br><b>2. Важные сочетания</b><br><table><tr><th>Funktionsverbgefüge</th><th>простой глагол</th></tr><tr><td><g>eine Entscheidung treffen</g></td><td><g>entscheiden</g></td></tr><tr><td><g>Kritik üben an</g></td><td><g>kritisieren</g></td></tr><tr><td><g>Hilfe leisten</g></td><td><g>helfen</g></td></tr><tr><td><g>in Betracht ziehen</g></td><td><g>erwägen</g></td></tr><tr><td><g>in Frage stellen</g></td><td><g>bezweifeln</g></td></tr><tr><td><g>zur Verfügung stellen</g></td><td><g>bereitstellen</g></td></tr><tr><td><g>zur Diskussion stellen</g></td><td><g>diskutieren</g></td></tr><tr><td><g>Einfluss nehmen auf</g></td><td><g>beeinflussen</g></td></tr><tr><td><g>Rücksicht nehmen auf</g></td><td><g>berücksichtigen</g></td></tr><tr><td><g>unter Beweis stellen</g></td><td><g>beweisen</g></td></tr><tr><td><g>in Kauf nehmen</g></td><td><g>hinnehmen</g></td></tr><tr><td><g>Stellung nehmen zu</g></td><td><g>sich äußern zu</g></td></tr></table><br><br>Значение не всегда полностью одинаковое: <g>Hilfe leisten</g> звучит официальнее, чем <g>helfen</g>, а <g>in Frage stellen</g> слабее, чем <g>bestreiten</g>.<br><br><b>3. Оттенки значения</b><br>С помощью Funktionsverbgefüge можно выразить то, чего простой глагол не выражает: <b>начало</b>, <b>длительность</b>, <b>завершение</b>, <b>побуждение</b> или <b>пассив</b>.<br><br><table><tr><th>Оттенок</th><th>Пример</th></tr><tr><td>начало</td><td><g>in Bewegung geraten</g> / <g>zum Einsatz kommen</g></td></tr><tr><td>длительность</td><td><g>in Betrieb sein</g> / <g>in Kraft bleiben</g></td></tr><tr><td>завершение</td><td><g>zum Abschluss kommen</g> / <g>zu Ende gehen</g></td></tr><tr><td>побуждение</td><td><g>in Gang setzen</g> / <g>zur Anwendung bringen</g></td></tr><tr><td>пассив</td><td><g>Anwendung finden</g> = angewendet werden</td></tr></table><br><br>Das neue Gesetz <g>tritt</g> morgen <g>in Kraft</g>.<br>Новый закон вступает в силу завтра.<br>Die Methode <g>findet</g> breite <g>Anwendung</g>.<br>Этот метод широко применяется.<br>Der Chef <g>setzt</g> das Projekt <g>in Gang</g>.<br>Руководитель запускает проект.<br><br><b>4. Грамматика</b><br>Функциональный глагол спрягается обычно (второе место в главном предложении, в конце в придаточном). Существительное может иметь прилагательное: <g>eine schwere Entscheidung treffen</g>. Артикль и предлог в основном устойчивы: <g>zur Verfügung stellen</g>, а не <g>in die Verfügung</g>. Отрицание стоит перед существительным или как <g>kein</g>: <g>keine Entscheidung treffen</g>, <g>nicht in Frage kommen</g>.<br><br>Er <g>übt</g> scharfe <g>Kritik</g> an dem Plan.<br>Он резко критикует этот план.<br>Es ist wichtig, dass die Stadt schnell eine <g>Entscheidung</g> <g>trifft</g>.<br>Важно, чтобы город быстро принял решение.<br><br><b>5. Стиль и ошибки</b><br>Funktionsverbgefüge относятся к письменной речи. В разговоре лучше употребить простой глагол. Много таких оборотов подряд звучит канцелярски. <b>Типичная ошибка:</b> неправильный глагол. Говорят <g>eine Entscheidung treffen</g> (не <g>machen</g>), <g>Kritik üben</g> (не <g>machen</g>) и <g>eine Frage stellen</g> (не <g>geben</g>)."
    }
  },
  {
    "id": "infinitivsaetze",
    "title": {"de": "Infinitivsätze in Gegenwart und Vergangenheit", "en": "Infinitive clauses in the present and past", "uk": "Інфінітивні речення в теперішньому й минулому часі", "ru": "Инфинитивные предложения в настоящем и прошедшем времени"},
    "explanation": {
      "de": "<b>Ein Infinitivsatz mit „zu“ ersetzt oft einen Nebensatz.</b><br>Du benutzt ihn, wenn das Subjekt im Haupt- und Nebensatz gleich ist. Für Gleichzeitiges oder Zukünftiges steht der <b>Infinitiv Präsens</b>: Er hofft, <g>zu gewinnen</g>. Für Vorzeitiges steht der <b>Infinitiv Perfekt</b> (Partizip II + <g>haben / sein</g> + <g>zu</g>): Er behauptet, <g>gewonnen zu haben</g>. Auch mit <b>um, ohne, (an)statt</b> funktioniert das: Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Beispiel: Er behauptet, die Prüfung <g>bestanden zu haben</g>.",
      "en": "<b>An infinitive clause with “zu” often replaces a subordinate clause.</b><br>You use it when the subject in the main and subordinate clauses is the same. For simultaneous or future events the <b>present infinitive</b> is used: Er hofft, <g>zu gewinnen</g>. For prior events the <b>perfect infinitive</b> is used (past participle + <g>haben / sein</g> + <g>zu</g>): Er behauptet, <g>gewonnen zu haben</g>. This also works with <b>um, ohne, (an)statt</b>: Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Example: Er behauptet, die Prüfung <g>bestanden zu haben</g>.<br>He claims to have passed the exam.",
      "uk": "<b>Інфінітивне речення з «zu» часто замінює підрядне речення.</b><br>Його вживають, коли підмет у головному й підрядному реченні однаковий. Для одночасної або майбутньої дії стоїть <b>інфінітив теперішнього часу</b>: Er hofft, <g>zu gewinnen</g>. Для попередньої дії стоїть <b>інфінітив перфекта</b> (дієприкметник ІІ + <g>haben / sein</g> + <g>zu</g>): Er behauptet, <g>gewonnen zu haben</g>. Це працює й з <b>um, ohne, (an)statt</b>: Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Приклад: Er behauptet, die Prüfung <g>bestanden zu haben</g>.<br>Він стверджує, що склав іспит.",
      "ru": "<b>Инфинитивное предложение с «zu» часто заменяет придаточное.</b><br>Его употребляют, когда подлежащее в главном и придаточном предложении одинаковое. Для одновременного или будущего действия стоит <b>инфинитив презенса</b>: Er hofft, <g>zu gewinnen</g>. Для предшествующего действия стоит <b>инфинитив перфекта</b> (причастие II + <g>haben / sein</g> + <g>zu</g>): Er behauptet, <g>gewonnen zu haben</g>. Это работает и с <b>um, ohne, (an)statt</b>: Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Пример: Er behauptet, die Prüfung <g>bestanden zu haben</g>.<br>Он утверждает, что сдал экзамен."
    },
    "rule": {
      "de": "<b>1. Die Formen des Infinitivs</b><br><table><tr><th>Form</th><th>Beispiel</th></tr><tr><td>Präsens Aktiv</td><td>Er hofft, bald <g>zu gewinnen</g>.</td></tr><tr><td>Perfekt Aktiv</td><td>Er behauptet, <g>gewonnen zu haben</g>. / Sie freut sich, <g>angekommen zu sein</g>.</td></tr><tr><td>Präsens Passiv</td><td>Er hofft, bald <g>befördert zu werden</g>.</td></tr><tr><td>Perfekt Passiv</td><td>Er behauptet, <g>betrogen worden zu sein</g>.</td></tr></table><br><br>Bei trennbaren Verben steht <g>zu</g> zwischen Präfix und Stamm: <g>aufzustehen, einzukaufen</g>. Das Komma steht bei <g>um, ohne, (an)statt</g>, bei einem Korrelat (<g>darauf, daran</g>) und bei Infinitivsätzen, die von einem Nomen oder Adjektiv abhängen, immer.<br><br><b>2. Gleichzeitigkeit und Vorzeitigkeit</b><br>Er hofft, <g>zu gewinnen</g>.<br>Er behauptet, gestern <g>gewonnen zu haben</g>.<br>Sie ist stolz darauf, die Prüfung <g>bestanden zu haben</g>.<br><br><b>3. um … zu, ohne … zu, (an)statt … zu</b><br><g>um … zu</g> nennt ein Ziel, <g>ohne … zu</g> etwas, das fehlt, <g>(an)statt … zu</g> eine Alternative. <g>Ohne</g> und <g>(an)statt</g> können auch mit dem Infinitiv Perfekt stehen.<br><br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Er ging, <g>ohne</g> sie <g>gesehen zu haben</g>.<br><g>Statt</g> zu <g>schlafen</g>, las sie.<br><br><b>4. Subjekt und Abgrenzung</b><br>Meist ist das Subjekt des Infinitivs das Subjekt des Hauptsatzes. Bei Verben wie <g>bitten, raten, erlauben</g> ist es das Objekt: <g>Ich bitte ihn, zu kommen.</g> Bei verschiedenen Subjekten braucht man <g>dass</g>. Nach Modalverben, <g>lassen</g> und Verben der Wahrnehmung steht der Infinitiv <b>ohne zu</b>.",
      "en": "<b>1. Forms of the infinitive</b><br><table><tr><th>Form</th><th>Example</th></tr><tr><td>Present active</td><td>Er hofft, bald <g>zu gewinnen</g>.</td></tr><tr><td>Perfect active</td><td>Er behauptet, <g>gewonnen zu haben</g>. / Sie freut sich, <g>angekommen zu sein</g>.</td></tr><tr><td>Present passive</td><td>Er hofft, bald <g>befördert zu werden</g>.</td></tr><tr><td>Perfect passive</td><td>Er behauptet, <g>betrogen worden zu sein</g>.</td></tr></table><br><br>With separable verbs, <g>zu</g> goes between the prefix and the stem: <g>aufzustehen, einzukaufen</g>. A comma is always required with <g>um, ohne, (an)statt</g>, with a correlate (<g>darauf, daran</g>) and with infinitive clauses that depend on a noun or an adjective.<br><br><b>2. Simultaneity and prior action</b><br>Er hofft, <g>zu gewinnen</g>.<br>He hopes to win. (future)<br>Er behauptet, gestern <g>gewonnen zu haben</g>.<br>He claims to have won yesterday. (prior)<br>Sie ist stolz darauf, die Prüfung <g>bestanden zu haben</g>.<br>She is proud to have passed the exam.<br><br><b>3. um … zu, ohne … zu, (an)statt … zu</b><br><g>um … zu</g> names a purpose, <g>ohne … zu</g> something missing, <g>(an)statt … zu</g> an alternative. <g>Ohne</g> and <g>(an)statt</g> can also be used with the perfect infinitive.<br><br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>He left without saying goodbye.<br>Er ging, <g>ohne</g> sie <g>gesehen zu haben</g>.<br>He left without having seen her.<br><g>Statt</g> zu <g>schlafen</g>, las sie.<br>Instead of sleeping, she read.<br><br><b>4. Subject and delimitation</b><br>The subject of the infinitive is usually the subject of the main clause. With verbs such as <g>bitten, raten, erlauben</g> it is the object: <g>Ich bitte ihn, zu kommen.</g> With different subjects you need <g>dass</g>. After modal verbs, <g>lassen</g> and verbs of perception the infinitive is used <b>without zu</b>.",
      "uk": "<b>1. Форми інфінітива</b><br><table><tr><th>Форма</th><th>Приклад</th></tr><tr><td>Теперішній час, активний стан</td><td>Er hofft, bald <g>zu gewinnen</g>.</td></tr><tr><td>Перфект, активний стан</td><td>Er behauptet, <g>gewonnen zu haben</g>. / Sie freut sich, <g>angekommen zu sein</g>.</td></tr><tr><td>Теперішній час, пасивний стан</td><td>Er hofft, bald <g>befördert zu werden</g>.</td></tr><tr><td>Перфект, пасивний стан</td><td>Er behauptet, <g>betrogen worden zu sein</g>.</td></tr></table><br><br>У віддільних дієсловах <g>zu</g> стоїть між префіксом і коренем: <g>aufzustehen, einzukaufen</g>. Кома обовʼязкова при <g>um, ohne, (an)statt</g>, при корелаті (<g>darauf, daran</g>) і в інфінітивних реченнях, залежних від іменника чи прикметника.<br><br><b>2. Одночасність і попередність</b><br>Er hofft, <g>zu gewinnen</g>.<br>Він сподівається виграти. (майбутнє)<br>Er behauptet, gestern <g>gewonnen zu haben</g>.<br>Він стверджує, що вчора виграв. (попередня дія)<br>Sie ist stolz darauf, die Prüfung <g>bestanden zu haben</g>.<br>Вона пишається тим, що склала іспит.<br><br><b>3. um … zu, ohne … zu, (an)statt … zu</b><br><g>um … zu</g> називає мету, <g>ohne … zu</g> — те, чого бракує, <g>(an)statt … zu</g> — альтернативу. <g>Ohne</g> і <g>(an)statt</g> можуть стояти й з інфінітивом перфекта.<br><br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Він пішов, не попрощавшись.<br>Er ging, <g>ohne</g> sie <g>gesehen zu haben</g>.<br>Він пішов, не побачивши її.<br><g>Statt</g> zu <g>schlafen</g>, las sie.<br>Замість того щоб спати, вона читала.<br><br><b>4. Підмет і межі вживання</b><br>Зазвичай підмет інфінітива — це підмет головного речення. У дієслів на кшталт <g>bitten, raten, erlauben</g> це додаток: <g>Ich bitte ihn, zu kommen.</g> За різних підметів потрібен <g>dass</g>. Після модальних дієслів, <g>lassen</g> і дієслів сприйняття інфінітив стоїть <b>без zu</b>.",
      "ru": "<b>1. Формы инфинитива</b><br><table><tr><th>Форма</th><th>Пример</th></tr><tr><td>Презенс актив</td><td>Er hofft, bald <g>zu gewinnen</g>.</td></tr><tr><td>Перфект актив</td><td>Er behauptet, <g>gewonnen zu haben</g>. / Sie freut sich, <g>angekommen zu sein</g>.</td></tr><tr><td>Презенс пассив</td><td>Er hofft, bald <g>befördert zu werden</g>.</td></tr><tr><td>Перфект пассив</td><td>Er behauptet, <g>betrogen worden zu sein</g>.</td></tr></table><br><br>У отделяемых глаголов <g>zu</g> стоит между приставкой и корнем: <g>aufzustehen, einzukaufen</g>. Запятая обязательна при <g>um, ohne, (an)statt</g>, при корреляте (<g>darauf, daran</g>) и в инфинитивных предложениях, зависящих от существительного или прилагательного.<br><br><b>2. Одновременность и предшествование</b><br>Er hofft, <g>zu gewinnen</g>.<br>Он надеется выиграть. (будущее)<br>Er behauptet, gestern <g>gewonnen zu haben</g>.<br>Он утверждает, что вчера выиграл. (предшествование)<br>Sie ist stolz darauf, die Prüfung <g>bestanden zu haben</g>.<br>Она гордится тем, что сдала экзамен.<br><br><b>3. um … zu, ohne … zu, (an)statt … zu</b><br><g>um … zu</g> называет цель, <g>ohne … zu</g> — то, чего не хватает, <g>(an)statt … zu</g> — альтернативу. <g>Ohne</g> и <g>(an)statt</g> могут стоять и с инфинитивом перфекта.<br><br>Er ging, <g>ohne</g> sich <g>zu verabschieden</g>.<br>Он ушёл, не попрощавшись.<br>Er ging, <g>ohne</g> sie <g>gesehen zu haben</g>.<br>Он ушёл, не увидев её.<br><g>Statt</g> zu <g>schlafen</g>, las sie.<br>Вместо того чтобы спать, она читала.<br><br><b>4. Подлежащее и границы употребления</b><br>Обычно подлежащее инфинитива — это подлежащее главного предложения. У глаголов вроде <g>bitten, raten, erlauben</g> это дополнение: <g>Ich bitte ihn, zu kommen.</g> При разных подлежащих нужен <g>dass</g>. После модальных глаголов, <g>lassen</g> и глаголов восприятия инфинитив стоит <b>без zu</b>."
    }
  },
  {
    "id": "nominalisierung_konditionalsaetze",
    "title": {"de": "Nominalisierung und Verbalisierung von Konditionalsätzen", "en": "Nominalisation and verbalisation of conditional clauses", "uk": "Номіналізація та вербалізація умовних речень", "ru": "Номинализация и вербализация условных предложений"},
    "explanation": {
      "de": "<b>Bedingungen lassen sich mit Präpositionen ausdrücken.</b><br>Konditionalsätze mit <b>wenn, falls</b> werden zu <g>bei</g> + Dativ oder <g>im Falle</g> + Genitiv. Die negative Bedingung („wenn nicht“) wird zu <g>ohne</g> + Akkusativ oder <g>bei fehlendem / fehlender</g> …. Das Verb wird zum Nomen.<br>Beispiel: <g>Wenn</g> es <g>regnet</g>, fällt das Spiel aus. – <g>Bei Regen</g> fällt das Spiel aus.",
      "en": "<b>Conditions can be expressed with prepositions.</b><br>Conditional clauses with <b>wenn, falls</b> become <g>bei</g> + dative or <g>im Falle</g> + genitive. The negative condition (“if not”) becomes <g>ohne</g> + accusative or <g>bei fehlendem / fehlender</g> …. The verb becomes a noun.<br>Example: <g>Wenn</g> es <g>regnet</g>, fällt das Spiel aus. – <g>Bei Regen</g> fällt das Spiel aus.<br>If it rains, the game is cancelled. – In case of rain, the game is cancelled.",
      "uk": "<b>Умови можна передавати прийменниками.</b><br>Умовні речення з <b>wenn, falls</b> перетворюються на <g>bei</g> + давальний або <g>im Falle</g> + родовий. Негативна умова («якщо не») перетворюється на <g>ohne</g> + знахідний або <g>bei fehlendem / fehlender</g> …. Дієслово стає іменником.<br>Приклад: <g>Wenn</g> es <g>regnet</g>, fällt das Spiel aus. – <g>Bei Regen</g> fällt das Spiel aus.<br>Якщо йде дощ, гру скасовують. – У разі дощу гру скасовують.",
      "ru": "<b>Условия можно выражать предлогами.</b><br>Условные предложения с <b>wenn, falls</b> превращаются в <g>bei</g> + дательный или <g>im Falle</g> + родительный. Отрицательное условие («если не») превращается в <g>ohne</g> + винительный или <g>bei fehlendem / fehlender</g> …. Глагол становится существительным.<br>Пример: <g>Wenn</g> es <g>regnet</g>, fällt das Spiel aus. – <g>Bei Regen</g> fällt das Spiel aus.<br>Если идёт дождь, игру отменяют. – В случае дождя игру отменяют."
    },
    "rule": {
      "de": "<b>1. Positive Bedingung</b><br><table><tr><th>Nebensatz</th><th>Nominalgruppe</th></tr><tr><td><g>wenn</g> es <g>regnet</g></td><td><g>bei</g> <g>Regen</g> (Dat.)</td></tr><tr><td><g>falls</g> Sie <g>Fragen haben</g></td><td><g>im Falle</g> von <g>Fragen</g> / <g>bei</g> <g>Fragen</g></td></tr><tr><td><g>wenn</g> es <g>nötig ist</g></td><td><g>bei</g> <g>Bedarf</g> / <g>im Bedarfsfall</g></td></tr><tr><td><g>falls</g> ein <g>Schaden entsteht</g></td><td><g>im Schadensfall</g> / <g>im Falle</g> eines <g>Schadens</g> (Gen.)</td></tr></table><br><br><g>Bei</g> steht oft ohne Artikel: <g>bei Regen, bei Verspätung, bei Interesse</g>. Mit Adjektiv steht es im Dativ: <g>bei starkem Regen</g>. Außerdem gibt es <g>unter der Voraussetzung</g> + Genitiv: <g>unter der Voraussetzung eines Vertrags</g>.<br><br><g>Falls</g> du <g>Fragen hast</g>, ruf mich an.<br><g>Bei Fragen</g> ruf mich an.<br><br><b>2. Negative Bedingung: ohne</b><br>Die Bedingung „wenn nicht“ wird mit <g>ohne</g> + Akkusativ oder mit <g>bei fehlendem / fehlender</g> + Nomen ausgedrückt. Im Konjunktiv II steht die irreale Bedingung ebenfalls mit <g>ohne</g> (<g>Ohne Plan ginge es nicht.</g>) oder mit <g>mit</g> (<g>Mit etwas Glück hätten wir gewonnen.</g>).<br><br><g>Wenn</g> es <g>keinen Plan gäbe</g>, ginge es nicht.<br><g>Ohne Plan</g> ginge es nicht.<br><g>Wenn</g> die Unterlagen <g>fehlen</g>, wird der Antrag abgelehnt.<br><g>Bei fehlenden</g> Unterlagen wird der Antrag abgelehnt.<br><br><b>3. Stil und Rückweg</b><br>Diese Nominalgruppen sind typisch für Verträge, Vorschriften und Hinweise: <g>bei Nichtzahlung, im Schadensfall, bei Bedarf</g>. Beim Rückweg ergänzt du Subjekt, Verb und Zeitform: <g>bei Verspätung</g> → <g>wenn der Zug Verspätung hat</g>. Die Wahl zwischen <g>wenn</g> und <g>falls</g> hängt von der Wahrscheinlichkeit ab: <g>falls</g> klingt unsicherer.",
      "en": "<b>1. Positive condition</b><br><table><tr><th>Subordinate clause</th><th>Noun phrase</th></tr><tr><td><g>wenn</g> es <g>regnet</g></td><td><g>bei</g> <g>Regen</g> (Dat.)</td></tr><tr><td><g>falls</g> Sie <g>Fragen haben</g></td><td><g>im Falle</g> von <g>Fragen</g> / <g>bei</g> <g>Fragen</g></td></tr><tr><td><g>wenn</g> es <g>nötig ist</g></td><td><g>bei</g> <g>Bedarf</g> / <g>im Bedarfsfall</g></td></tr><tr><td><g>falls</g> ein <g>Schaden entsteht</g></td><td><g>im Schadensfall</g> / <g>im Falle</g> eines <g>Schadens</g> (Gen.)</td></tr></table><br><br><g>Bei</g> often stands without an article: <g>bei Regen, bei Verspätung, bei Interesse</g>. With an adjective it takes the dative: <g>bei starkem Regen</g>. There is also <g>unter der Voraussetzung</g> + genitive: <g>unter der Voraussetzung eines Vertrags</g>.<br><br><g>Falls</g> du <g>Fragen hast</g>, ruf mich an.<br>If you have questions, call me.<br><g>Bei Fragen</g> ruf mich an.<br>If you have questions, call me.<br><br><b>2. Negative condition: ohne</b><br>The condition “if not” is expressed with <g>ohne</g> + accusative or with <g>bei fehlendem / fehlender</g> + noun. In the Konjunktiv II the unreal condition is also expressed with <g>ohne</g> (<g>Ohne Plan ginge es nicht.</g>) or with <g>mit</g> (<g>Mit etwas Glück hätten wir gewonnen.</g>).<br><br><g>Wenn</g> es <g>keinen Plan gäbe</g>, ginge es nicht.<br>If there were no plan, it would not work.<br><g>Ohne Plan</g> ginge es nicht.<br>Without a plan it would not work.<br><g>Wenn</g> die Unterlagen <g>fehlen</g>, wird der Antrag abgelehnt.<br>If the documents are missing, the application is rejected.<br><g>Bei fehlenden</g> Unterlagen wird der Antrag abgelehnt.<br>If documents are missing, the application is rejected.<br><br><b>3. Style and conversion back</b><br>These noun phrases are typical of contracts, regulations and notices: <g>bei Nichtzahlung, im Schadensfall, bei Bedarf</g>. When converting back, you add subject, verb and tense: <g>bei Verspätung</g> → <g>wenn der Zug Verspätung hat</g>. The choice between <g>wenn</g> and <g>falls</g> depends on probability: <g>falls</g> sounds less certain.",
      "uk": "<b>1. Позитивна умова</b><br><table><tr><th>Підрядне речення</th><th>Іменникова група</th></tr><tr><td><g>wenn</g> es <g>regnet</g></td><td><g>bei</g> <g>Regen</g> (Dat.)</td></tr><tr><td><g>falls</g> Sie <g>Fragen haben</g></td><td><g>im Falle</g> von <g>Fragen</g> / <g>bei</g> <g>Fragen</g></td></tr><tr><td><g>wenn</g> es <g>nötig ist</g></td><td><g>bei</g> <g>Bedarf</g> / <g>im Bedarfsfall</g></td></tr><tr><td><g>falls</g> ein <g>Schaden entsteht</g></td><td><g>im Schadensfall</g> / <g>im Falle</g> eines <g>Schadens</g> (Gen.)</td></tr></table><br><br><g>Bei</g> часто стоїть без артикля: <g>bei Regen, bei Verspätung, bei Interesse</g>. З прикметником стоїть давальний: <g>bei starkem Regen</g>. Є також <g>unter der Voraussetzung</g> + родовий: <g>unter der Voraussetzung eines Vertrags</g>.<br><br><g>Falls</g> du <g>Fragen hast</g>, ruf mich an.<br>Якщо в тебе є запитання, зателефонуй мені.<br><g>Bei Fragen</g> ruf mich an.<br>У разі запитань зателефонуй мені.<br><br><b>2. Негативна умова: ohne</b><br>Умова «якщо не» передається через <g>ohne</g> + знахідний або <g>bei fehlendem / fehlender</g> + іменник. У Konjunktiv II нереальна умова також передається через <g>ohne</g> (<g>Ohne Plan ginge es nicht.</g>) або через <g>mit</g> (<g>Mit etwas Glück hätten wir gewonnen.</g>).<br><br><g>Wenn</g> es <g>keinen Plan gäbe</g>, ginge es nicht.<br>Якби не було плану, нічого б не вийшло.<br><g>Ohne Plan</g> ginge es nicht.<br>Без плану нічого б не вийшло.<br><g>Wenn</g> die Unterlagen <g>fehlen</g>, wird der Antrag abgelehnt.<br>Якщо документів бракує, заяву відхиляють.<br><g>Bei fehlenden</g> Unterlagen wird der Antrag abgelehnt.<br>У разі відсутності документів заяву відхиляють.<br><br><b>3. Стиль і зворотне перетворення</b><br>Ці іменникові групи типові для договорів, приписів і оголошень: <g>bei Nichtzahlung, im Schadensfall, bei Bedarf</g>. У зворотному напрямку ти додаєш підмет, дієслово й час: <g>bei Verspätung</g> → <g>wenn der Zug Verspätung hat</g>. Вибір між <g>wenn</g> і <g>falls</g> залежить від імовірності: <g>falls</g> звучить непевніше.",
      "ru": "<b>1. Положительное условие</b><br><table><tr><th>Придаточное</th><th>Именная группа</th></tr><tr><td><g>wenn</g> es <g>regnet</g></td><td><g>bei</g> <g>Regen</g> (Dat.)</td></tr><tr><td><g>falls</g> Sie <g>Fragen haben</g></td><td><g>im Falle</g> von <g>Fragen</g> / <g>bei</g> <g>Fragen</g></td></tr><tr><td><g>wenn</g> es <g>nötig ist</g></td><td><g>bei</g> <g>Bedarf</g> / <g>im Bedarfsfall</g></td></tr><tr><td><g>falls</g> ein <g>Schaden entsteht</g></td><td><g>im Schadensfall</g> / <g>im Falle</g> eines <g>Schadens</g> (Gen.)</td></tr></table><br><br><g>Bei</g> часто стоит без артикля: <g>bei Regen, bei Verspätung, bei Interesse</g>. С прилагательным стоит дательный: <g>bei starkem Regen</g>. Есть также <g>unter der Voraussetzung</g> + родительный: <g>unter der Voraussetzung eines Vertrags</g>.<br><br><g>Falls</g> du <g>Fragen hast</g>, ruf mich an.<br>Если у тебя есть вопросы, позвони мне.<br><g>Bei Fragen</g> ruf mich an.<br>В случае вопросов позвони мне.<br><br><b>2. Отрицательное условие: ohne</b><br>Условие «если не» выражается через <g>ohne</g> + винительный или через <g>bei fehlendem / fehlender</g> + существительное. В Konjunktiv II нереальное условие также выражается через <g>ohne</g> (<g>Ohne Plan ginge es nicht.</g>) или через <g>mit</g> (<g>Mit etwas Glück hätten wir gewonnen.</g>).<br><br><g>Wenn</g> es <g>keinen Plan gäbe</g>, ginge es nicht.<br>Если бы не было плана, ничего бы не получилось.<br><g>Ohne Plan</g> ginge es nicht.<br>Без плана ничего бы не получилось.<br><g>Wenn</g> die Unterlagen <g>fehlen</g>, wird der Antrag abgelehnt.<br>Если документов не хватает, заявление отклоняют.<br><g>Bei fehlenden</g> Unterlagen wird der Antrag abgelehnt.<br>При отсутствии документов заявление отклоняют.<br><br><b>3. Стиль и обратное преобразование</b><br>Эти именные группы типичны для договоров, предписаний и объявлений: <g>bei Nichtzahlung, im Schadensfall, bei Bedarf</g>. При обратном преобразовании ты добавляешь подлежащее, глагол и время: <g>bei Verspätung</g> → <g>wenn der Zug Verspätung hat</g>. Выбор между <g>wenn</g> и <g>falls</g> зависит от вероятности: <g>falls</g> звучит менее уверенно."
    }
  },
  {
    "id": "passiv_besonderheiten",
    "title": {"de": "Besonderheiten des Passivs", "en": "Special features of the passive", "uk": "Особливості пасиву", "ru": "Особенности пассива"},
    "explanation": {
      "de": "<b>Neben dem normalen Vorgangspassiv gibt es mehrere Sonderformen.</b><br><b>Passiv mit Modalverb:</b> Das Problem <g>muss gelöst werden</g>. <b>Perfekt:</b> Das Haus <g>ist gebaut worden</g> (nicht „geworden“). <b>Unpersönliches Passiv:</b> <g>Es wird</g> hier <g>getanzt</g>. <b>Zustandspassiv:</b> Die Tür <g>ist geschlossen</g>. Statt Passiv kannst du oft <b>man</b>, <b>sich lassen + Infinitiv</b> oder <b>sein + zu + Infinitiv</b> benutzen.<br>Beispiel: Die Brücke <g>ist</g> vor zwei Jahren <g>gebaut worden</g>.",
      "en": "<b>Besides the normal process passive there are several special forms.</b><br><b>Passive with a modal verb:</b> Das Problem <g>muss gelöst werden</g>. <b>Perfect:</b> Das Haus <g>ist gebaut worden</g> (not “geworden”). <b>Impersonal passive:</b> <g>Es wird</g> hier <g>getanzt</g>. <b>Stative passive:</b> Die Tür <g>ist geschlossen</g>. Instead of the passive you can often use <b>man</b>, <b>sich lassen + infinitive</b> or <b>sein + zu + infinitive</b>.<br>Example: Die Brücke <g>ist</g> vor zwei Jahren <g>gebaut worden</g>.<br>The bridge was built two years ago.",
      "uk": "<b>Окрім звичайного пасиву процесу, існує кілька особливих форм.</b><br><b>Пасив із модальним дієсловом:</b> Das Problem <g>muss gelöst werden</g>. <b>Перфект:</b> Das Haus <g>ist gebaut worden</g> (не «geworden»). <b>Безособовий пасив:</b> <g>Es wird</g> hier <g>getanzt</g>. <b>Пасив стану:</b> Die Tür <g>ist geschlossen</g>. Замість пасиву часто можна вжити <b>man</b>, <b>sich lassen + інфінітив</b> або <b>sein + zu + інфінітив</b>.<br>Приклад: Die Brücke <g>ist</g> vor zwei Jahren <g>gebaut worden</g>.<br>Міст збудували два роки тому.",
      "ru": "<b>Кроме обычного пассива процесса, существует несколько особых форм.</b><br><b>Пассив с модальным глаголом:</b> Das Problem <g>muss gelöst werden</g>. <b>Перфект:</b> Das Haus <g>ist gebaut worden</g> (не «geworden»). <b>Безличный пассив:</b> <g>Es wird</g> hier <g>getanzt</g>. <b>Пассив состояния:</b> Die Tür <g>ist geschlossen</g>. Вместо пассива часто можно употребить <b>man</b>, <b>sich lassen + инфинитив</b> или <b>sein + zu + инфинитив</b>.<br>Пример: Die Brücke <g>ist</g> vor zwei Jahren <g>gebaut worden</g>.<br>Мост построили два года назад."
    },
    "rule": {
      "de": "<b>1. Vorgangspassiv in allen Zeiten</b><br><table><tr><th>Zeit</th><th>Beispiel</th></tr><tr><td>Präsens</td><td>Das Haus <g>wird gebaut</g>.</td></tr><tr><td>Präteritum</td><td>Das Haus <g>wurde gebaut</g>.</td></tr><tr><td>Perfekt</td><td>Das Haus <g>ist gebaut worden</g>.</td></tr><tr><td>Plusquamperfekt</td><td>Das Haus <g>war gebaut worden</g>.</td></tr><tr><td>Futur I</td><td>Das Haus <g>wird gebaut werden</g>.</td></tr></table><br><br>Im Passiv Perfekt steht immer <g>worden</g>, nie <g>geworden</g>. Der Handelnde steht mit <g>von</g> + Dativ (Person) oder <g>durch</g> + Akkusativ (Mittel, Ursache): <g>von den Arbeitern gebaut</g>, <g>durch einen Sturm zerstört</g>.<br><br><b>2. Passiv mit Modalverb</b><br>Form: Modalverb + Partizip II + <g>werden</g> (Infinitiv Passiv). Im Nebensatz steht das Modalverb am Ende: <g>…, weil das Problem gelöst werden muss</g>. Für die Vergangenheit benutzt man meist das Präteritum: <g>Das Problem musste gelöst werden.</g><br><br>Die Anträge <g>müssen</g> bis Freitag <g>abgegeben werden</g>.<br>Das <g>kann</g> nicht <g>akzeptiert werden</g>.<br><br><b>3. Unpersönliches Passiv</b><br>Das unpersönliche Passiv hat <b>kein Subjekt</b>. Es entsteht bei Verben ohne Akkusativobjekt. Das Platzhalter-<g>es</g> steht nur auf Position 1; sonst entfällt es. Verben mit Dativ oder Präposition behalten ihre Ergänzung.<br><br><g>Es wird</g> hier <g>getanzt</g>. / Hier <g>wird getanzt</g>.<br>Dem Kind <g>wird geholfen</g>.<br>Auf ihn <g>wird</g> schon lange <g>gewartet</g>.<br><br><b>4. Zustandspassiv</b><br>Das Zustandspassiv (<g>sein</g> + Partizip II) beschreibt das <b>Ergebnis</b> einer Handlung. Das Vorgangspassiv (<g>werden</g> + Partizip II) beschreibt den <b>Vorgang</b>.<br><br>Die Tür <g>wird geschlossen</g>.<br>Die Tür <g>ist geschlossen</g>.<br>Das Geschäft <g>war</g> bis 18 Uhr <g>geöffnet</g>.<br><br><b>5. Ersatzformen für das Passiv</b><br><table><tr><th>Form</th><th>Beispiel</th></tr><tr><td><g>man</g> + Aktiv</td><td><g>Man</g> löst das Problem.</td></tr><tr><td><g>sich lassen</g> + Infinitiv (= können)</td><td>Das Problem <g>lässt sich lösen</g>.</td></tr><tr><td><g>sein</g> + <g>zu</g> + Infinitiv</td><td>Das Problem <g>ist zu lösen</g>.</td></tr><tr><td>Adjektiv auf <g>-bar</g> / <g>-lich</g></td><td>Das Problem ist <g>lösbar</g>.</td></tr><tr><td><g>bekommen / kriegen</g> + Partizip II (Dativpassiv)</td><td>Er <g>bekommt</g> das Auto <g>geschenkt</g>.</td></tr></table><br><br>Das <b>Dativpassiv</b> mit <g>bekommen, erhalten, kriegen</g> macht den Dativ zum Subjekt (<g>Ihm wird das Auto geschenkt</g> → <g>Er bekommt das Auto geschenkt</g>).",
      "en": "<b>1. Process passive in all tenses</b><br><table><tr><th>Tense</th><th>Example</th></tr><tr><td>Präsens</td><td>Das Haus <g>wird gebaut</g>.</td></tr><tr><td>Präteritum</td><td>Das Haus <g>wurde gebaut</g>.</td></tr><tr><td>Perfekt</td><td>Das Haus <g>ist gebaut worden</g>.</td></tr><tr><td>Plusquamperfekt</td><td>Das Haus <g>war gebaut worden</g>.</td></tr><tr><td>Futur I</td><td>Das Haus <g>wird gebaut werden</g>.</td></tr></table><br><br>In the perfect passive <g>worden</g> is always used, never <g>geworden</g>. The agent is introduced with <g>von</g> + dative (person) or <g>durch</g> + accusative (means, cause): <g>von den Arbeitern gebaut</g>, <g>durch einen Sturm zerstört</g>.<br><br><b>2. Passive with a modal verb</b><br>Form: modal verb + past participle + <g>werden</g> (passive infinitive). In a subordinate clause the modal verb is at the end: <g>…, weil das Problem gelöst werden muss</g>. For the past, the simple past is usually used: <g>Das Problem musste gelöst werden.</g><br><br>Die Anträge <g>müssen</g> bis Freitag <g>abgegeben werden</g>.<br>The applications must be submitted by Friday.<br>Das <g>kann</g> nicht <g>akzeptiert werden</g>.<br>That cannot be accepted.<br><br><b>3. Impersonal passive</b><br>The impersonal passive has <b>no subject</b>. It occurs with verbs without an accusative object. The placeholder <g>es</g> stands only in position 1; otherwise it is dropped. Verbs with a dative or a preposition keep their complement.<br><br><g>Es wird</g> hier <g>getanzt</g>. / Hier <g>wird getanzt</g>.<br>There is dancing here.<br>Dem Kind <g>wird geholfen</g>.<br>The child is being helped.<br>Auf ihn <g>wird</g> schon lange <g>gewartet</g>.<br>People have been waiting for him for a long time.<br><br><b>4. Stative passive</b><br>The stative passive (<g>sein</g> + past participle) describes the <b>result</b> of an action. The process passive (<g>werden</g> + past participle) describes the <b>process</b>.<br><br>Die Tür <g>wird geschlossen</g>.<br>The door is being closed. (process)<br>Die Tür <g>ist geschlossen</g>.<br>The door is closed. (result)<br>Das Geschäft <g>war</g> bis 18 Uhr <g>geöffnet</g>.<br>The shop was open until 6 pm.<br><br><b>5. Alternatives to the passive</b><br><table><tr><th>Form</th><th>Example</th></tr><tr><td><g>man</g> + Aktiv</td><td><g>Man</g> löst das Problem.</td></tr><tr><td><g>sich lassen</g> + Infinitiv (= können)</td><td>Das Problem <g>lässt sich lösen</g>.</td></tr><tr><td><g>sein</g> + <g>zu</g> + Infinitiv</td><td>Das Problem <g>ist zu lösen</g>.</td></tr><tr><td>Adjektiv auf <g>-bar</g> / <g>-lich</g></td><td>Das Problem ist <g>lösbar</g>.</td></tr><tr><td><g>bekommen / kriegen</g> + Partizip II (Dativpassiv)</td><td>Er <g>bekommt</g> das Auto <g>geschenkt</g>.</td></tr></table><br><br>The <b>dative passive</b> with <g>bekommen, erhalten, kriegen</g> turns the dative into the subject (<g>Ihm wird das Auto geschenkt</g> → <g>Er bekommt das Auto geschenkt</g>).",
      "uk": "<b>1. Пасив процесу в усіх часах</b><br><table><tr><th>Час</th><th>Приклад</th></tr><tr><td>Präsens</td><td>Das Haus <g>wird gebaut</g>.</td></tr><tr><td>Präteritum</td><td>Das Haus <g>wurde gebaut</g>.</td></tr><tr><td>Perfekt</td><td>Das Haus <g>ist gebaut worden</g>.</td></tr><tr><td>Plusquamperfekt</td><td>Das Haus <g>war gebaut worden</g>.</td></tr><tr><td>Futur I</td><td>Das Haus <g>wird gebaut werden</g>.</td></tr></table><br><br>У пасиві перфекта завжди стоїть <g>worden</g>, ніколи <g>geworden</g>. Виконавець дії вводиться через <g>von</g> + давальний (особа) або <g>durch</g> + знахідний (засіб, причина): <g>von den Arbeitern gebaut</g>, <g>durch einen Sturm zerstört</g>.<br><br><b>2. Пасив із модальним дієсловом</b><br>Форма: модальне дієслово + дієприкметник ІІ + <g>werden</g> (інфінітив пасиву). У підрядному реченні модальне дієслово стоїть наприкінці: <g>…, weil das Problem gelöst werden muss</g>. Для минулого зазвичай вживають Präteritum: <g>Das Problem musste gelöst werden.</g><br><br>Die Anträge <g>müssen</g> bis Freitag <g>abgegeben werden</g>.<br>Заяви потрібно подати до пʼятниці.<br>Das <g>kann</g> nicht <g>akzeptiert werden</g>.<br>Це неприйнятно.<br><br><b>3. Безособовий пасив</b><br>Безособовий пасив <b>не має підмета</b>. Він утворюється від дієслів без додатка в знахідному відмінку. Слово-замінник <g>es</g> стоїть лише на першому місці; в іншому разі воно відпадає. Дієслова з давальним відмінком або прийменником зберігають свій додаток.<br><br><g>Es wird</g> hier <g>getanzt</g>. / Hier <g>wird getanzt</g>.<br>Тут танцюють.<br>Dem Kind <g>wird geholfen</g>.<br>Дитині допомагають.<br>Auf ihn <g>wird</g> schon lange <g>gewartet</g>.<br>На нього вже давно чекають.<br><br><b>4. Пасив стану</b><br>Пасив стану (<g>sein</g> + дієприкметник ІІ) описує <b>результат</b> дії. Пасив процесу (<g>werden</g> + дієприкметник ІІ) описує <b>процес</b>.<br><br>Die Tür <g>wird geschlossen</g>.<br>Двері зачиняють. (процес)<br>Die Tür <g>ist geschlossen</g>.<br>Двері зачинені. (результат)<br>Das Geschäft <g>war</g> bis 18 Uhr <g>geöffnet</g>.<br>Магазин був відчинений до 18:00.<br><br><b>5. Замінники пасиву</b><br><table><tr><th>Форма</th><th>Приклад</th></tr><tr><td><g>man</g> + Aktiv</td><td><g>Man</g> löst das Problem.</td></tr><tr><td><g>sich lassen</g> + Infinitiv (= können)</td><td>Das Problem <g>lässt sich lösen</g>.</td></tr><tr><td><g>sein</g> + <g>zu</g> + Infinitiv</td><td>Das Problem <g>ist zu lösen</g>.</td></tr><tr><td>Adjektiv auf <g>-bar</g> / <g>-lich</g></td><td>Das Problem ist <g>lösbar</g>.</td></tr><tr><td><g>bekommen / kriegen</g> + Partizip II (Dativpassiv)</td><td>Er <g>bekommt</g> das Auto <g>geschenkt</g>.</td></tr></table><br><br><b>Пасив давального відмінка</b> з <g>bekommen, erhalten, kriegen</g> робить давальний відмінок підметом (<g>Ihm wird das Auto geschenkt</g> → <g>Er bekommt das Auto geschenkt</g>).",
      "ru": "<b>1. Пассив процесса во всех временах</b><br><table><tr><th>Время</th><th>Пример</th></tr><tr><td>Präsens</td><td>Das Haus <g>wird gebaut</g>.</td></tr><tr><td>Präteritum</td><td>Das Haus <g>wurde gebaut</g>.</td></tr><tr><td>Perfekt</td><td>Das Haus <g>ist gebaut worden</g>.</td></tr><tr><td>Plusquamperfekt</td><td>Das Haus <g>war gebaut worden</g>.</td></tr><tr><td>Futur I</td><td>Das Haus <g>wird gebaut werden</g>.</td></tr></table><br><br>В пассиве перфекта всегда стоит <g>worden</g>, никогда <g>geworden</g>. Исполнитель вводится через <g>von</g> + дательный (лицо) или <g>durch</g> + винительный (средство, причина): <g>von den Arbeitern gebaut</g>, <g>durch einen Sturm zerstört</g>.<br><br><b>2. Пассив с модальным глаголом</b><br>Форма: модальный глагол + причастие II + <g>werden</g> (инфинитив пассива). В придаточном предложении модальный глагол стоит в конце: <g>…, weil das Problem gelöst werden muss</g>. Для прошедшего обычно употребляют Präteritum: <g>Das Problem musste gelöst werden.</g><br><br>Die Anträge <g>müssen</g> bis Freitag <g>abgegeben werden</g>.<br>Заявления нужно подать до пятницы.<br>Das <g>kann</g> nicht <g>akzeptiert werden</g>.<br>Это нельзя принять.<br><br><b>3. Безличный пассив</b><br>Безличный пассив <b>не имеет подлежащего</b>. Он образуется от глаголов без дополнения в винительном падеже. Слово-заместитель <g>es</g> стоит только на первом месте; в остальных случаях оно отпадает. Глаголы с дательным падежом или предлогом сохраняют своё дополнение.<br><br><g>Es wird</g> hier <g>getanzt</g>. / Hier <g>wird getanzt</g>.<br>Здесь танцуют.<br>Dem Kind <g>wird geholfen</g>.<br>Ребёнку помогают.<br>Auf ihn <g>wird</g> schon lange <g>gewartet</g>.<br>Его уже давно ждут.<br><br><b>4. Пассив состояния</b><br>Пассив состояния (<g>sein</g> + причастие II) описывает <b>результат</b> действия. Пассив процесса (<g>werden</g> + причастие II) описывает <b>процесс</b>.<br><br>Die Tür <g>wird geschlossen</g>.<br>Дверь закрывают. (процесс)<br>Die Tür <g>ist geschlossen</g>.<br>Дверь закрыта. (результат)<br>Das Geschäft <g>war</g> bis 18 Uhr <g>geöffnet</g>.<br>Магазин был открыт до 18:00.<br><br><b>5. Заменители пассива</b><br><table><tr><th>Форма</th><th>Пример</th></tr><tr><td><g>man</g> + Aktiv</td><td><g>Man</g> löst das Problem.</td></tr><tr><td><g>sich lassen</g> + Infinitiv (= können)</td><td>Das Problem <g>lässt sich lösen</g>.</td></tr><tr><td><g>sein</g> + <g>zu</g> + Infinitiv</td><td>Das Problem <g>ist zu lösen</g>.</td></tr><tr><td>Adjektiv auf <g>-bar</g> / <g>-lich</g></td><td>Das Problem ist <g>lösbar</g>.</td></tr><tr><td><g>bekommen / kriegen</g> + Partizip II (Dativpassiv)</td><td>Er <g>bekommt</g> das Auto <g>geschenkt</g>.</td></tr></table><br><br><b>Пассив дательного падежа</b> с <g>bekommen, erhalten, kriegen</g> превращает дательный падеж в подлежащее (<g>Ihm wird das Auto geschenkt</g> → <g>Er bekommt das Auto geschenkt</g>)."
    }
  },
  {
    "id": "modales_partizip",
    "title": {"de": "Modales Partizip", "en": "Modal participle", "uk": "Модальний дієприкметник", "ru": "Модальное причастие"},
    "explanation": {
      "de": "<b>Das modale Partizip ersetzt einen Relativsatz mit Modalverb im Passiv.</b><br>Es besteht aus <b>zu + Partizip I</b> und steht vor einem Nomen. Es drückt <b>Möglichkeit oder Notwendigkeit im Passiv</b> aus („kann / muss … werden“). Das Partizip bekommt die Endung wie ein Adjektiv.<br>Beispiel: eine <g>zu lösende</g> Aufgabe = eine Aufgabe, die gelöst werden muss",
      "en": "<b>The modal participle replaces a relative clause with a modal verb in the passive.</b><br>It consists of <b>zu + present participle</b> and stands before a noun. It expresses <b>possibility or necessity in the passive</b> (“can / must be …”). The participle takes an adjective ending.<br>Example: eine <g>zu lösende</g> Aufgabe = eine Aufgabe, die gelöst werden muss<br>a task to be solved = a task that must be solved",
      "uk": "<b>Модальний дієприкметник замінює означальне речення з модальним дієсловом у пасиві.</b><br>Воно складається з <b>zu + Partizip I</b> і стоїть перед іменником. Воно виражає <b>можливість або необхідність у пасиві</b> («може / має бути …»). Дієприкметник отримує закінчення, як прикметник.<br>Приклад: eine <g>zu lösende</g> Aufgabe = eine Aufgabe, die gelöst werden muss<br>завдання, яке потрібно розвʼязати = завдання, яке має бути розвʼязане",
      "ru": "<b>Модальное причастие заменяет определительное придаточное с модальным глаголом в пассиве.</b><br>Оно состоит из <b>zu + Partizip I</b> и стоит перед существительным. Оно выражает <b>возможность или необходимость в пассиве</b> («может / должно быть …»). Причастие получает окончание, как прилагательное.<br>Пример: eine <g>zu lösende</g> Aufgabe = eine Aufgabe, die gelöst werden muss<br>задача, которую нужно решить = задача, которая должна быть решена"
    },
    "rule": {
      "de": "<b>1. Bildung</b><br><b>zu</b> + Infinitiv + <b>-d</b> + Adjektivendung: <g>lösen</g> → <g>zu lösend</g> → <g>die zu lösende Aufgabe</g>. Bei trennbaren Verben steht <g>zu</g> zwischen Präfix und Stamm: <g>abholen</g> → <g>die abzuholende Ware</g>. Das Partizip richtet sich nach Artikel, Kasus, Genus und Numerus des Nomens.<br><br>die <g>zu erledigenden</g> Aufgaben<br>mit dem <g>zu zahlenden</g> Betrag<br>die <g>einzuhaltenden</g> Fristen<br><br><b>2. Bedeutung</b><br>Je nach Kontext bedeutet das modale Partizip <b>können, müssen, sollen</b> oder <b>dürfen</b> im Passiv. Mit <g>nicht</g> oder <g>kaum</g> steht es für <b>können nicht</b> oder <b>dürfen nicht</b>.<br><br><table><tr><th>Modales Partizip</th><th>Relativsatz</th></tr><tr><td>eine <g>zu lösende</g> Aufgabe</td><td>eine Aufgabe, die gelöst werden <b>muss</b> / <b>kann</b></td></tr><tr><td>ein <g>nicht zu unterschätzendes</g> Risiko</td><td>ein Risiko, das man <b>nicht</b> unterschätzen <b>darf</b></td></tr><tr><td>ein <g>kaum zu lösendes</g> Problem</td><td>ein Problem, das <b>kaum</b> gelöst werden <b>kann</b></td></tr><tr><td>die <g>zu erwartende</g> Entwicklung</td><td>die Entwicklung, die man erwarten <b>kann</b></td></tr></table><br><br><b>3. Umformung</b><br>Die Aufgabe, <g>die</g> sofort <g>gelöst werden muss</g>, ist wichtig.<br>Die <g>sofort zu lösende</g> Aufgabe ist wichtig.<br>Die Aufgabe <g>ist</g> sofort <g>zu lösen</g>.<br><br>Das modale Partizip kann lange Attribute bilden: <g>die von allen Mitarbeitern bis Freitag zu erledigenden Aufgaben</g> (erweitertes Partizipialattribut). Alle Angaben stehen zwischen Artikel und Partizip.<br><br><b>4. Einschränkungen</b><br>Das modale Partizip gibt es nur bei Verben, die ein Passiv bilden können (also bei transitiven Verben). Es ist typisch für die Schriftsprache. Bei Verben ohne Passiv ist es nicht möglich: nicht <g>der zu schlafende Mann</g>.",
      "en": "<b>1. Formation</b><br><b>zu</b> + infinitive + <b>-d</b> + adjective ending: <g>lösen</g> → <g>zu lösend</g> → <g>die zu lösende Aufgabe</g>. With separable verbs <g>zu</g> goes between the prefix and the stem: <g>abholen</g> → <g>die abzuholende Ware</g>. The participle agrees with article, case, gender and number of the noun.<br><br>die <g>zu erledigenden</g> Aufgaben<br>the tasks to be completed<br>mit dem <g>zu zahlenden</g> Betrag<br>with the amount to be paid<br>die <g>einzuhaltenden</g> Fristen<br>the deadlines to be met<br><br><b>2. Meaning</b><br>Depending on the context, the modal participle means <b>can, must, should</b> or <b>may</b> in the passive. With <g>nicht</g> or <g>kaum</g> it stands for <b>cannot</b> or <b>must not</b>.<br><br><table><tr><th>Modal participle</th><th>Relative clause</th></tr><tr><td>eine <g>zu lösende</g> Aufgabe</td><td>eine Aufgabe, die gelöst werden <b>muss</b> / <b>kann</b></td></tr><tr><td>ein <g>nicht zu unterschätzendes</g> Risiko</td><td>ein Risiko, das man <b>nicht</b> unterschätzen <b>darf</b></td></tr><tr><td>ein <g>kaum zu lösendes</g> Problem</td><td>ein Problem, das <b>kaum</b> gelöst werden <b>kann</b></td></tr><tr><td>die <g>zu erwartende</g> Entwicklung</td><td>die Entwicklung, die man erwarten <b>kann</b></td></tr></table><br><br><b>3. Paraphrase</b><br>Die Aufgabe, <g>die</g> sofort <g>gelöst werden muss</g>, ist wichtig.<br>The task that has to be solved at once is important.<br>Die <g>sofort zu lösende</g> Aufgabe ist wichtig.<br>The task to be solved at once is important. (modal participle)<br>Die Aufgabe <g>ist</g> sofort <g>zu lösen</g>.<br>The task is to be solved at once. (sein + zu)<br><br>The modal participle can form long attributes: <g>die von allen Mitarbeitern bis Freitag zu erledigenden Aufgaben</g> (extended participial attribute). All the details stand between the article and the participle.<br><br><b>4. Restrictions</b><br>The modal participle exists only for verbs that can form a passive (that is, transitive verbs). It is typical of written language. It is not possible with verbs that have no passive: not <g>der zu schlafende Mann</g>.",
      "uk": "<b>1. Утворення</b><br><b>zu</b> + інфінітив + <b>-d</b> + закінчення прикметника: <g>lösen</g> → <g>zu lösend</g> → <g>die zu lösende Aufgabe</g>. У віддільних дієсловах <g>zu</g> стоїть між префіксом і коренем: <g>abholen</g> → <g>die abzuholende Ware</g>. Дієприкметник узгоджується з артиклем, відмінком, родом і числом іменника.<br><br>die <g>zu erledigenden</g> Aufgaben<br>завдання, які потрібно виконати<br>mit dem <g>zu zahlenden</g> Betrag<br>із сумою, яку потрібно сплатити<br>die <g>einzuhaltenden</g> Fristen<br>терміни, яких слід дотримуватися<br><br><b>2. Значення</b><br>Залежно від контексту модальний дієприкметник означає <b>можна, треба, слід</b> або <b>дозволено</b> у пасиві. З <g>nicht</g> або <g>kaum</g> він означає <b>не можна</b> або <b>не слід</b>.<br><br><table><tr><th>Модальний дієприкметник</th><th>Означальне речення</th></tr><tr><td>eine <g>zu lösende</g> Aufgabe</td><td>eine Aufgabe, die gelöst werden <b>muss</b> / <b>kann</b></td></tr><tr><td>ein <g>nicht zu unterschätzendes</g> Risiko</td><td>ein Risiko, das man <b>nicht</b> unterschätzen <b>darf</b></td></tr><tr><td>ein <g>kaum zu lösendes</g> Problem</td><td>ein Problem, das <b>kaum</b> gelöst werden <b>kann</b></td></tr><tr><td>die <g>zu erwartende</g> Entwicklung</td><td>die Entwicklung, die man erwarten <b>kann</b></td></tr></table><br><br><b>3. Перефразування</b><br>Die Aufgabe, <g>die</g> sofort <g>gelöst werden muss</g>, ist wichtig.<br>Завдання, яке треба негайно розвʼязати, важливе.<br>Die <g>sofort zu lösende</g> Aufgabe ist wichtig.<br>Завдання, яке треба негайно розвʼязати, важливе. (модальний дієприкметник)<br>Die Aufgabe <g>ist</g> sofort <g>zu lösen</g>.<br>Завдання слід негайно розвʼязати. (sein + zu)<br><br>Модальний дієприкметник може утворювати довгі означення: <g>die von allen Mitarbeitern bis Freitag zu erledigenden Aufgaben</g> (поширене дієприкметникове означення). Усі уточнення стоять між артиклем і дієприкметником.<br><br><b>4. Обмеження</b><br>Модальний дієприкметник існує лише в дієслів, що можуть утворювати пасив (тобто перехідних). Він типовий для писемної мови. У дієслів без пасиву він неможливий: не <g>der zu schlafende Mann</g>.",
      "ru": "<b>1. Образование</b><br><b>zu</b> + инфинитив + <b>-d</b> + окончание прилагательного: <g>lösen</g> → <g>zu lösend</g> → <g>die zu lösende Aufgabe</g>. У отделяемых глаголов <g>zu</g> стоит между приставкой и корнем: <g>abholen</g> → <g>die abzuholende Ware</g>. Причастие согласуется с артиклем, падежом, родом и числом существительного.<br><br>die <g>zu erledigenden</g> Aufgaben<br>задачи, которые нужно выполнить<br>mit dem <g>zu zahlenden</g> Betrag<br>с суммой, которую нужно оплатить<br>die <g>einzuhaltenden</g> Fristen<br>сроки, которые нужно соблюдать<br><br><b>2. Значение</b><br>В зависимости от контекста модальное причастие означает <b>можно, нужно, следует</b> или <b>разрешено</b> в пассиве. С <g>nicht</g> или <g>kaum</g> оно означает <b>нельзя</b> или <b>не следует</b>.<br><br><table><tr><th>Модальное причастие</th><th>Определительное придаточное</th></tr><tr><td>eine <g>zu lösende</g> Aufgabe</td><td>eine Aufgabe, die gelöst werden <b>muss</b> / <b>kann</b></td></tr><tr><td>ein <g>nicht zu unterschätzendes</g> Risiko</td><td>ein Risiko, das man <b>nicht</b> unterschätzen <b>darf</b></td></tr><tr><td>ein <g>kaum zu lösendes</g> Problem</td><td>ein Problem, das <b>kaum</b> gelöst werden <b>kann</b></td></tr><tr><td>die <g>zu erwartende</g> Entwicklung</td><td>die Entwicklung, die man erwarten <b>kann</b></td></tr></table><br><br><b>3. Перефразирование</b><br>Die Aufgabe, <g>die</g> sofort <g>gelöst werden muss</g>, ist wichtig.<br>Задача, которую нужно немедленно решить, важна.<br>Die <g>sofort zu lösende</g> Aufgabe ist wichtig.<br>Задача, которую нужно немедленно решить, важна. (модальное причастие)<br>Die Aufgabe <g>ist</g> sofort <g>zu lösen</g>.<br>Задачу следует немедленно решить. (sein + zu)<br><br>Модальное причастие может образовывать длинные определения: <g>die von allen Mitarbeitern bis Freitag zu erledigenden Aufgaben</g> (распространённое причастное определение). Все уточнения стоят между артиклем и причастием.<br><br><b>4. Ограничения</b><br>Модальное причастие существует только у глаголов, которые могут образовывать пассив (то есть переходных). Оно типично для письменной речи. У глаголов без пассива оно невозможно: нельзя <g>der zu schlafende Mann</g>."
    }
  },
  {
    "id": "partizipialattribute",
    "title": {"de": "Partizipialattribute: Partizip I und II als Attribut", "en": "Participial attributes: present and past participle before a noun", "uk": "Дієприкметникові означення: Partizip I і II перед іменником", "ru": "Причастные определения: Partizip I и II перед существительным"},
    "explanation": {
      "de": "<b>Ein Partizip kann wie ein Adjektiv vor einem Nomen stehen.</b><br>Das <b>Partizip I</b> (Infinitiv + <g>-d</g>) ist aktiv und gleichzeitig: <g>die steigenden Preise</g> = die Preise, die steigen. Das <b>Partizip II</b> ist meist passiv und vorzeitig: <g>das gestohlene Auto</g> = das Auto, das gestohlen wurde. Das Partizip bekommt die Adjektivendung und kann mit Zusätzen zu einem langen <b>erweiterten Attribut</b> werden.<br>Beispiel: das <g>gestern gestohlene</g> Auto = das Auto, das gestern gestohlen wurde",
      "en": "<b>A participle can stand before a noun like an adjective.</b><br>The <b>present participle</b> (infinitive + <g>-d</g>) is active and simultaneous: <g>die steigenden Preise</g> = the prices that are rising. The <b>past participle</b> is mostly passive and prior: <g>das gestohlene Auto</g> = the car that was stolen. The participle takes the adjective ending and, with additions, can become a long <b>extended attribute</b>.<br>Example: das <g>gestern gestohlene</g> Auto = das Auto, das gestern gestohlen wurde<br>the car stolen yesterday = the car that was stolen yesterday",
      "uk": "<b>Дієприкметник може стояти перед іменником, як прикметник.</b><br><b>Partizip I</b> (інфінітив + <g>-d</g>) має активне значення й означає одночасну дію: <g>die steigenden Preise</g> = ціни, що зростають. <b>Partizip II</b> здебільшого пасивний і означає попередню дію: <g>das gestohlene Auto</g> = авто, яке вкрали. Дієприкметник отримує закінчення прикметника й, з доповненнями, може стати довгим <b>поширеним означенням</b>.<br>Приклад: das <g>gestern gestohlene</g> Auto = das Auto, das gestern gestohlen wurde<br>авто, вкрадене вчора = авто, яке вкрали вчора",
      "ru": "<b>Причастие может стоять перед существительным, как прилагательное.</b><br><b>Partizip I</b> (инфинитив + <g>-d</g>) имеет активное значение и означает одновременное действие: <g>die steigenden Preise</g> = цены, которые растут. <b>Partizip II</b> в основном пассивный и означает предшествующее действие: <g>das gestohlene Auto</g> = автомобиль, который украли. Причастие получает окончание прилагательного и с дополнениями может стать длинным <b>распространённым определением</b>.<br>Пример: das <g>gestern gestohlene</g> Auto = das Auto, das gestern gestohlen wurde<br>автомобиль, украденный вчера = автомобиль, который украли вчера"
    },
    "rule": {
      "de": "<b>1. Partizip I und Partizip II</b><br><table><tr><th>Partizip I</th><th>Partizip II</th></tr><tr><td>Infinitiv + <g>d</g>:<br><g>lachen</g> → <g>lachend</g></td><td><g>ge-</g> … <g>-t</g> / <g>-en</g>:<br><g>stehlen</g> → <g>gestohlen</g></td></tr><tr><td>aktiv, gleichzeitig</td><td>meist passiv, vorzeitig</td></tr><tr><td>die <g>steigenden</g> Preise</td><td>das <g>gestohlene</g> Auto</td></tr><tr><td>der <g>schlafende</g> Hund</td><td>der <g>festgenommene</g> Verdächtige</td></tr></table><br><br>Die Endung richtet sich nach Artikel, Kasus, Genus und Numerus des Nomens: <g>der steigende Preis</g>, <g>die steigenden Preise</g>, <g>mit steigenden Preisen</g>.<br><br><b>2. Bedeutung und Voraussetzungen</b><br><b>Partizip I</b> kann man von den meisten Verben bilden (nicht von <g>sein</g>, <g>haben</g> und Modalverben im üblichen Sinn). <b>Partizip II</b> steht bei transitiven Verben mit <b>passiver</b> Bedeutung (<g>das gelesene Buch</g> = das Buch, das gelesen wurde). Bei Verben der Bewegung und Zustandsänderung mit <g>sein</g> hat es <b>aktive</b> Bedeutung (<g>der angekommene Zug</g> = der Zug, der angekommen ist). Bei intransitiven Verben mit <g>haben</g> ist kein Partizip II als Attribut möglich: nicht <g>der geschlafene Mann</g>.<br><br>Viele Partizipien werden zu Nomen: <g>der Angeklagte</g> – <g>ein Angeklagter</g>, <g>die Verletzten</g>, <g>der Reisende</g>. Sie werden wie Adjektive dekliniert.<br><br><b>3. Das erweiterte Partizipialattribut</b><br>Alle Zusätze (Orts-, Zeit-, Art-Angaben, Objekte, Agens mit <g>von</g>) stehen zwischen dem Artikel und dem Partizip. Das Nomen kommt erst am Ende. Das Attribut ersetzt einen Relativsatz.<br><br>der <g>seit zwei Jahren</g> <g>von der Polizei gesuchte</g> Täter<br>die <g>den Prozess begleitende</g> Presse<br>der <g>vor einer Woche aus der Haft entlassene</g> Mann<br><br><b>4. In einen Relativsatz umformen</b><br><b>1.</b> Finde das Partizip und das Nomen.<br><b>2.</b> Bilde einen Relativsatz mit dem passenden Relativpronomen.<br><b>3.</b> Bei Partizip I: Verb im Präsens (aktiv). Bei Partizip II mit passiver Bedeutung: Passiv (<g>wurde … / ist … worden</g>). Bei Partizip II mit aktiver Bedeutung: Perfekt (<g>ist angekommen</g>).<br><b>4.</b> Alle Zusätze kommen vor das Verb am Satzende.<br><br>die <g>steigenden</g> Preise → die Preise, <g>die steigen</g><br>das <g>gestohlene</g> Auto → das Auto, <g>das gestohlen wurde</g><br>der <g>angekommene</g> Zug → der Zug, <g>der angekommen ist</g><br><br><b>5. Stil und Grenzen</b><br>Partizipialattribute sind typisch für Nachrichten, Gesetze, Urteile und wissenschaftliche Texte. Sie machen Sätze knapp, aber sehr lange Attribute sind schwer zu lesen. Dann ist ein Relativsatz besser. Eine Variante mit <g>zu</g> + Partizip I siehst du im Thema „Modales Partizip“: <g>die zu lösende Aufgabe</g>.",
      "en": "<b>1. Present and past participle</b><br><table><tr><th>Present participle</th><th>Past participle</th></tr><tr><td>infinitive + <g>d</g>:<br><g>lachen</g> → <g>lachend</g></td><td><g>ge-</g> … <g>-t</g> / <g>-en</g>:<br><g>stehlen</g> → <g>gestohlen</g></td></tr><tr><td>active, simultaneous</td><td>mostly passive, prior</td></tr><tr><td>die <g>steigenden</g> Preise</td><td>das <g>gestohlene</g> Auto</td></tr><tr><td>der <g>schlafende</g> Hund</td><td>der <g>festgenommene</g> Verdächtige</td></tr></table><br><br>The ending depends on article, case, gender and number of the noun: <g>der steigende Preis</g>, <g>die steigenden Preise</g>, <g>mit steigenden Preisen</g>.<br><br><b>2. Meaning and requirements</b><br>The <b>present participle</b> can be formed from most verbs (not from <g>sein</g>, <g>haben</g> and modal verbs in their usual sense). The <b>past participle</b> has a <b>passive</b> meaning with transitive verbs (<g>das gelesene Buch</g> = the book that was read). With verbs of movement and change of state that take <g>sein</g> it has an <b>active</b> meaning (<g>der angekommene Zug</g> = the train that has arrived). With intransitive verbs that take <g>haben</g>, no past participle as an attribute is possible: not <g>der geschlafene Mann</g>.<br><br>Many participles become nouns: <g>der Angeklagte</g> – <g>ein Angeklagter</g>, <g>die Verletzten</g>, <g>der Reisende</g>. They are declined like adjectives.<br><br><b>3. The extended participial attribute</b><br>All additions (place, time, manner, objects, agent with <g>von</g>) stand between the article and the participle. The noun comes only at the end. The attribute replaces a relative clause.<br><br>der <g>seit zwei Jahren</g> <g>von der Polizei gesuchte</g> Täter<br>the offender wanted by the police for two years<br>die <g>den Prozess begleitende</g> Presse<br>the press covering the trial<br>der <g>vor einer Woche aus der Haft entlassene</g> Mann<br>the man released from custody a week ago<br><br><b>4. Converting into a relative clause</b><br><b>1.</b> Find the participle and the noun.<br><b>2.</b> Form a relative clause with the right relative pronoun.<br><b>3.</b> With the present participle: verb in the present (active). With a past participle of passive meaning: passive (<g>wurde … / ist … worden</g>). With a past participle of active meaning: perfect (<g>ist angekommen</g>).<br><b>4.</b> All additions go before the verb at the end of the clause.<br><br>die <g>steigenden</g> Preise → die Preise, <g>die steigen</g><br>the rising prices → the prices that are rising<br>das <g>gestohlene</g> Auto → das Auto, <g>das gestohlen wurde</g><br>the stolen car → the car that was stolen<br>der <g>angekommene</g> Zug → der Zug, <g>der angekommen ist</g><br>the arrived train → the train that has arrived<br><br><b>5. Style and limits</b><br>Participial attributes are typical of news, laws, judgments and academic texts. They make sentences concise, but very long attributes are hard to read. A relative clause is then better. You will find the variant with <g>zu</g> + present participle in the topic “Modal participle”: <g>die zu lösende Aufgabe</g>.",
      "uk": "<b>1. Partizip I і Partizip II</b><br><table><tr><th>Partizip I</th><th>Partizip II</th></tr><tr><td>інфінітив + <g>d</g>:<br><g>lachen</g> → <g>lachend</g></td><td><g>ge-</g> … <g>-t</g> / <g>-en</g>:<br><g>stehlen</g> → <g>gestohlen</g></td></tr><tr><td>активне, одночасне</td><td>здебільшого пасивне, попереднє</td></tr><tr><td>die <g>steigenden</g> Preise</td><td>das <g>gestohlene</g> Auto</td></tr><tr><td>der <g>schlafende</g> Hund</td><td>der <g>festgenommene</g> Verdächtige</td></tr></table><br><br>Закінчення залежить від артикля, відмінка, роду й числа іменника: <g>der steigende Preis</g>, <g>die steigenden Preise</g>, <g>mit steigenden Preisen</g>.<br><br><b>2. Значення й умови</b><br><b>Partizip I</b> можна утворити від більшості дієслів (не від <g>sein</g>, <g>haben</g> і модальних дієслів у звичайному значенні). <b>Partizip II</b> у перехідних дієслів має <b>пасивне</b> значення (<g>das gelesene Buch</g> = книжка, яку прочитали). У дієслів руху та зміни стану з <g>sein</g> він має <b>активне</b> значення (<g>der angekommene Zug</g> = потяг, що прибув). У неперехідних дієслів з <g>haben</g> Partizip II як означення неможливий: не <g>der geschlafene Mann</g>.<br><br>Багато дієприкметників стають іменниками: <g>der Angeklagte</g> – <g>ein Angeklagter</g>, <g>die Verletzten</g>, <g>der Reisende</g>. Вони відмінюються, як прикметники.<br><br><b>3. Поширене дієприкметникове означення</b><br>Усі доповнення (місце, час, спосіб, додатки, виконавець із <g>von</g>) стоять між артиклем і дієприкметником. Іменник стоїть лише в кінці. Таке означення замінює означальне речення.<br><br>der <g>seit zwei Jahren</g> <g>von der Polizei gesuchte</g> Täter<br>злочинець, якого вже два роки розшукує поліція<br>die <g>den Prozess begleitende</g> Presse<br>преса, що висвітлює процес<br>der <g>vor einer Woche aus der Haft entlassene</g> Mann<br>чоловік, якого звільнили з-під варти тиждень тому<br><br><b>4. Перетворення на означальне речення</b><br><b>1.</b> Знайди дієприкметник та іменник.<br><b>2.</b> Утвори означальне речення з відповідним відносним займенником.<br><b>3.</b> Для Partizip I: дієслово в теперішньому часі (актив). Для Partizip II з пасивним значенням: пасив (<g>wurde … / ist … worden</g>). Для Partizip II з активним значенням: Perfekt (<g>ist angekommen</g>).<br><b>4.</b> Усі доповнення ставляться перед дієсловом наприкінці речення.<br><br>die <g>steigenden</g> Preise → die Preise, <g>die steigen</g><br>ціни, що зростають → ціни, які зростають<br>das <g>gestohlene</g> Auto → das Auto, <g>das gestohlen wurde</g><br>вкрадене авто → авто, яке вкрали<br>der <g>angekommene</g> Zug → der Zug, <g>der angekommen ist</g><br>потяг, що прибув → потяг, який прибув<br><br><b>5. Стиль і межі</b><br>Дієприкметникові означення типові для новин, законів, вироків і наукових текстів. Вони роблять речення стислими, але дуже довгі означення важко читати. Тоді краще означальне речення. Варіант із <g>zu</g> + Partizip I дивись у темі «Модальний дієприкметник»: <g>die zu lösende Aufgabe</g>.",
      "ru": "<b>1. Partizip I и Partizip II</b><br><table><tr><th>Partizip I</th><th>Partizip II</th></tr><tr><td>инфинитив + <g>d</g>:<br><g>lachen</g> → <g>lachend</g></td><td><g>ge-</g> … <g>-t</g> / <g>-en</g>:<br><g>stehlen</g> → <g>gestohlen</g></td></tr><tr><td>активное, одновременное</td><td>в основном пассивное, предшествующее</td></tr><tr><td>die <g>steigenden</g> Preise</td><td>das <g>gestohlene</g> Auto</td></tr><tr><td>der <g>schlafende</g> Hund</td><td>der <g>festgenommene</g> Verdächtige</td></tr></table><br><br>Окончание зависит от артикля, падежа, рода и числа существительного: <g>der steigende Preis</g>, <g>die steigenden Preise</g>, <g>mit steigenden Preisen</g>.<br><br><b>2. Значение и условия</b><br><b>Partizip I</b> можно образовать от большинства глаголов (не от <g>sein</g>, <g>haben</g> и модальных глаголов в обычном значении). <b>Partizip II</b> у переходных глаголов имеет <b>пассивное</b> значение (<g>das gelesene Buch</g> = книга, которую прочитали). У глаголов движения и изменения состояния с <g>sein</g> он имеет <b>активное</b> значение (<g>der angekommene Zug</g> = поезд, который прибыл). У непереходных глаголов с <g>haben</g> Partizip II как определение невозможен: нельзя <g>der geschlafene Mann</g>.<br><br>Многие причастия становятся существительными: <g>der Angeklagte</g> – <g>ein Angeklagter</g>, <g>die Verletzten</g>, <g>der Reisende</g>. Они склоняются, как прилагательные.<br><br><b>3. Распространённое причастное определение</b><br>Все дополнения (место, время, образ действия, дополнения, исполнитель с <g>von</g>) стоят между артиклем и причастием. Существительное стоит только в конце. Такое определение заменяет определительное придаточное.<br><br>der <g>seit zwei Jahren</g> <g>von der Polizei gesuchte</g> Täter<br>преступник, которого уже два года разыскивает полиция<br>die <g>den Prozess begleitende</g> Presse<br>пресса, освещающая процесс<br>der <g>vor einer Woche aus der Haft entlassene</g> Mann<br>мужчина, освобождённый из-под стражи неделю назад<br><br><b>4. Преобразование в определительное придаточное</b><br><b>1.</b> Найди причастие и существительное.<br><b>2.</b> Образуй определительное придаточное с подходящим относительным местоимением.<br><b>3.</b> Для Partizip I: глагол в настоящем времени (актив). Для Partizip II с пассивным значением: пассив (<g>wurde … / ist … worden</g>). Для Partizip II с активным значением: Perfekt (<g>ist angekommen</g>).<br><b>4.</b> Все дополнения ставятся перед глаголом в конце предложения.<br><br>die <g>steigenden</g> Preise → die Preise, <g>die steigen</g><br>растущие цены → цены, которые растут<br>das <g>gestohlene</g> Auto → das Auto, <g>das gestohlen wurde</g><br>украденный автомобиль → автомобиль, который украли<br>der <g>angekommene</g> Zug → der Zug, <g>der angekommen ist</g><br>прибывший поезд → поезд, который прибыл<br><br><b>5. Стиль и границы</b><br>Причастные определения типичны для новостей, законов, приговоров и научных текстов. Они делают предложения краткими, но очень длинные определения трудно читать. Тогда лучше определительное придаточное. Вариант с <g>zu</g> + Partizip I смотри в теме «Модальное причастие»: <g>die zu lösende Aufgabe</g>."
    }
  },
  {
    "id": "subjektive_modalverben_behauptungen",
    "title": {"de": "Subjektive Modalverben: Behauptungen ausdrücken", "en": "Subjective modal verbs: expressing claims", "uk": "Субʼєктивні модальні дієслова: вираження тверджень", "ru": "Субъективные модальные глаголы: выражение утверждений"},
    "explanation": {
      "de": "<b>Mit „wollen“ und „sollen“ gibst du Behauptungen wieder.</b><br><b>Wollen</b> = die Person selbst behauptet es: Er <g>will</g> den Dieb <g>gesehen haben</g>. <b>Sollen</b> = andere sagen es, man hat es gehört: Sie <g>soll</g> sehr reich <g>sein</g>. Du selbst bist nicht sicher, ob es stimmt. Für Vergangenes steht der <b>Infinitiv Perfekt</b> (Partizip II + <g>haben / sein</g>).<br>Beispiel: Er <g>will</g> den Dieb <g>gesehen haben</g>.",
      "en": "<b>With “wollen” and “sollen” you report claims.</b><br><b>Wollen</b> = the person claims it themselves: Er <g>will</g> den Dieb <g>gesehen haben</g>. <b>Sollen</b> = others say it, it is hearsay: Sie <g>soll</g> sehr reich <g>sein</g>. You yourself are not sure whether it is true. For the past the <b>perfect infinitive</b> is used (past participle + <g>haben / sein</g>).<br>Example: Er <g>will</g> den Dieb <g>gesehen haben</g>.<br>He claims to have seen the thief.",
      "uk": "<b>За допомогою «wollen» і «sollen» ти передаєш твердження.</b><br><b>Wollen</b> = особа сама це стверджує: Er <g>will</g> den Dieb <g>gesehen haben</g>. <b>Sollen</b> = це кажуть інші, чули від когось: Sie <g>soll</g> sehr reich <g>sein</g>. Ти сам не певен, чи це правда. Для минулого вживають <b>інфінітив перфекта</b> (дієприкметник ІІ + <g>haben / sein</g>).<br>Приклад: Er <g>will</g> den Dieb <g>gesehen haben</g>.<br>Він стверджує, що бачив злодія.",
      "ru": "<b>С помощью «wollen» и «sollen» ты передаёшь утверждения.</b><br><b>Wollen</b> = лицо само это утверждает: Er <g>will</g> den Dieb <g>gesehen haben</g>. <b>Sollen</b> = это говорят другие, слышали от кого-то: Sie <g>soll</g> sehr reich <g>sein</g>. Ты сам не уверен, правда ли это. Для прошедшего употребляют <b>инфинитив перфекта</b> (причастие II + <g>haben / sein</g>).<br>Пример: Er <g>will</g> den Dieb <g>gesehen haben</g>.<br>Он утверждает, что видел вора."
    },
    "rule": {
      "de": "<b>1. Subjektiver und objektiver Gebrauch</b><br>Modalverben können zwei Funktionen haben. Der <b>objektive</b> Gebrauch beschreibt Wunsch, Pflicht oder Plan des Subjekts. Der <b>subjektive</b> Gebrauch drückt die Haltung des Sprechers zu einer Aussage aus.<br><br><table><tr><th>objektiv</th><th>subjektiv</th></tr><tr><td>Er <g>will</g> nach Berlin <g>fahren</g>. (Wunsch)</td><td>Er <g>will</g> Arzt <g>gewesen sein</g>. (Behauptung)</td></tr><tr><td>Sie <g>soll</g> die Miete <g>zahlen</g>. (Auftrag)</td><td>Sie <g>soll</g> sehr reich <g>sein</g>. (Gerücht)</td></tr></table><br><br><b>2. wollen: Behauptung der Person selbst</b><br>Mit <g>wollen</g> berichtest du, was das Subjekt über sich selbst sagt. Oft zweifelst du daran. Das Subjekt ist die Person, die behauptet.<br><br>Er <g>will</g> nichts davon <g>gewusst haben</g>.<br>Sie <g>will</g> schon als Kind Klavier <g>gespielt haben</g>.<br><br><b>3. sollen: Behauptung anderer</b><br>Mit <g>sollen</g> gibst du ein Gerücht oder eine Meldung wieder, deren Quelle unbekannt oder nicht die Person selbst ist. Die Wendung <g>es heißt, dass</g> hat dieselbe Bedeutung.<br><br>Das Restaurant <g>soll</g> sehr gut <g>sein</g>.<br>Der Täter <g>soll</g> gestern <g>gefasst worden sein</g>.<br>Die Preise <g>sollen</g> nächstes Jahr <g>steigen</g>.<br><br><b>4. Infinitivformen und Zeiten</b><br><table><tr><th>Zeitbezug</th><th>Beispiel</th></tr><tr><td>Gegenwart</td><td>Er <g>will</g> sehr reich <g>sein</g>.</td></tr><tr><td>Vergangenheit</td><td>Er <g>will</g> sehr reich <g>gewesen sein</g>.</td></tr><tr><td>Passiv</td><td>Er <g>will</g> betrogen <g>worden sein</g>.</td></tr></table><br><br>Subjektive Modalverben stehen im Präsens oder im Präteritum (<g>Er wollte den Dieb gesehen haben</g>), nicht im Perfekt. Mit dem Infinitiv Präsens kann sich <g>sollen</g> auch auf die Zukunft beziehen: <g>Die Steuern sollen sinken.</g>",
      "en": "<b>1. Subjective and objective use</b><br>Modal verbs can have two functions. The <b>objective</b> use describes the subject's wish, obligation or plan. The <b>subjective</b> use expresses the speaker's attitude to a statement.<br><br><table><tr><th>Objective</th><th>Subjective</th></tr><tr><td>Er <g>will</g> nach Berlin <g>fahren</g>. (Wunsch)</td><td>Er <g>will</g> Arzt <g>gewesen sein</g>. (Behauptung)</td></tr><tr><td>Sie <g>soll</g> die Miete <g>zahlen</g>. (Auftrag)</td><td>Sie <g>soll</g> sehr reich <g>sein</g>. (Gerücht)</td></tr></table><br><br><b>2. wollen: the person's own claim</b><br>With <g>wollen</g> you report what the subject says about themselves. You often doubt it. The subject is the person making the claim.<br><br>Er <g>will</g> nichts davon <g>gewusst haben</g>.<br>He claims not to have known anything about it.<br>Sie <g>will</g> schon als Kind Klavier <g>gespielt haben</g>.<br>She claims to have played the piano as a child.<br><br><b>3. sollen: others' claim</b><br>With <g>sollen</g> you report a rumour or a report whose source is unknown or is not the person themselves. The phrase <g>es heißt, dass</g> has the same meaning.<br><br>Das Restaurant <g>soll</g> sehr gut <g>sein</g>.<br>The restaurant is said to be very good.<br>Der Täter <g>soll</g> gestern <g>gefasst worden sein</g>.<br>The offender is said to have been caught yesterday.<br>Die Preise <g>sollen</g> nächstes Jahr <g>steigen</g>.<br>Prices are said to rise next year.<br><br><b>4. Infinitive forms and tenses</b><br><table><tr><th>Time reference</th><th>Example</th></tr><tr><td>Present</td><td>Er <g>will</g> sehr reich <g>sein</g>.</td></tr><tr><td>Past</td><td>Er <g>will</g> sehr reich <g>gewesen sein</g>.</td></tr><tr><td>Passive</td><td>Er <g>will</g> betrogen <g>worden sein</g>.</td></tr></table><br><br>Subjective modal verbs stand in the present or the simple past (<g>Er wollte den Dieb gesehen haben</g>), not in the perfect. With the present infinitive <g>sollen</g> can also refer to the future: <g>Die Steuern sollen sinken.</g>",
      "uk": "<b>1. Субʼєктивне й обʼєктивне вживання</b><br>Модальні дієслова можуть мати дві функції. <b>Обʼєктивне</b> вживання описує бажання, обовʼязок або план підмета. <b>Субʼєктивне</b> вживання виражає ставлення мовця до твердження.<br><br><table><tr><th>Обʼєктивне</th><th>Субʼєктивне</th></tr><tr><td>Er <g>will</g> nach Berlin <g>fahren</g>. (Wunsch)</td><td>Er <g>will</g> Arzt <g>gewesen sein</g>. (Behauptung)</td></tr><tr><td>Sie <g>soll</g> die Miete <g>zahlen</g>. (Auftrag)</td><td>Sie <g>soll</g> sehr reich <g>sein</g>. (Gerücht)</td></tr></table><br><br><b>2. wollen: твердження самої особи</b><br>За допомогою <g>wollen</g> ти передаєш, що підмет каже про себе. Ти часто сумніваєшся в цьому. Підмет — це особа, яка стверджує.<br><br>Er <g>will</g> nichts davon <g>gewusst haben</g>.<br>Він стверджує, що нічого про це не знав.<br>Sie <g>will</g> schon als Kind Klavier <g>gespielt haben</g>.<br>Вона стверджує, що грала на фортепіано ще дитиною.<br><br><b>3. sollen: твердження інших</b><br>За допомогою <g>sollen</g> ти передаєш чутку або повідомлення, джерело яких невідоме або не є самою особою. Вислів <g>es heißt, dass</g> має те саме значення.<br><br>Das Restaurant <g>soll</g> sehr gut <g>sein</g>.<br>Кажуть, що ресторан дуже хороший.<br>Der Täter <g>soll</g> gestern <g>gefasst worden sein</g>.<br>Кажуть, що злочинця схопили вчора.<br>Die Preise <g>sollen</g> nächstes Jahr <g>steigen</g>.<br>Кажуть, що наступного року ціни зростуть.<br><br><b>4. Форми інфінітива й часи</b><br><table><tr><th>Часове співвідношення</th><th>Приклад</th></tr><tr><td>Теперішній час</td><td>Er <g>will</g> sehr reich <g>sein</g>.</td></tr><tr><td>Минуле</td><td>Er <g>will</g> sehr reich <g>gewesen sein</g>.</td></tr><tr><td>Пасив</td><td>Er <g>will</g> betrogen <g>worden sein</g>.</td></tr></table><br><br>Субʼєктивні модальні дієслова стоять у Präsens або Präteritum (<g>Er wollte den Dieb gesehen haben</g>), а не в Perfekt. З інфінітивом теперішнього часу <g>sollen</g> може стосуватися й майбутнього: <g>Die Steuern sollen sinken.</g>",
      "ru": "<b>1. Субъективное и объективное употребление</b><br>Модальные глаголы могут иметь две функции. <b>Объективное</b> употребление описывает желание, обязанность или план подлежащего. <b>Субъективное</b> употребление выражает отношение говорящего к высказыванию.<br><br><table><tr><th>Объективное</th><th>Субъективное</th></tr><tr><td>Er <g>will</g> nach Berlin <g>fahren</g>. (Wunsch)</td><td>Er <g>will</g> Arzt <g>gewesen sein</g>. (Behauptung)</td></tr><tr><td>Sie <g>soll</g> die Miete <g>zahlen</g>. (Auftrag)</td><td>Sie <g>soll</g> sehr reich <g>sein</g>. (Gerücht)</td></tr></table><br><br><b>2. wollen: утверждение самого лица</b><br>С помощью <g>wollen</g> ты передаёшь, что подлежащее говорит о себе. Ты часто сомневаешься в этом. Подлежащее — это лицо, которое утверждает.<br><br>Er <g>will</g> nichts davon <g>gewusst haben</g>.<br>Он утверждает, что ничего об этом не знал.<br>Sie <g>will</g> schon als Kind Klavier <g>gespielt haben</g>.<br>Она утверждает, что играла на фортепиано ещё ребёнком.<br><br><b>3. sollen: утверждение других</b><br>С помощью <g>sollen</g> ты передаёшь слух или сообщение, источник которых неизвестен или не является самим лицом. Выражение <g>es heißt, dass</g> имеет то же значение.<br><br>Das Restaurant <g>soll</g> sehr gut <g>sein</g>.<br>Говорят, что ресторан очень хороший.<br>Der Täter <g>soll</g> gestern <g>gefasst worden sein</g>.<br>Говорят, что преступника поймали вчера.<br>Die Preise <g>sollen</g> nächstes Jahr <g>steigen</g>.<br>Говорят, что в следующем году цены вырастут.<br><br><b>4. Формы инфинитива и времена</b><br><table><tr><th>Временное соотношение</th><th>Пример</th></tr><tr><td>Настоящее</td><td>Er <g>will</g> sehr reich <g>sein</g>.</td></tr><tr><td>Прошедшее</td><td>Er <g>will</g> sehr reich <g>gewesen sein</g>.</td></tr><tr><td>Пассив</td><td>Er <g>will</g> betrogen <g>worden sein</g>.</td></tr></table><br><br>Субъективные модальные глаголы стоят в Präsens или Präteritum (<g>Er wollte den Dieb gesehen haben</g>), а не в Perfekt. С инфинитивом презенса <g>sollen</g> может относиться и к будущему: <g>Die Steuern sollen sinken.</g>"
    }
  },
  {
    "id": "subjektive_modalverben_vermutungen",
    "title": {"de": "Subjektive Modalverben: Vermutungen ausdrücken", "en": "Subjective modal verbs: expressing assumptions", "uk": "Субʼєктивні модальні дієслова: вираження припущень", "ru": "Субъективные модальные глаголы: выражение предположений"},
    "explanation": {
      "de": "<b>Mit Modalverben zeigst du, wie sicher du dir bist.</b><br><b>Müssen</b> = fast sicher: Er <g>muss</g> zu Hause <g>sein</g>. <b>Dürfte</b> = wahrscheinlich: Er <g>dürfte</g> bald <g>kommen</g>. <b>Können / könnte / mögen</b> = möglich: Es <g>kann</g> <g>sein</g>. <b>Nicht können</b> = ausgeschlossen: Das <g>kann</g> nicht <g>stimmen</g>. Für Vergangenes steht der Infinitiv Perfekt: Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>Beispiel: Er <g>dürfte</g> bald <g>kommen</g>.",
      "en": "<b>With modal verbs you show how certain you are.</b><br><b>Müssen</b> = almost certain: Er <g>muss</g> zu Hause <g>sein</g>. <b>Dürfte</b> = probable: Er <g>dürfte</g> bald <g>kommen</g>. <b>Können / könnte / mögen</b> = possible: Es <g>kann</g> <g>sein</g>. <b>Nicht können</b> = impossible: Das <g>kann</g> nicht <g>stimmen</g>. For the past the perfect infinitive is used: Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>Example: Er <g>dürfte</g> bald <g>kommen</g>.<br>He should be arriving soon.",
      "uk": "<b>За допомогою модальних дієслів ти показуєш, наскільки ти впевнений.</b><br><b>Müssen</b> = майже напевно: Er <g>muss</g> zu Hause <g>sein</g>. <b>Dürfte</b> = ймовірно: Er <g>dürfte</g> bald <g>kommen</g>. <b>Können / könnte / mögen</b> = можливо: Es <g>kann</g> <g>sein</g>. <b>Nicht können</b> = виключено: Das <g>kann</g> nicht <g>stimmen</g>. Для минулого стоїть інфінітив перфекта: Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>Приклад: Er <g>dürfte</g> bald <g>kommen</g>.<br>Він, імовірно, скоро прийде.",
      "ru": "<b>С помощью модальных глаголов ты показываешь, насколько ты уверен.</b><br><b>Müssen</b> = почти наверняка: Er <g>muss</g> zu Hause <g>sein</g>. <b>Dürfte</b> = вероятно: Er <g>dürfte</g> bald <g>kommen</g>. <b>Können / könnte / mögen</b> = возможно: Es <g>kann</g> <g>sein</g>. <b>Nicht können</b> = исключено: Das <g>kann</g> nicht <g>stimmen</g>. Для прошедшего стоит инфинитив перфекта: Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>Пример: Er <g>dürfte</g> bald <g>kommen</g>.<br>Он, вероятно, скоро придёт."
    },
    "rule": {
      "de": "<b>1. Skala der Sicherheit</b><br><table><tr><th>Modalverb</th><th>Bedeutung und Beispiel</th></tr><tr><td><g>müssen</g></td><td>fast sicher:<br>Er <g>muss</g> zu Hause <g>sein</g>.</td></tr><tr><td><g>dürfte</g></td><td>wahrscheinlich:<br>Er <g>dürfte</g> bald <g>kommen</g>.</td></tr><tr><td><g>können</g> / <g>könnte</g> / <g>mag</g></td><td>möglich:<br>Es <g>kann</g> / <g>könnte</g> Regen <g>geben</g>.</td></tr><tr><td><g>nicht können</g></td><td>ausgeschlossen:<br>Das <g>kann</g> nicht <g>stimmen</g>.</td></tr></table><br><br><g>Könnte</g> ist unsicherer als <g>kann</g>. <g>Dürfte</g> gibt es in dieser Bedeutung nur im Konjunktiv II. <g>Mögen</g> klingt förmlich und leitet oft ein Zugeständnis ein: <g>Das mag sein, aber …</g><br><br><b>2. Vergangenheit und Passiv</b><br>Für Vermutungen über die Vergangenheit steht der Infinitiv Perfekt: Partizip II + <g>haben / sein</g>. Im Passiv: Partizip II + <g>worden sein</g>.<br><br>Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>Sie <g>dürfte</g> schon <g>abgereist sein</g>.<br>Der Brief <g>muss</g> gestern <g>abgeschickt worden sein</g>.<br>Er <g>kann</g> das nicht <g>gewusst haben</g>.<br><br><b>3. Verneinung</b><br>Die Verneinung von <g>müssen</g> in subjektiver Bedeutung ist <g>nicht können</g> (ausgeschlossen) oder <g>dürfte nicht</g> (wahrscheinlich nicht). <g>Er muss nicht zu Hause sein</g> bedeutet dagegen nur: Es ist nicht sicher, dass er zu Hause ist.<br><br>Er <g>kann</g> nicht zu Hause <g>sein</g>. Ich habe ihn eben gesehen.<br>Er <g>dürfte</g> nicht zu Hause <g>sein</g>.<br><br><b>4. Alternativen</b><br>Du kannst Vermutungen auch mit Adverbien ausdrücken: <g>sicher, bestimmt, wahrscheinlich, vermutlich, vielleicht, möglicherweise</g>, oder mit Wendungen wie <g>Es ist möglich, dass …</g>. Modalverben klingen knapper und bilden eine feine Stufenfolge.",
      "en": "<b>1. Scale of certainty</b><br><table><tr><th>Modal verb</th><th>Meaning and example</th></tr><tr><td><g>müssen</g></td><td>almost certain:<br>Er <g>muss</g> zu Hause <g>sein</g>.</td></tr><tr><td><g>dürfte</g></td><td>probable:<br>Er <g>dürfte</g> bald <g>kommen</g>.</td></tr><tr><td><g>können</g> / <g>könnte</g> / <g>mag</g></td><td>possible:<br>Es <g>kann</g> / <g>könnte</g> Regen <g>geben</g>.</td></tr><tr><td><g>nicht können</g></td><td>impossible:<br>Das <g>kann</g> nicht <g>stimmen</g>.</td></tr></table><br><br><g>Könnte</g> is less certain than <g>kann</g>. <g>Dürfte</g> exists in this meaning only in the Konjunktiv II. <g>Mögen</g> sounds formal and often introduces a concession: <g>Das mag sein, aber …</g><br><br><b>2. Past and passive</b><br>For assumptions about the past the perfect infinitive is used: past participle + <g>haben / sein</g>. In the passive: past participle + <g>worden sein</g>.<br><br>Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>He must have missed the train.<br>Sie <g>dürfte</g> schon <g>abgereist sein</g>.<br>She has probably already left.<br>Der Brief <g>muss</g> gestern <g>abgeschickt worden sein</g>.<br>The letter must have been sent yesterday.<br>Er <g>kann</g> das nicht <g>gewusst haben</g>.<br>He cannot have known that.<br><br><b>3. Negation</b><br>The negation of <g>müssen</g> in its subjective meaning is <g>nicht können</g> (impossible) or <g>dürfte nicht</g> (probably not). <g>Er muss nicht zu Hause sein</g> only means: It is not certain that he is at home.<br><br>Er <g>kann</g> nicht zu Hause <g>sein</g>. Ich habe ihn eben gesehen.<br>He cannot be at home. I just saw him.<br>Er <g>dürfte</g> nicht zu Hause <g>sein</g>.<br>He is probably not at home.<br><br><b>4. Alternatives</b><br>You can also express assumptions with adverbs: <g>sicher, bestimmt, wahrscheinlich, vermutlich, vielleicht, möglicherweise</g>, or with phrases such as <g>Es ist möglich, dass …</g>. Modal verbs sound more concise and form a fine gradation.",
      "uk": "<b>1. Шкала впевненості</b><br><table><tr><th>Модальне дієслово</th><th>Значення й приклад</th></tr><tr><td><g>müssen</g></td><td>майже напевно:<br>Er <g>muss</g> zu Hause <g>sein</g>.</td></tr><tr><td><g>dürfte</g></td><td>ймовірно:<br>Er <g>dürfte</g> bald <g>kommen</g>.</td></tr><tr><td><g>können</g> / <g>könnte</g> / <g>mag</g></td><td>можливо:<br>Es <g>kann</g> / <g>könnte</g> Regen <g>geben</g>.</td></tr><tr><td><g>nicht können</g></td><td>виключено:<br>Das <g>kann</g> nicht <g>stimmen</g>.</td></tr></table><br><br><g>Könnte</g> менш певне, ніж <g>kann</g>. <g>Dürfte</g> у цьому значенні існує лише в Konjunktiv II. <g>Mögen</g> звучить офіційно й часто вводить поступку: <g>Das mag sein, aber …</g><br><br><b>2. Минуле й пасив</b><br>Для припущень про минуле вживають інфінітив перфекта: дієприкметник ІІ + <g>haben / sein</g>. У пасиві: дієприкметник ІІ + <g>worden sein</g>.<br><br>Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>Він, мабуть, запізнився на потяг.<br>Sie <g>dürfte</g> schon <g>abgereist sein</g>.<br>Вона, імовірно, вже виїхала.<br>Der Brief <g>muss</g> gestern <g>abgeschickt worden sein</g>.<br>Лист, мабуть, відправили вчора.<br>Er <g>kann</g> das nicht <g>gewusst haben</g>.<br>Він не міг цього знати.<br><br><b>3. Заперечення</b><br>Заперечення <g>müssen</g> у субʼєктивному значенні — це <g>nicht können</g> (виключено) або <g>dürfte nicht</g> (імовірно, ні). Натомість <g>Er muss nicht zu Hause sein</g> означає лише: не напевно, що він удома.<br><br>Er <g>kann</g> nicht zu Hause <g>sein</g>. Ich habe ihn eben gesehen.<br>Його не може бути вдома. Я щойно його бачив.<br>Er <g>dürfte</g> nicht zu Hause <g>sein</g>.<br>Його, імовірно, немає вдома.<br><br><b>4. Альтернативи</b><br>Припущення можна виражати й прислівниками: <g>sicher, bestimmt, wahrscheinlich, vermutlich, vielleicht, möglicherweise</g>, або зворотами на кшталт <g>Es ist möglich, dass …</g>. Модальні дієслова звучать стисліше й утворюють тонку градацію.",
      "ru": "<b>1. Шкала уверенности</b><br><table><tr><th>Модальный глагол</th><th>Значение и пример</th></tr><tr><td><g>müssen</g></td><td>почти наверняка:<br>Er <g>muss</g> zu Hause <g>sein</g>.</td></tr><tr><td><g>dürfte</g></td><td>вероятно:<br>Er <g>dürfte</g> bald <g>kommen</g>.</td></tr><tr><td><g>können</g> / <g>könnte</g> / <g>mag</g></td><td>возможно:<br>Es <g>kann</g> / <g>könnte</g> Regen <g>geben</g>.</td></tr><tr><td><g>nicht können</g></td><td>исключено:<br>Das <g>kann</g> nicht <g>stimmen</g>.</td></tr></table><br><br><g>Könnte</g> менее уверенно, чем <g>kann</g>. <g>Dürfte</g> в этом значении существует только в Konjunktiv II. <g>Mögen</g> звучит официально и часто вводит уступку: <g>Das mag sein, aber …</g><br><br><b>2. Прошедшее и пассив</b><br>Для предположений о прошедшем употребляют инфинитив перфекта: причастие II + <g>haben / sein</g>. В пассиве: причастие II + <g>worden sein</g>.<br><br>Er <g>muss</g> den Zug <g>verpasst haben</g>.<br>Он, должно быть, опоздал на поезд.<br>Sie <g>dürfte</g> schon <g>abgereist sein</g>.<br>Она, вероятно, уже уехала.<br>Der Brief <g>muss</g> gestern <g>abgeschickt worden sein</g>.<br>Письмо, должно быть, отправили вчера.<br>Er <g>kann</g> das nicht <g>gewusst haben</g>.<br>Он не мог этого знать.<br><br><b>3. Отрицание</b><br>Отрицание <g>müssen</g> в субъективном значении — это <g>nicht können</g> (исключено) или <g>dürfte nicht</g> (вероятно, нет). Зато <g>Er muss nicht zu Hause sein</g> означает лишь: не обязательно, что он дома.<br><br>Er <g>kann</g> nicht zu Hause <g>sein</g>. Ich habe ihn eben gesehen.<br>Его не может быть дома. Я только что его видел.<br>Er <g>dürfte</g> nicht zu Hause <g>sein</g>.<br>Его, вероятно, нет дома.<br><br><b>4. Альтернативы</b><br>Предположения можно выражать и наречиями: <g>sicher, bestimmt, wahrscheinlich, vermutlich, vielleicht, möglicherweise</g>, или оборотами вроде <g>Es ist möglich, dass …</g>. Модальные глаголы звучат короче и образуют тонкую градацию."
    }
  },
  {
    "id": "futur_vermutungen",
    "title": {"de": "Futur I und Futur II: Vermutungen ausdrücken", "en": "Future I and Future II: expressing assumptions", "uk": "Futur I і Futur II: вираження припущень", "ru": "Futur I и Futur II: выражение предположений"},
    "explanation": {
      "de": "<b>Mit dem Futur drückst du nicht nur Zukunft aus, sondern auch Vermutungen.</b><br>Futur I (<g>werden</g> + Infinitiv) = Vermutung über die Gegenwart: Er <g>wird</g> wohl im Stau <g>stehen</g>. Futur II (<g>werden</g> + Partizip II + <g>haben / sein</g>) = Vermutung über die Vergangenheit: Sie <g>wird</g> den Termin <g>vergessen haben</g>. Typische Signalwörter sind <b>wohl, sicher, bestimmt, wahrscheinlich, schon</b>.<br>Beispiel: Die Kollegin <g>wird</g> schon nach Hause <g>gegangen sein</g>.",
      "en": "<b>With the future tense you express not only the future but also assumptions.</b><br>Futur I (<g>werden</g> + infinitive) = assumption about the present: Er <g>wird</g> wohl im Stau <g>stehen</g>. Futur II (<g>werden</g> + past participle + <g>haben / sein</g>) = assumption about the past: Sie <g>wird</g> den Termin <g>vergessen haben</g>. Typical signal words are <b>wohl, sicher, bestimmt, wahrscheinlich, schon</b>.<br>Example: Die Kollegin <g>wird</g> schon nach Hause <g>gegangen sein</g>.<br>Our colleague <g>will</g> have <g>gone</g> home already.",
      "uk": "<b>За допомогою футура ти виражаєш не лише майбутнє, а й припущення.</b><br>Futur I (<g>werden</g> + інфінітив) = припущення про теперішнє: Er <g>wird</g> wohl im Stau <g>stehen</g>. Futur II (<g>werden</g> + дієприкметник ІІ + <g>haben / sein</g>) = припущення про минуле: Sie <g>wird</g> den Termin <g>vergessen haben</g>. Типові слова-сигнали: <b>wohl, sicher, bestimmt, wahrscheinlich, schon</b>.<br>Приклад: Die Kollegin <g>wird</g> schon nach Hause <g>gegangen sein</g>.<br>Колега, мабуть, уже пішла додому.",
      "ru": "<b>С помощью футура ты выражаешь не только будущее, но и предположения.</b><br>Futur I (<g>werden</g> + инфинитив) = предположение о настоящем: Er <g>wird</g> wohl im Stau <g>stehen</g>. Futur II (<g>werden</g> + причастие II + <g>haben / sein</g>) = предположение о прошлом: Sie <g>wird</g> den Termin <g>vergessen haben</g>. Типичные слова-сигналы: <b>wohl, sicher, bestimmt, wahrscheinlich, schon</b>.<br>Пример: Die Kollegin <g>wird</g> schon nach Hause <g>gegangen sein</g>.<br>Коллега, наверное, уже ушла домой."
    },
    "rule": {
      "de": "<b>1. Futur I: Vermutung über die Gegenwart</b><br>Form: <g>werden</g> + Infinitiv. Ein Adverb wie <g>wohl</g>, <g>sicher</g>, <g>bestimmt</g>, <g>wahrscheinlich</g>, <g>vermutlich</g> oder <g>schon</g> macht klar, dass es um eine Vermutung geht und nicht um die Zukunft.<br><br>Herr Weber <g>wird</g> wohl noch in der Besprechung <g>sein</g>.<br>Das Paket <g>wird</g> bestimmt im Lager <g>liegen</g>.<br><br><b>2. Futur II: Vermutung über die Vergangenheit</b><br>Form: <g>werden</g> + Partizip II + <g>haben / sein</g>. Der Sprecher vermutet, dass etwas schon passiert ist.<br><br>Er <g>wird</g> den Zug <g>verpasst haben</g>.<br>Die Lieferung <g>wird</g> gestern <g>angekommen sein</g>.<br>Der Fehler <g>wird</g> beim Update <g>entstanden sein</g>.<br><br><b>3. Zukunft oder Vermutung?</b><br><table><tr><th>Satz</th><th>Bedeutung</th></tr><tr><td>Ich <g>werde</g> morgen <g>anrufen</g>.</td><td>Zukunft, Plan</td></tr><tr><td>Sie <g>wird</g> wohl krank <g>sein</g>.</td><td>Vermutung, Gegenwart</td></tr><tr><td>Bis Freitag <g>werden</g> wir alles <g>erledigt haben</g>.</td><td>Zukunft, abgeschlossen</td></tr><tr><td>Er <g>wird</g> es <g>vergessen haben</g>.</td><td>Vermutung, Vergangenheit</td></tr></table><br><br>Ohne Zeitangabe für die Zukunft und mit <g>wohl</g>, <g>sicher</g> usw. ist das Futur fast immer eine Vermutung.<br><br><b>4. Vergleich mit subjektiven Modalverben</b><br>Das Futur mit <g>wohl</g> entspricht ungefähr <g>dürfte</g>: Beide drücken eine wahrscheinliche Vermutung aus. Das Futur klingt alltäglicher, <g>dürfte</g> eher förmlich.<br><br>Er <g>wird</g> wohl krank <g>sein</g>. ≈ Er <g>dürfte</g> krank <g>sein</g>.<br>Sie <g>wird</g> es <g>vergessen haben</g>. ≈ Sie <g>dürfte</g> es <g>vergessen haben</g>.<br><br><b>5. Im Nebensatz</b><br>Im Nebensatz steht <g>werden</g> am Ende. Im Alltag ersetzt man diese Form oft durch Präsens oder Perfekt mit <g>wohl</g>.<br><br>Ich nehme an, dass er den Bus <g>verpasst haben wird</g>.<br>= Er hat den Bus wohl verpasst.",
      "en": "<b>1. Futur I: assumption about the present</b><br>Form: <g>werden</g> + infinitive. An adverb such as <g>wohl</g>, <g>sicher</g>, <g>bestimmt</g>, <g>wahrscheinlich</g>, <g>vermutlich</g> or <g>schon</g> makes it clear that this is an assumption and not the future.<br><br>Herr Weber <g>wird</g> wohl noch in der Besprechung <g>sein</g>.<br>Mr Weber <g>will</g> probably still <g>be</g> in the meeting.<br>Das Paket <g>wird</g> bestimmt im Lager <g>liegen</g>.<br>The parcel <g>will</g> certainly <g>be</g> in the warehouse.<br><br><b>2. Futur II: assumption about the past</b><br>Form: <g>werden</g> + past participle + <g>haben / sein</g>. The speaker assumes that something has already happened.<br><br>Er <g>wird</g> den Zug <g>verpasst haben</g>.<br>He <g>will have missed</g> the train.<br>Die Lieferung <g>wird</g> gestern <g>angekommen sein</g>.<br>The delivery <g>will have arrived</g> yesterday.<br>Der Fehler <g>wird</g> beim Update <g>entstanden sein</g>.<br>The error <g>will have occurred</g> during the update.<br><br><b>3. Future or assumption?</b><br><table><tr><th>Sentence</th><th>Meaning</th></tr><tr><td>Ich <g>werde</g> morgen <g>anrufen</g>.</td><td>future, plan</td></tr><tr><td>Sie <g>wird</g> wohl krank <g>sein</g>.</td><td>assumption, present</td></tr><tr><td>Bis Freitag <g>werden</g> wir alles <g>erledigt haben</g>.</td><td>future, completed</td></tr><tr><td>Er <g>wird</g> es <g>vergessen haben</g>.</td><td>assumption, past</td></tr></table><br><br>Without a time expression pointing to the future and with <g>wohl</g>, <g>sicher</g> etc., the future tense almost always expresses an assumption.<br><br><b>4. Comparison with subjective modal verbs</b><br>The future tense with <g>wohl</g> roughly corresponds to <g>dürfte</g>: both express a probable assumption. The future tense sounds more everyday, <g>dürfte</g> rather formal.<br><br>Er <g>wird</g> wohl krank <g>sein</g>. ≈ Er <g>dürfte</g> krank <g>sein</g>.<br>He is probably ill.<br>Sie <g>wird</g> es <g>vergessen haben</g>. ≈ Sie <g>dürfte</g> es <g>vergessen haben</g>.<br>She has probably forgotten it.<br><br><b>5. In subordinate clauses</b><br>In a subordinate clause <g>werden</g> goes to the end. In everyday speech this form is often replaced by the present or perfect tense with <g>wohl</g>.<br><br>Ich nehme an, dass er den Bus <g>verpasst haben wird</g>.<br>= Er hat den Bus wohl verpasst.<br>I assume he has missed the bus.",
      "uk": "<b>1. Futur I: припущення про теперішнє</b><br>Форма: <g>werden</g> + інфінітив. Прислівник <g>wohl</g>, <g>sicher</g>, <g>bestimmt</g>, <g>wahrscheinlich</g>, <g>vermutlich</g> або <g>schon</g> показує, що йдеться про припущення, а не про майбутнє.<br><br>Herr Weber <g>wird</g> wohl noch in der Besprechung <g>sein</g>.<br>Пан Вебер, мабуть, ще на нараді.<br>Das Paket <g>wird</g> bestimmt im Lager <g>liegen</g>.<br>Посилка, напевно, лежить на складі.<br><br><b>2. Futur II: припущення про минуле</b><br>Форма: <g>werden</g> + дієприкметник ІІ + <g>haben / sein</g>. Мовець припускає, що щось уже сталося.<br><br>Er <g>wird</g> den Zug <g>verpasst haben</g>.<br>Він, мабуть, запізнився на потяг.<br>Die Lieferung <g>wird</g> gestern <g>angekommen sein</g>.<br>Поставка, мабуть, прибула вчора.<br>Der Fehler <g>wird</g> beim Update <g>entstanden sein</g>.<br>Помилка, мабуть, виникла під час оновлення.<br><br><b>3. Майбутнє чи припущення?</b><br><table><tr><th>Речення</th><th>Значення</th></tr><tr><td>Ich <g>werde</g> morgen <g>anrufen</g>.</td><td>майбутнє, план</td></tr><tr><td>Sie <g>wird</g> wohl krank <g>sein</g>.</td><td>припущення, теперішнє</td></tr><tr><td>Bis Freitag <g>werden</g> wir alles <g>erledigt haben</g>.</td><td>майбутнє, завершене</td></tr><tr><td>Er <g>wird</g> es <g>vergessen haben</g>.</td><td>припущення, минуле</td></tr></table><br><br>Якщо немає вказівки на майбутній час, а є <g>wohl</g>, <g>sicher</g> тощо, футур майже завжди виражає припущення.<br><br><b>4. Порівняння із субʼєктивними модальними дієсловами</b><br>Футур із <g>wohl</g> приблизно відповідає <g>dürfte</g>: обидва виражають ймовірне припущення. Футур звучить побутовіше, <g>dürfte</g> — радше офіційно.<br><br>Er <g>wird</g> wohl krank <g>sein</g>. ≈ Er <g>dürfte</g> krank <g>sein</g>.<br>Він, імовірно, хворий.<br>Sie <g>wird</g> es <g>vergessen haben</g>. ≈ Sie <g>dürfte</g> es <g>vergessen haben</g>.<br>Вона, імовірно, про це забула.<br><br><b>5. У підрядному реченні</b><br>У підрядному реченні <g>werden</g> стоїть у кінці. У розмовній мові цю форму часто замінюють презенсом або перфектом із <g>wohl</g>.<br><br>Ich nehme an, dass er den Bus <g>verpasst haben wird</g>.<br>= Er hat den Bus wohl verpasst.<br>Я припускаю, що він запізнився на автобус.",
      "ru": "<b>1. Futur I: предположение о настоящем</b><br>Форма: <g>werden</g> + инфинитив. Наречие <g>wohl</g>, <g>sicher</g>, <g>bestimmt</g>, <g>wahrscheinlich</g>, <g>vermutlich</g> или <g>schon</g> показывает, что речь идёт о предположении, а не о будущем.<br><br>Herr Weber <g>wird</g> wohl noch in der Besprechung <g>sein</g>.<br>Господин Вебер, наверное, ещё на совещании.<br>Das Paket <g>wird</g> bestimmt im Lager <g>liegen</g>.<br>Посылка, наверняка, лежит на складе.<br><br><b>2. Futur II: предположение о прошлом</b><br>Форма: <g>werden</g> + причастие II + <g>haben / sein</g>. Говорящий предполагает, что что-то уже произошло.<br><br>Er <g>wird</g> den Zug <g>verpasst haben</g>.<br>Он, наверное, опоздал на поезд.<br>Die Lieferung <g>wird</g> gestern <g>angekommen sein</g>.<br>Поставка, наверное, пришла вчера.<br>Der Fehler <g>wird</g> beim Update <g>entstanden sein</g>.<br>Ошибка, наверное, возникла при обновлении.<br><br><b>3. Будущее или предположение?</b><br><table><tr><th>Предложение</th><th>Значение</th></tr><tr><td>Ich <g>werde</g> morgen <g>anrufen</g>.</td><td>будущее, план</td></tr><tr><td>Sie <g>wird</g> wohl krank <g>sein</g>.</td><td>предположение, настоящее</td></tr><tr><td>Bis Freitag <g>werden</g> wir alles <g>erledigt haben</g>.</td><td>будущее, завершённое</td></tr><tr><td>Er <g>wird</g> es <g>vergessen haben</g>.</td><td>предположение, прошлое</td></tr></table><br><br>Если нет указания на будущее время, а есть <g>wohl</g>, <g>sicher</g> и т. п., футур почти всегда выражает предположение.<br><br><b>4. Сравнение с субъективными модальными глаголами</b><br>Футур с <g>wohl</g> примерно соответствует <g>dürfte</g>: оба выражают вероятное предположение. Футур звучит более бытово, <g>dürfte</g> — скорее официально.<br><br>Er <g>wird</g> wohl krank <g>sein</g>. ≈ Er <g>dürfte</g> krank <g>sein</g>.<br>Он, вероятно, болен.<br>Sie <g>wird</g> es <g>vergessen haben</g>. ≈ Sie <g>dürfte</g> es <g>vergessen haben</g>.<br>Она, вероятно, об этом забыла.<br><br><b>5. В придаточном предложении</b><br>В придаточном предложении <g>werden</g> стоит в конце. В разговорной речи эту форму часто заменяют презенсом или перфектом с <g>wohl</g>.<br><br>Ich nehme an, dass er den Bus <g>verpasst haben wird</g>.<br>= Er hat den Bus wohl verpasst.<br>Я предполагаю, что он опоздал на автобус."
    }
  },
  {
    "id": "nominalisierung_praepositionalergaenzungen",
    "title": {"de": "Nominalisierung und Verbalisierung von Präpositionalergänzungen", "en": "Nominalisation and verbalisation of prepositional complements", "uk": "Номіналізація та вербалізація прийменникових додатків", "ru": "Номинализация и вербализация предложных дополнений"},
    "explanation": {
      "de": "<b>Verben mit fester Präposition lassen sich oft zu Nomen machen.</b><br>Die <b>Präposition</b> bleibt oft gleich: <g>sich freuen über</g> → <g>die Freude über</g>. Manchmal ändert sie sich: <g>sich interessieren für</g> → <g>das Interesse an</g>. Das Subjekt wird zum Genitivattribut oder zu <b>von</b> + Dativ. Aus einem Nebensatz mit <b>dass</b> oder einem Infinitiv wird eine Nominalgruppe.<br>Beispiel: Er freut sich, <g>dass</g> sie <g>kommt</g>. – Er freut sich <g>über</g> <g>ihr Kommen</g>.",
      "en": "<b>Verbs with a fixed preposition can often be turned into nouns.</b><br>The <b>preposition</b> often stays the same: <g>sich freuen über</g> → <g>die Freude über</g>. Sometimes it changes: <g>sich interessieren für</g> → <g>das Interesse an</g>. The subject becomes a genitive attribute or <b>von</b> + dative. A clause with <b>dass</b> or an infinitive becomes a noun phrase.<br>Example: Er freut sich, <g>dass</g> sie <g>kommt</g>. – Er freut sich <g>über</g> <g>ihr Kommen</g>.<br>He is glad that she is coming. – He is glad about her coming.",
      "uk": "<b>Дієслова зі сталим прийменником часто можна перетворити на іменники.</b><br><b>Прийменник</b> часто лишається тим самим: <g>sich freuen über</g> → <g>die Freude über</g>. Іноді він змінюється: <g>sich interessieren für</g> → <g>das Interesse an</g>. Підмет перетворюється на означення в родовому відмінку або на <b>von</b> + давальний. Із підрядного речення з <b>dass</b> або інфінітива утворюється іменникова група.<br>Приклад: Er freut sich, <g>dass</g> sie <g>kommt</g>. – Er freut sich <g>über</g> <g>ihr Kommen</g>.<br>Він радий, що вона приходить. – Він радий її приходу.",
      "ru": "<b>Глаголы с постоянным предлогом часто можно превратить в существительные.</b><br><b>Предлог</b> часто остаётся прежним: <g>sich freuen über</g> → <g>die Freude über</g>. Иногда он меняется: <g>sich interessieren für</g> → <g>das Interesse an</g>. Подлежащее превращается в определение в родительном падеже или в <b>von</b> + дательный. Из придаточного с <b>dass</b> или инфинитива получается именная группа.<br>Пример: Er freut sich, <g>dass</g> sie <g>kommt</g>. – Er freut sich <g>über</g> <g>ihr Kommen</g>.<br>Он рад, что она приходит. – Он рад её приходу."
    },
    "rule": {
      "de": "<b>1. Wichtige Verben und Nomen</b><br><table><tr><th>Verb + Präposition</th><th>Nomen + Präposition</th></tr><tr><td><g>sich freuen über</g></td><td><g>die Freude über</g></td></tr><tr><td><g>sich ärgern über</g></td><td><g>der Ärger über</g></td></tr><tr><td><g>sich interessieren für</g></td><td><g>das Interesse an</g> (!)</td></tr><tr><td><g>teilnehmen an</g></td><td><g>die Teilnahme an</g></td></tr><tr><td><g>hoffen auf</g></td><td><g>die Hoffnung auf</g></td></tr><tr><td><g>Angst haben vor</g></td><td><g>die Angst vor</g></td></tr><tr><td><g>sich erinnern an</g></td><td><g>die Erinnerung an</g></td></tr><tr><td><g>sich bewerben um</g></td><td><g>die Bewerbung um</g></td></tr><tr><td><g>sich entscheiden für</g></td><td><g>die Entscheidung für</g></td></tr><tr><td><g>abhängen von</g></td><td><g>die Abhängigkeit von</g></td></tr><tr><td><g>zweifeln an</g></td><td><g>der Zweifel an</g></td></tr><tr><td><g>sich vorbereiten auf</g></td><td><g>die Vorbereitung auf</g></td></tr></table><br><br>Achtung: Das Nomen kann eine andere Präposition verlangen als das Verb. Lerne Nomen und Präposition deshalb zusammen.<br><br><b>2. Subjekt, Objekt und Inhalt</b><br><b>1.</b> Das Subjekt des Nebensatzes wird zum Possessivartikel oder Genitiv: <g>dass sie kommt</g> → <g>ihr Kommen</g>.<br><b>2.</b> Das Pronominaladverb (<g>darüber, darauf, davon</g>) entfällt; die Präposition steht vor dem Nomen.<br><b>3.</b> Bei gleichem Subjekt im Haupt- und Nebensatz entfällt das Subjekt: <g>Er hofft, zu gewinnen.</g> → <g>Er hofft auf einen Sieg.</g><br><b>4.</b> Ein Genitiv genügt: <g>die Freude der Kinder über das Geschenk</g>.<br><br>Sie ärgert sich, <g>dass</g> er so spät <g>kommt</g>.<br>Sie ärgert sich <g>über</g> sein <g>spätes Kommen</g>.<br>Wir warten <g>darauf</g>, dass die Ergebnisse <g>veröffentlicht werden</g>.<br>Wir warten <g>auf</g> die <g>Veröffentlichung</g> der Ergebnisse.<br><br><b>3. Rückweg zum Verb</b><br>Bei der Verbalisierung erkennst du das Verb im Nomen (<g>die Hoffnung</g> → <g>hoffen</g>) und ergänzst das Korrelat: <g>Seine Hoffnung auf Erfolg</g> → <g>Er hofft darauf, Erfolg zu haben.</g> Danach wählst du <g>dass</g>, <g>zu</g> + Infinitiv oder einen Fragesatz.",
      "en": "<b>1. Important verbs and nouns</b><br><table><tr><th>Verb + preposition</th><th>Noun + preposition</th></tr><tr><td><g>sich freuen über</g></td><td><g>die Freude über</g></td></tr><tr><td><g>sich ärgern über</g></td><td><g>der Ärger über</g></td></tr><tr><td><g>sich interessieren für</g></td><td><g>das Interesse an</g> (!)</td></tr><tr><td><g>teilnehmen an</g></td><td><g>die Teilnahme an</g></td></tr><tr><td><g>hoffen auf</g></td><td><g>die Hoffnung auf</g></td></tr><tr><td><g>Angst haben vor</g></td><td><g>die Angst vor</g></td></tr><tr><td><g>sich erinnern an</g></td><td><g>die Erinnerung an</g></td></tr><tr><td><g>sich bewerben um</g></td><td><g>die Bewerbung um</g></td></tr><tr><td><g>sich entscheiden für</g></td><td><g>die Entscheidung für</g></td></tr><tr><td><g>abhängen von</g></td><td><g>die Abhängigkeit von</g></td></tr><tr><td><g>zweifeln an</g></td><td><g>der Zweifel an</g></td></tr><tr><td><g>sich vorbereiten auf</g></td><td><g>die Vorbereitung auf</g></td></tr></table><br><br>Note: the noun may require a different preposition from the verb. Learn noun and preposition together.<br><br><b>2. Subject, object and content</b><br><b>1.</b> The subject of the subordinate clause becomes a possessive article or genitive: <g>dass sie kommt</g> → <g>ihr Kommen</g>.<br><b>2.</b> The pronominal adverb (<g>darüber, darauf, davon</g>) is dropped; the preposition stands before the noun.<br><b>3.</b> When the main and subordinate clauses have the same subject, the subject is dropped: <g>Er hofft, zu gewinnen.</g> → <g>Er hofft auf einen Sieg.</g><br><b>4.</b> One genitive is enough: <g>die Freude der Kinder über das Geschenk</g>.<br><br>Sie ärgert sich, <g>dass</g> er so spät <g>kommt</g>.<br>She is annoyed that he comes so late.<br>Sie ärgert sich <g>über</g> sein <g>spätes Kommen</g>.<br>She is annoyed about his late arrival.<br>Wir warten <g>darauf</g>, dass die Ergebnisse <g>veröffentlicht werden</g>.<br>We are waiting for the results to be published.<br>Wir warten <g>auf</g> die <g>Veröffentlichung</g> der Ergebnisse.<br>We are waiting for the publication of the results.<br><br><b>3. Converting back to the verb</b><br>When converting back, you recognise the verb in the noun (<g>die Hoffnung</g> → <g>hoffen</g>) and add the correlate: <g>Seine Hoffnung auf Erfolg</g> → <g>Er hofft darauf, Erfolg zu haben.</g> Then you choose <g>dass</g>, <g>zu</g> + infinitive or an interrogative clause.",
      "uk": "<b>1. Важливі дієслова й іменники</b><br><table><tr><th>Дієслово + прийменник</th><th>Іменник + прийменник</th></tr><tr><td><g>sich freuen über</g></td><td><g>die Freude über</g></td></tr><tr><td><g>sich ärgern über</g></td><td><g>der Ärger über</g></td></tr><tr><td><g>sich interessieren für</g></td><td><g>das Interesse an</g> (!)</td></tr><tr><td><g>teilnehmen an</g></td><td><g>die Teilnahme an</g></td></tr><tr><td><g>hoffen auf</g></td><td><g>die Hoffnung auf</g></td></tr><tr><td><g>Angst haben vor</g></td><td><g>die Angst vor</g></td></tr><tr><td><g>sich erinnern an</g></td><td><g>die Erinnerung an</g></td></tr><tr><td><g>sich bewerben um</g></td><td><g>die Bewerbung um</g></td></tr><tr><td><g>sich entscheiden für</g></td><td><g>die Entscheidung für</g></td></tr><tr><td><g>abhängen von</g></td><td><g>die Abhängigkeit von</g></td></tr><tr><td><g>zweifeln an</g></td><td><g>der Zweifel an</g></td></tr><tr><td><g>sich vorbereiten auf</g></td><td><g>die Vorbereitung auf</g></td></tr></table><br><br>Увага: іменник може вимагати іншого прийменника, ніж дієслово. Тому вчи іменник і прийменник разом.<br><br><b>2. Підмет, додаток і зміст</b><br><b>1.</b> Підмет підрядного речення стає присвійним артиклем або родовим відмінком: <g>dass sie kommt</g> → <g>ihr Kommen</g>.<br><b>2.</b> Займенниковий прислівник (<g>darüber, darauf, davon</g>) відпадає; прийменник стоїть перед іменником.<br><b>3.</b> За однакового підмета в головному й підрядному реченні підмет відпадає: <g>Er hofft, zu gewinnen.</g> → <g>Er hofft auf einen Sieg.</g><br><b>4.</b> Достатньо одного родового відмінка: <g>die Freude der Kinder über das Geschenk</g>.<br><br>Sie ärgert sich, <g>dass</g> er so spät <g>kommt</g>.<br>Вона злиться, що він приходить так пізно.<br>Sie ärgert sich <g>über</g> sein <g>spätes Kommen</g>.<br>Вона злиться через його пізній прихід.<br>Wir warten <g>darauf</g>, dass die Ergebnisse <g>veröffentlicht werden</g>.<br>Ми чекаємо, поки опублікують результати.<br>Wir warten <g>auf</g> die <g>Veröffentlichung</g> der Ergebnisse.<br>Ми чекаємо публікації результатів.<br><br><b>3. Зворотне перетворення на дієслово</b><br>У зворотному напрямку ти впізнаєш дієслово в іменнику (<g>die Hoffnung</g> → <g>hoffen</g>) і додаєш коррелят: <g>Seine Hoffnung auf Erfolg</g> → <g>Er hofft darauf, Erfolg zu haben.</g> Потім обираєш <g>dass</g>, <g>zu</g> + інфінітив або питальне речення.",
      "ru": "<b>1. Важные глаголы и существительные</b><br><table><tr><th>Глагол + предлог</th><th>Существительное + предлог</th></tr><tr><td><g>sich freuen über</g></td><td><g>die Freude über</g></td></tr><tr><td><g>sich ärgern über</g></td><td><g>der Ärger über</g></td></tr><tr><td><g>sich interessieren für</g></td><td><g>das Interesse an</g> (!)</td></tr><tr><td><g>teilnehmen an</g></td><td><g>die Teilnahme an</g></td></tr><tr><td><g>hoffen auf</g></td><td><g>die Hoffnung auf</g></td></tr><tr><td><g>Angst haben vor</g></td><td><g>die Angst vor</g></td></tr><tr><td><g>sich erinnern an</g></td><td><g>die Erinnerung an</g></td></tr><tr><td><g>sich bewerben um</g></td><td><g>die Bewerbung um</g></td></tr><tr><td><g>sich entscheiden für</g></td><td><g>die Entscheidung für</g></td></tr><tr><td><g>abhängen von</g></td><td><g>die Abhängigkeit von</g></td></tr><tr><td><g>zweifeln an</g></td><td><g>der Zweifel an</g></td></tr><tr><td><g>sich vorbereiten auf</g></td><td><g>die Vorbereitung auf</g></td></tr></table><br><br>Внимание: существительное может требовать другого предлога, чем глагол. Поэтому учи существительное и предлог вместе.<br><br><b>2. Подлежащее, дополнение и содержание</b><br><b>1.</b> Подлежащее придаточного становится притяжательным артиклем или родительным падежом: <g>dass sie kommt</g> → <g>ihr Kommen</g>.<br><b>2.</b> Местоименное наречие (<g>darüber, darauf, davon</g>) отпадает; предлог стоит перед существительным.<br><b>3.</b> При одинаковом подлежащем в главном и придаточном предложении подлежащее отпадает: <g>Er hofft, zu gewinnen.</g> → <g>Er hofft auf einen Sieg.</g><br><b>4.</b> Достаточно одного родительного падежа: <g>die Freude der Kinder über das Geschenk</g>.<br><br>Sie ärgert sich, <g>dass</g> er so spät <g>kommt</g>.<br>Она сердится, что он приходит так поздно.<br>Sie ärgert sich <g>über</g> sein <g>spätes Kommen</g>.<br>Она сердится из-за его позднего прихода.<br>Wir warten <g>darauf</g>, dass die Ergebnisse <g>veröffentlicht werden</g>.<br>Мы ждём, пока опубликуют результаты.<br>Wir warten <g>auf</g> die <g>Veröffentlichung</g> der Ergebnisse.<br>Мы ждём публикации результатов.<br><br><b>3. Обратное преобразование в глагол</b><br>При обратном преобразовании ты узнаёшь глагол в существительном (<g>die Hoffnung</g> → <g>hoffen</g>) и добавляешь коррелят: <g>Seine Hoffnung auf Erfolg</g> → <g>Er hofft darauf, Erfolg zu haben.</g> Затем выбираешь <g>dass</g>, <g>zu</g> + инфинитив или вопросительное предложение."
    }
  },
  {
    "id": "konnektoren_gegensatz_zeit",
    "title": {"de": "Konnektoren: allerdings, mittlerweile, vielmehr …", "en": "Connectors: allerdings, mittlerweile, vielmehr …", "uk": "Сполучники: allerdings, mittlerweile, vielmehr …", "ru": "Союзы: allerdings, mittlerweile, vielmehr …"},
    "explanation": {
      "de": "<b>Mit diesen Konnektoren verbindest du Sätze präziser und abwechslungsreicher.</b><br><b>Allerdings</b> schränkt eine Aussage ein („aber“): Das Buch ist gut, <g>allerdings</g> etwas lang. <b>Vielmehr</b> stellt etwas richtig („sondern“): Er ist nicht faul, <g>vielmehr</g> überarbeitet. <b>Mittlerweile</b> bedeutet „inzwischen“. Auch <b>dennoch, immerhin, zudem, ferner</b> gehören dazu. Steht der Konnektor auf Position 1, folgt das Verb auf Position 2.<br>Beispiel: Das Buch ist gut, <g>allerdings</g> etwas lang.",
      "en": "<b>With these connectors you link sentences more precisely and with more variety.</b><br><b>Allerdings</b> qualifies a statement (“but”): Das Buch ist gut, <g>allerdings</g> etwas lang. <b>Vielmehr</b> corrects something (“rather”): Er ist nicht faul, <g>vielmehr</g> überarbeitet. <b>Mittlerweile</b> means “by now”. <b>Dennoch, immerhin, zudem, ferner</b> also belong here. If the connector is in position 1, the verb follows in position 2.<br>Example: Das Buch ist gut, <g>allerdings</g> etwas lang.<br>The book is good, but a bit long.",
      "uk": "<b>За допомогою цих сполучників ти поєднуєш речення точніше й різноманітніше.</b><br><b>Allerdings</b> обмежує твердження («але»): Das Buch ist gut, <g>allerdings</g> etwas lang. <b>Vielmehr</b> виправляє («радше»): Er ist nicht faul, <g>vielmehr</g> überarbeitet. <b>Mittlerweile</b> означає «тим часом, уже». Сюди належать і <b>dennoch, immerhin, zudem, ferner</b>. Якщо сполучник стоїть на першому місці, дієслово йде на другому.<br>Приклад: Das Buch ist gut, <g>allerdings</g> etwas lang.<br>Книжка хороша, але трохи довга.",
      "ru": "<b>С помощью этих коннекторов ты соединяешь предложения точнее и разнообразнее.</b><br><b>Allerdings</b> ограничивает высказывание («но»): Das Buch ist gut, <g>allerdings</g> etwas lang. <b>Vielmehr</b> исправляет («скорее»): Er ist nicht faul, <g>vielmehr</g> überarbeitet. <b>Mittlerweile</b> означает «между тем, уже». Сюда относятся и <b>dennoch, immerhin, zudem, ferner</b>. Если коннектор стоит на первом месте, глагол идёт на втором.<br>Пример: Das Buch ist gut, <g>allerdings</g> etwas lang.<br>Книга хорошая, но немного длинная."
    },
    "rule": {
      "de": "<b>1. Gegensatz und Einschränkung</b><br><table><tr><th>Konnektor</th><th>Bedeutung und Beispiel</th></tr><tr><td><g>allerdings</g></td><td>schränkt ein („aber“):<br>Die Wohnung ist schön, <g>allerdings</g> teuer.</td></tr><tr><td><g>dennoch</g> / <g>trotzdem</g></td><td>trotz des Gegenarguments:<br>Es regnete, <g>dennoch</g> gingen wir los.</td></tr><tr><td><g>hingegen</g> / <g>dagegen</g></td><td>Gegensatz:<br>Er ist laut, sie <g>hingegen</g> ist still.</td></tr><tr><td><g>immerhin</g></td><td>positiver Aspekt („wenigstens“):<br>Er hat verloren, aber <g>immerhin</g> hat er gekämpft.</td></tr></table><br><br><b>2. Korrektur: vielmehr</b><br><g>Vielmehr</g> steht nach einer Verneinung und stellt etwas richtig. Es ist formeller als <g>sondern</g>. Als Adverb steht es auf Position 1 mit folgendem Verb oder im Mittelfeld.<br><br>Er ist nicht faul, <g>vielmehr</g> ist er überarbeitet.<br><br><b>3. Zusatz: zudem, ferner</b><br><g>Zudem</g> fügt ein weiteres Argument hinzu („außerdem“). <g>Ferner</g> ist sehr formell und reiht Punkte in Listen auf. Beide stehen auf Position 1 mit Verb auf Position 2 oder im Mittelfeld.<br><br>Die Stadt ist schön. <g>Zudem</g> ist sie günstig.<br>Der Vorstand beschloss die Fusion. <g>Ferner</g> wurde ein neuer Leiter gewählt.<br><br><b>4. Zeit: mittlerweile</b><br><g>Mittlerweile</g> bedeutet „inzwischen, in der Zwischenzeit“ oder „bis jetzt“. Es zeigt eine Veränderung seit einem früheren Zeitpunkt.<br><br>Ich habe <g>mittlerweile</g> eine neue Stelle gefunden.<br>Er hat <g>mittlerweile</g> Deutsch gelernt.<br><br><b>5. Stellung im Satz</b><br>Alle diese Konnektoren sind Adverbien. Sie stehen auf Position 1 (Verb auf Position 2), im Mittelfeld oder, wie <g>allerdings</g>, auch am Ende. Sie verbinden Sätze nicht wie <g>aber, sondern, denn</g> auf Position 0.<br><br>Er ist müde. Er arbeitet <g>dennoch</g> weiter.",
      "en": "<b>1. Contrast and qualification</b><br><table><tr><th>Connector</th><th>Meaning and example</th></tr><tr><td><g>allerdings</g></td><td>qualifies (“but”):<br>Die Wohnung ist schön, <g>allerdings</g> teuer.</td></tr><tr><td><g>dennoch</g> / <g>trotzdem</g></td><td>despite the counter-argument:<br>Es regnete, <g>dennoch</g> gingen wir los.</td></tr><tr><td><g>hingegen</g> / <g>dagegen</g></td><td>contrast:<br>Er ist laut, sie <g>hingegen</g> ist still.</td></tr><tr><td><g>immerhin</g></td><td>positive aspect (“at least”):<br>Er hat verloren, aber <g>immerhin</g> hat er gekämpft.</td></tr></table><br><br><b>2. Correction: vielmehr</b><br><g>Vielmehr</g> follows a negation and corrects something. It is more formal than <g>sondern</g>. As an adverb it stands in position 1 followed by the verb, or in the middle field.<br><br>Er ist nicht faul, <g>vielmehr</g> ist er überarbeitet.<br>He is not lazy; rather, he is overworked.<br><br><b>3. Addition: zudem, ferner</b><br><g>Zudem</g> adds a further argument (“besides”). <g>Ferner</g> is very formal and lines up points in lists. Both stand in position 1 with the verb in position 2, or in the middle field.<br><br>Die Stadt ist schön. <g>Zudem</g> ist sie günstig.<br>The city is beautiful. Moreover, it is cheap.<br>Der Vorstand beschloss die Fusion. <g>Ferner</g> wurde ein neuer Leiter gewählt.<br>The board decided on the merger. Furthermore, a new head was elected.<br><br><b>4. Time: mittlerweile</b><br><g>Mittlerweile</g> means “meanwhile, in the meantime” or “by now”. It shows a change since an earlier point in time.<br><br>Ich habe <g>mittlerweile</g> eine neue Stelle gefunden.<br>By now I have found a new job.<br>Er hat <g>mittlerweile</g> Deutsch gelernt.<br>He has learned German in the meantime.<br><br><b>5. Position in the sentence</b><br>All these connectors are adverbs. They stand in position 1 (verb in position 2), in the middle field or, like <g>allerdings</g>, also at the end. Unlike <g>aber, sondern, denn</g> they do not stand in position 0.<br><br>Er ist müde. Er arbeitet <g>dennoch</g> weiter.<br>He is tired. He keeps working all the same.",
      "uk": "<b>1. Протиставлення й обмеження</b><br><table><tr><th>Сполучник</th><th>Значення й приклад</th></tr><tr><td><g>allerdings</g></td><td>обмежує («але»):<br>Die Wohnung ist schön, <g>allerdings</g> teuer.</td></tr><tr><td><g>dennoch</g> / <g>trotzdem</g></td><td>попри контраргумент:<br>Es regnete, <g>dennoch</g> gingen wir los.</td></tr><tr><td><g>hingegen</g> / <g>dagegen</g></td><td>протиставлення:<br>Er ist laut, sie <g>hingegen</g> ist still.</td></tr><tr><td><g>immerhin</g></td><td>позитивний аспект («принаймні»):<br>Er hat verloren, aber <g>immerhin</g> hat er gekämpft.</td></tr></table><br><br><b>2. Виправлення: vielmehr</b><br><g>Vielmehr</g> стоїть після заперечення й виправляє сказане. Воно офіційніше, ніж <g>sondern</g>. Як прислівник воно стоїть на першому місці з наступним дієсловом або в середній частині речення.<br><br>Er ist nicht faul, <g>vielmehr</g> ist er überarbeitet.<br>Він не лінивий, а радше перевтомлений.<br><br><b>3. Додавання: zudem, ferner</b><br><g>Zudem</g> додає ще один аргумент («крім того»). <g>Ferner</g> дуже офіційне й нанизує пункти в переліках. Обидва стоять на першому місці з дієсловом на другому або в середній частині.<br><br>Die Stadt ist schön. <g>Zudem</g> ist sie günstig.<br>Місто гарне. До того ж воно дешеве.<br>Der Vorstand beschloss die Fusion. <g>Ferner</g> wurde ein neuer Leiter gewählt.<br>Правління ухвалило злиття. Крім того, обрали нового керівника.<br><br><b>4. Час: mittlerweile</b><br><g>Mittlerweile</g> означає «тим часом, за цей час» або «вже». Воно показує зміну від раніших часів.<br><br>Ich habe <g>mittlerweile</g> eine neue Stelle gefunden.<br>Тим часом я знайшов нову роботу.<br>Er hat <g>mittlerweile</g> Deutsch gelernt.<br>Він тим часом вивчив німецьку.<br><br><b>5. Позиція в реченні</b><br>Усі ці сполучники — прислівники. Вони стоять на першому місці (дієслово на другому), в середній частині або, як <g>allerdings</g>, наприкінці. На відміну від <g>aber, sondern, denn</g>, вони не стоять на нульовій позиції.<br><br>Er ist müde. Er arbeitet <g>dennoch</g> weiter.<br>Він утомлений. Проте він і далі працює.",
      "ru": "<b>1. Противопоставление и ограничение</b><br><table><tr><th>Коннектор</th><th>Значение и пример</th></tr><tr><td><g>allerdings</g></td><td>ограничивает («но»):<br>Die Wohnung ist schön, <g>allerdings</g> teuer.</td></tr><tr><td><g>dennoch</g> / <g>trotzdem</g></td><td>несмотря на контраргумент:<br>Es regnete, <g>dennoch</g> gingen wir los.</td></tr><tr><td><g>hingegen</g> / <g>dagegen</g></td><td>противопоставление:<br>Er ist laut, sie <g>hingegen</g> ist still.</td></tr><tr><td><g>immerhin</g></td><td>положительный аспект («по крайней мере»):<br>Er hat verloren, aber <g>immerhin</g> hat er gekämpft.</td></tr></table><br><br><b>2. Исправление: vielmehr</b><br><g>Vielmehr</g> стоит после отрицания и исправляет сказанное. Оно официальнее, чем <g>sondern</g>. Как наречие оно стоит на первом месте с последующим глаголом или в средней части предложения.<br><br>Er ist nicht faul, <g>vielmehr</g> ist er überarbeitet.<br>Он не ленив, а скорее переутомлён.<br><br><b>3. Добавление: zudem, ferner</b><br><g>Zudem</g> добавляет ещё один аргумент («кроме того»). <g>Ferner</g> очень официально и нанизывает пункты в перечнях. Оба стоят на первом месте с глаголом на втором или в средней части.<br><br>Die Stadt ist schön. <g>Zudem</g> ist sie günstig.<br>Город красивый. К тому же он недорогой.<br>Der Vorstand beschloss die Fusion. <g>Ferner</g> wurde ein neuer Leiter gewählt.<br>Правление приняло решение о слиянии. Кроме того, был избран новый руководитель.<br><br><b>4. Время: mittlerweile</b><br><g>Mittlerweile</g> означает «тем временем, за это время» или «уже». Оно показывает изменение с более раннего момента.<br><br>Ich habe <g>mittlerweile</g> eine neue Stelle gefunden.<br>Тем временем я нашёл новую работу.<br>Er hat <g>mittlerweile</g> Deutsch gelernt.<br>Он тем временем выучил немецкий.<br><br><b>5. Позиция в предложении</b><br>Все эти коннекторы — наречия. Они стоят на первом месте (глагол на втором), в средней части или, как <g>allerdings</g>, в конце. В отличие от <g>aber, sondern, denn</g>, они не стоят на нулевой позиции.<br><br>Er ist müde. Er arbeitet <g>dennoch</g> weiter.<br>Он устал. Тем не менее он продолжает работать."
    }
  },
  {
    "id": "besonderheiten_konditionalsaetze",
    "title": {"de": "Besonderheiten von Konditionalsätzen", "en": "Special features of conditional clauses", "uk": "Особливості умовних речень", "ru": "Особенности условных предложений"},
    "explanation": {
      "de": "<b>Konditionalsätze kannst du auch ohne „wenn“ bilden.</b><br>Das Verb steht dann auf Position 1: <g>Hätte</g> ich Zeit, würde ich kommen. <g>Sollte</g> es regnen, bleiben wir zu Hause. Irreale Bedingungen stehen im <b>Konjunktiv II</b>, für die Vergangenheit im Konjunktiv II der Vergangenheit: <g>Wäre</g> ich früher gekommen, <g>hätte</g> ich ihn getroffen. Außerdem gibt es <b>falls, sofern, es sei denn, angenommen, dass</b>.<br>Beispiel: <g>Hätte</g> ich Zeit, würde ich kommen.",
      "en": "<b>You can also form conditional clauses without “wenn”.</b><br>The verb then stands in position 1: <g>Hätte</g> ich Zeit, würde ich kommen. <g>Sollte</g> es regnen, bleiben wir zu Hause. Unreal conditions use the <b>Konjunktiv II</b>, for the past the past Konjunktiv II: <g>Wäre</g> ich früher gekommen, <g>hätte</g> ich ihn getroffen. There are also <b>falls, sofern, es sei denn, angenommen, dass</b>.<br>Example: <g>Hätte</g> ich Zeit, würde ich kommen.<br>If I had time, I would come.",
      "uk": "<b>Умовні речення можна утворювати й без «wenn».</b><br>Дієслово тоді стоїть на першому місці: <g>Hätte</g> ich Zeit, würde ich kommen. <g>Sollte</g> es regnen, bleiben wir zu Hause. Нереальні умови стоять у <b>Konjunktiv II</b>, для минулого — у Konjunktiv II минулого часу: <g>Wäre</g> ich früher gekommen, <g>hätte</g> ich ihn getroffen. Є також <b>falls, sofern, es sei denn, angenommen, dass</b>.<br>Приклад: <g>Hätte</g> ich Zeit, würde ich kommen.<br>Якби я мав час, я б прийшов.",
      "ru": "<b>Условные предложения можно образовывать и без «wenn».</b><br>Глагол тогда стоит на первом месте: <g>Hätte</g> ich Zeit, würde ich kommen. <g>Sollte</g> es regnen, bleiben wir zu Hause. Нереальные условия стоят в <b>Konjunktiv II</b>, для прошедшего — в Konjunktiv II прошедшего времени: <g>Wäre</g> ich früher gekommen, <g>hätte</g> ich ihn getroffen. Есть также <b>falls, sofern, es sei denn, angenommen, dass</b>.<br>Пример: <g>Hätte</g> ich Zeit, würde ich kommen.<br>Если бы у меня было время, я бы пришёл."
    },
    "rule": {
      "de": "<b>1. Konditionalsatz ohne wenn</b><br>Das konjugierte Verb steht auf Position 1. Der Hauptsatz kann mit <g>so</g> oder <g>dann</g> beginnen (dann folgt das Verb auf Position 2) oder direkt mit dem Verb. Das geht bei realen und irrealen Bedingungen.<br><br><g>Kommst</g> du pünktlich, <g>dann</g> fahren wir los.<br><g>Hätte</g> ich Zeit, <g>(dann)</g> würde ich kommen.<br><g>Wäre</g> das Wetter besser, gingen wir spazieren.<br><br><b>2. sollte</b><br><g>Sollte</g> markiert eine geringe Wahrscheinlichkeit („falls es doch passiert“). Es steht im Konjunktiv II, der Hauptsatz kann aber im Indikativ, im Imperativ oder im Konjunktiv II stehen. Mit <g>wenn</g> lautet derselbe Satz: <g>Wenn es regnen sollte, …</g><br><br><g>Sollten</g> Sie Fragen haben, rufen Sie uns an.<br><g>Sollte</g> es regnen, bleiben wir zu Hause.<br><br><b>3. Irreale Bedingungen: Gegenwart und Vergangenheit</b><br><table><tr><th>Zeitbezug</th><th>Form und Beispiel</th></tr><tr><td>Gegenwart / Zukunft</td><td>Konjunktiv II:<br><g>Hätte</g> ich Geld, <g>würde</g> ich reisen.</td></tr><tr><td>Vergangenheit</td><td><g>hätte</g> / <g>wäre</g> + Partizip II:<br><g>Wäre</g> ich früher <g>gekommen</g>, <g>hätte</g> ich ihn <g>getroffen</g>.</td></tr><tr><td>gemischt</td><td><g>Wäre</g> ich damals <g>ausgewandert</g>, <g>würde</g> ich jetzt in Kanada <g>leben</g>.</td></tr></table><br><br>Bei schwachen Verben ist der Konjunktiv II identisch mit dem Präteritum; deshalb benutzt man meist <g>würde</g> + Infinitiv. <g>Hätte, wäre, könnte, müsste, dürfte</g> und <g>wüsste</g> kann man direkt benutzen.<br><br><b>4. Weitere Konnektoren</b><br><table><tr><th>Konnektor</th><th>Bedeutung und Beispiel</th></tr><tr><td><g>falls</g></td><td>unsichere Bedingung (Indikativ):<br><g>Falls</g> er <g>kommt</g>, sag mir Bescheid.</td></tr><tr><td><g>sofern</g></td><td>Einschränkung („vorausgesetzt“):<br>Wir kommen, <g>sofern</g> es <g>möglich ist</g>.</td></tr><tr><td><g>es sei denn</g></td><td>Ausnahme:<br>Wir fahren, <g>es sei denn</g>, es <g>schneit</g>.</td></tr><tr><td><g>angenommen, dass</g></td><td>Annahme:<br><g>Angenommen</g>, <g>dass</g> er <g>recht hat</g>, was dann?</td></tr><tr><td><g>für den Fall, dass</g></td><td>Vorsorge:<br>Nimm einen Schirm mit, <g>für den Fall, dass</g> es <g>regnet</g>.</td></tr></table><br><br><b>5. Wunschsätze</b><br>Irreale Wünsche haben die Form eines Konditionalsatzes. Mit <g>doch</g> oder <g>nur</g> wird der Wunsch betont.<br><br><g>Wenn</g> ich <g>nur</g> mehr Zeit <g>hätte</g>!<br><g>Wäre</g> ich <g>doch</g> früher gekommen!",
      "en": "<b>1. Conditional clause without wenn</b><br>The conjugated verb stands in position 1. The main clause can begin with <g>so</g> or <g>dann</g> (the verb then follows in position 2) or directly with the verb. This works with real and unreal conditions.<br><br><g>Kommst</g> du pünktlich, <g>dann</g> fahren wir los.<br>If you are on time, we'll set off.<br><g>Hätte</g> ich Zeit, <g>(dann)</g> würde ich kommen.<br>If I had time, I would come.<br><g>Wäre</g> das Wetter besser, gingen wir spazieren.<br>If the weather were better, we would go for a walk.<br><br><b>2. sollte</b><br><g>Sollte</g> marks a low probability (“in case it does happen”). It is in the Konjunktiv II, but the main clause can be in the indicative, the imperative or the Konjunktiv II. With <g>wenn</g> the same sentence reads: <g>Wenn es regnen sollte, …</g><br><br><g>Sollten</g> Sie Fragen haben, rufen Sie uns an.<br>Should you have any questions, please call us.<br><g>Sollte</g> es regnen, bleiben wir zu Hause.<br>Should it rain, we will stay at home.<br><br><b>3. Unreal conditions: present and past</b><br><table><tr><th>Time reference</th><th>Form and example</th></tr><tr><td>Present / future</td><td>Konjunktiv II:<br><g>Hätte</g> ich Geld, <g>würde</g> ich reisen.</td></tr><tr><td>Past</td><td><g>hätte</g> / <g>wäre</g> + Partizip II:<br><g>Wäre</g> ich früher <g>gekommen</g>, <g>hätte</g> ich ihn <g>getroffen</g>.</td></tr><tr><td>Mixed</td><td><g>Wäre</g> ich damals <g>ausgewandert</g>, <g>würde</g> ich jetzt in Kanada <g>leben</g>.</td></tr></table><br><br>With weak verbs the Konjunktiv II is identical with the simple past; that is why <g>würde</g> + infinitive is usually used. <g>Hätte, wäre, könnte, müsste, dürfte</g> and <g>wüsste</g> can be used directly.<br><br><b>4. More connectors</b><br><table><tr><th>Connector</th><th>Meaning and example</th></tr><tr><td><g>falls</g></td><td>uncertain condition (indicative):<br><g>Falls</g> er <g>kommt</g>, sag mir Bescheid.</td></tr><tr><td><g>sofern</g></td><td>qualification (“provided that”):<br>Wir kommen, <g>sofern</g> es <g>möglich ist</g>.</td></tr><tr><td><g>es sei denn</g></td><td>exception:<br>Wir fahren, <g>es sei denn</g>, es <g>schneit</g>.</td></tr><tr><td><g>angenommen, dass</g></td><td>assumption:<br><g>Angenommen</g>, <g>dass</g> er <g>recht hat</g>, was dann?</td></tr><tr><td><g>für den Fall, dass</g></td><td>precaution:<br>Nimm einen Schirm mit, <g>für den Fall, dass</g> es <g>regnet</g>.</td></tr></table><br><br><b>5. Wish clauses</b><br>Unreal wishes have the form of a conditional clause. <g>doch</g> or <g>nur</g> emphasises the wish.<br><br><g>Wenn</g> ich <g>nur</g> mehr Zeit <g>hätte</g>!<br>If only I had more time!<br><g>Wäre</g> ich <g>doch</g> früher gekommen!<br>If only I had come earlier!",
      "uk": "<b>1. Умовне речення без wenn</b><br>Дієслово у відмінюваній формі стоїть на першому місці. Головне речення може починатися з <g>so</g> або <g>dann</g> (тоді дієслово йде на другому місці) або одразу з дієслова. Це працює і з реальними, і з нереальними умовами.<br><br><g>Kommst</g> du pünktlich, <g>dann</g> fahren wir los.<br>Якщо ти будеш вчасно, ми вирушимо.<br><g>Hätte</g> ich Zeit, <g>(dann)</g> würde ich kommen.<br>Якби я мав час, я б прийшов.<br><g>Wäre</g> das Wetter besser, gingen wir spazieren.<br>Якби погода була кращою, ми пішли б гуляти.<br><br><b>2. sollte</b><br><g>Sollte</g> позначає малу ймовірність («якщо раптом станеться»). Воно стоїть у Konjunktiv II, але головне речення може бути в індикативі, імперативі або Konjunktiv II. З <g>wenn</g> те саме речення звучить так: <g>Wenn es regnen sollte, …</g><br><br><g>Sollten</g> Sie Fragen haben, rufen Sie uns an.<br>Якщо в Вас раптом виникнуть запитання, зателефонуйте нам.<br><g>Sollte</g> es regnen, bleiben wir zu Hause.<br>Якщо піде дощ, ми залишимося вдома.<br><br><b>3. Нереальні умови: теперішнє й минуле</b><br><table><tr><th>Часовий план</th><th>Форма й приклад</th></tr><tr><td>Теперішнє / майбутнє</td><td>Konjunktiv II:<br><g>Hätte</g> ich Geld, <g>würde</g> ich reisen.</td></tr><tr><td>Минуле</td><td><g>hätte</g> / <g>wäre</g> + Partizip II:<br><g>Wäre</g> ich früher <g>gekommen</g>, <g>hätte</g> ich ihn <g>getroffen</g>.</td></tr><tr><td>Змішаний</td><td><g>Wäre</g> ich damals <g>ausgewandert</g>, <g>würde</g> ich jetzt in Kanada <g>leben</g>.</td></tr></table><br><br>У слабких дієслів Konjunktiv II збігається з Präteritum; тому зазвичай вживають <g>würde</g> + інфінітив. <g>Hätte, wäre, könnte, müsste, dürfte</g> і <g>wüsste</g> можна вживати безпосередньо.<br><br><b>4. Інші сполучники</b><br><table><tr><th>Сполучник</th><th>Значення й приклад</th></tr><tr><td><g>falls</g></td><td>непевна умова (індикатив):<br><g>Falls</g> er <g>kommt</g>, sag mir Bescheid.</td></tr><tr><td><g>sofern</g></td><td>обмеження («за умови, що»):<br>Wir kommen, <g>sofern</g> es <g>möglich ist</g>.</td></tr><tr><td><g>es sei denn</g></td><td>виняток:<br>Wir fahren, <g>es sei denn</g>, es <g>schneit</g>.</td></tr><tr><td><g>angenommen, dass</g></td><td>припущення:<br><g>Angenommen</g>, <g>dass</g> er <g>recht hat</g>, was dann?</td></tr><tr><td><g>für den Fall, dass</g></td><td>застереження:<br>Nimm einen Schirm mit, <g>für den Fall, dass</g> es <g>regnet</g>.</td></tr></table><br><br><b>5. Речення-бажання</b><br>Нереальні бажання мають форму умовного речення. Слова <g>doch</g> або <g>nur</g> підкреслюють бажання.<br><br><g>Wenn</g> ich <g>nur</g> mehr Zeit <g>hätte</g>!<br>Якби ж я мав більше часу!<br><g>Wäre</g> ich <g>doch</g> früher gekommen!<br>Якби ж я прийшов раніше!",
      "ru": "<b>1. Условное предложение без wenn</b><br>Спрягаемый глагол стоит на первом месте. Главное предложение может начинаться с <g>so</g> или <g>dann</g> (тогда глагол идёт на втором месте) или сразу с глагола. Это работает и с реальными, и с нереальными условиями.<br><br><g>Kommst</g> du pünktlich, <g>dann</g> fahren wir los.<br>Если ты придёшь вовремя, мы поедем.<br><g>Hätte</g> ich Zeit, <g>(dann)</g> würde ich kommen.<br>Если бы у меня было время, я бы пришёл.<br><g>Wäre</g> das Wetter besser, gingen wir spazieren.<br>Если бы погода была лучше, мы пошли бы гулять.<br><br><b>2. sollte</b><br><g>Sollte</g> отмечает малую вероятность («если вдруг случится»). Оно стоит в Konjunktiv II, но главное предложение может быть в индикативе, императиве или Konjunktiv II. С <g>wenn</g> то же предложение звучит так: <g>Wenn es regnen sollte, …</g><br><br><g>Sollten</g> Sie Fragen haben, rufen Sie uns an.<br>Если у Вас вдруг возникнут вопросы, позвоните нам.<br><g>Sollte</g> es regnen, bleiben wir zu Hause.<br>Если пойдёт дождь, мы останемся дома.<br><br><b>3. Нереальные условия: настоящее и прошедшее</b><br><table><tr><th>Временной план</th><th>Форма и пример</th></tr><tr><td>Настоящее / будущее</td><td>Konjunktiv II:<br><g>Hätte</g> ich Geld, <g>würde</g> ich reisen.</td></tr><tr><td>Прошедшее</td><td><g>hätte</g> / <g>wäre</g> + Partizip II:<br><g>Wäre</g> ich früher <g>gekommen</g>, <g>hätte</g> ich ihn <g>getroffen</g>.</td></tr><tr><td>Смешанный</td><td><g>Wäre</g> ich damals <g>ausgewandert</g>, <g>würde</g> ich jetzt in Kanada <g>leben</g>.</td></tr></table><br><br>У слабых глаголов Konjunktiv II совпадает с Präteritum; поэтому обычно употребляют <g>würde</g> + инфинитив. <g>Hätte, wäre, könnte, müsste, dürfte</g> и <g>wüsste</g> можно употреблять непосредственно.<br><br><b>4. Другие коннекторы</b><br><table><tr><th>Коннектор</th><th>Значение и пример</th></tr><tr><td><g>falls</g></td><td>неуверенное условие (индикатив):<br><g>Falls</g> er <g>kommt</g>, sag mir Bescheid.</td></tr><tr><td><g>sofern</g></td><td>ограничение («при условии, что»):<br>Wir kommen, <g>sofern</g> es <g>möglich ist</g>.</td></tr><tr><td><g>es sei denn</g></td><td>исключение:<br>Wir fahren, <g>es sei denn</g>, es <g>schneit</g>.</td></tr><tr><td><g>angenommen, dass</g></td><td>предположение:<br><g>Angenommen</g>, <g>dass</g> er <g>recht hat</g>, was dann?</td></tr><tr><td><g>für den Fall, dass</g></td><td>предосторожность:<br>Nimm einen Schirm mit, <g>für den Fall, dass</g> es <g>regnet</g>.</td></tr></table><br><br><b>5. Предложения-пожелания</b><br>Нереальные пожелания имеют форму условного предложения. Слова <g>doch</g> или <g>nur</g> подчёркивают пожелание.<br><br><g>Wenn</g> ich <g>nur</g> mehr Zeit <g>hätte</g>!<br>Если бы только у меня было больше времени!<br><g>Wäre</g> ich <g>doch</g> früher gekommen!<br>Если бы я только пришёл раньше!"
    }
  },
  {
    "id": "partizipialgruppen",
    "title": {"de": "Partizipialgruppen: ehrlich gesagt, genau genommen …", "en": "Participial phrases: ehrlich gesagt, genau genommen …", "uk": "Дієприкметникові звороти: ehrlich gesagt, genau genommen …", "ru": "Причастные обороты: ehrlich gesagt, genau genommen …"},
    "explanation": {
      "de": "<b>Partizipialgruppen sind feste Wendungen mit einem Partizip II.</b><br>Mit ihnen kommentierst du deine Aussage oder schränkst sie ein: <g>ehrlich gesagt</g>, <g>kurz gesagt</g>, <g>so gesehen</g>, <g>genau genommen</g>, <g>grob geschätzt</g>. Oft haben sie eine konditionale Bedeutung: <g>genau genommen</g> = wenn man es genau nimmt. Manche brauchen eine Ergänzung: <g>verglichen mit</g> + D., <g>abgesehen von</g> + D., <g>angenommen, dass</g> …<br>Beispiel: <g>Ehrlich gesagt</g> halte ich den Termin für zu knapp.",
      "en": "<b>Participial phrases are fixed expressions with a past participle.</b><br>You use them to comment on or qualify what you say: <g>ehrlich gesagt</g>, <g>kurz gesagt</g>, <g>so gesehen</g>, <g>genau genommen</g>, <g>grob geschätzt</g>. They often have a conditional meaning: <g>genau genommen</g> = if you take it precisely. Some need a complement: <g>verglichen mit</g> + dat., <g>abgesehen von</g> + dat., <g>angenommen, dass</g> …<br>Example: <g>Ehrlich gesagt</g> halte ich den Termin für zu knapp.<br><g>Frankly speaking</g>, I think the deadline is too tight.",
      "uk": "<b>Дієприкметникові звороти — це сталі вирази з дієприкметником ІІ.</b><br>Ними ти коментуєш або обмежуєш своє висловлювання: <g>ehrlich gesagt</g>, <g>kurz gesagt</g>, <g>so gesehen</g>, <g>genau genommen</g>, <g>grob geschätzt</g>. Часто вони мають умовне значення: <g>genau genommen</g> = якщо брати точно. Деякі потребують доповнення: <g>verglichen mit</g> + D., <g>abgesehen von</g> + D., <g>angenommen, dass</g> …<br>Приклад: <g>Ehrlich gesagt</g> halte ich den Termin für zu knapp.<br><g>Чесно кажучи</g>, я вважаю цей термін надто стислим.",
      "ru": "<b>Причастные обороты — это устойчивые выражения с причастием II.</b><br>Ими ты комментируешь или ограничиваешь своё высказывание: <g>ehrlich gesagt</g>, <g>kurz gesagt</g>, <g>so gesehen</g>, <g>genau genommen</g>, <g>grob geschätzt</g>. Часто они имеют условное значение: <g>genau genommen</g> = если брать точно. Некоторым нужно дополнение: <g>verglichen mit</g> + D., <g>abgesehen von</g> + D., <g>angenommen, dass</g> …<br>Пример: <g>Ehrlich gesagt</g> halte ich den Termin für zu knapp.<br><g>Честно говоря</g>, я считаю этот срок слишком сжатым."
    },
    "rule": {
      "de": "<b>1. Was ist eine Partizipialgruppe?</b><br>Eine Partizipialgruppe ist eine verkürzte Form eines Nebensatzes, meist eines Konditionalsatzes. Das Subjekt fehlt, übrig bleibt das Partizip II mit wenigen Wörtern.<br><br><g>Genau genommen</g> ist das kein Fehler.<br>= Wenn man es genau nimmt, ist das kein Fehler.<br><g>So gesehen</g> hat sie recht.<br>= Wenn man es so sieht, hat sie recht.<br><br><b>2. Feste Wendungen ohne Ergänzung</b><br><table><tr><th>Wendung</th><th>Bedeutung</th></tr><tr><td><g>ehrlich gesagt</g></td><td>um offen zu sein</td></tr><tr><td><g>kurz gesagt</g></td><td>zusammengefasst</td></tr><tr><td><g>anders gesagt / ausgedrückt / formuliert</g></td><td>mit anderen Worten</td></tr><tr><td><g>genau / streng genommen</g></td><td>wenn man es genau nimmt</td></tr><tr><td><g>im Grunde genommen</g></td><td>eigentlich</td></tr><tr><td><g>so gesehen</g></td><td>aus dieser Perspektive</td></tr><tr><td><g>genauer / oberflächlich betrachtet</g></td><td>bei genauerer / oberflächlicher Betrachtung</td></tr><tr><td><g>grob geschätzt</g></td><td>ungefähr</td></tr></table><br><br><b>3. Wendungen mit Ergänzung</b><br>Einige Partizipialgruppen haben eine Präpositionalergänzung oder leiten einen Satz ein.<br><br><g>Verglichen mit</g> dem Vorjahr ist der Umsatz gestiegen.<br><g>Abgesehen von</g> kleinen Fehlern ist der Bericht gut.<br><g>Ausgehend von</g> den Zahlen planen wir zwei neue Stellen.<br><g>Gemessen an</g> der Erfahrung ist das Gehalt niedrig.<br><g>Angenommen</g>, der Kunde lehnt ab: Was machen wir dann?<br><g>Vorausgesetzt</g>, dass alle zustimmen, beginnen wir im Mai.<br><br><b>4. Wortstellung und Komma</b><br>Steht die Partizipialgruppe am Satzanfang, folgt direkt das konjugierte Verb (Position 2): <g>Ehrlich gesagt</g> <b>finde</b> ich die Idee gut. Bei festen Wendungen ohne Ergänzung kann ein Komma stehen, es muss aber nicht. Nach <g>angenommen</g> und <g>vorausgesetzt</g> steht immer ein Komma, danach folgt ein dass-Satz oder ein Satz mit Verb an Position 2.<br><br>Längere Gruppen mit Ergänzung können auch in der Satzmitte stehen und werden dann durch Kommas abgetrennt:<br>Die Kosten sind, <g>verglichen mit</g> dem Vorjahr, deutlich gesunken.",
      "en": "<b>1. What is a participial phrase?</b><br>A participial phrase is a shortened form of a subordinate clause, usually a conditional clause. The subject is omitted, and only the past participle with a few words remains.<br><br><g>Genau genommen</g> ist das kein Fehler.<br>= Wenn man es genau nimmt, ist das kein Fehler.<br><g>Strictly speaking</g>, that is not a mistake.<br><g>So gesehen</g> hat sie recht.<br>= Wenn man es so sieht, hat sie recht.<br><g>Seen that way</g>, she is right.<br><br><b>2. Fixed expressions without a complement</b><br><table><tr><th>Expression</th><th>Meaning</th></tr><tr><td><g>ehrlich gesagt</g></td><td>to be frank</td></tr><tr><td><g>kurz gesagt</g></td><td>in short</td></tr><tr><td><g>anders gesagt / ausgedrückt / formuliert</g></td><td>in other words</td></tr><tr><td><g>genau / streng genommen</g></td><td>strictly speaking</td></tr><tr><td><g>im Grunde genommen</g></td><td>basically</td></tr><tr><td><g>so gesehen</g></td><td>from this perspective</td></tr><tr><td><g>genauer / oberflächlich betrachtet</g></td><td>on closer / superficial inspection</td></tr><tr><td><g>grob geschätzt</g></td><td>roughly</td></tr></table><br><br><b>3. Expressions with a complement</b><br>Some participial phrases take a prepositional complement or introduce a clause.<br><br><g>Verglichen mit</g> dem Vorjahr ist der Umsatz gestiegen.<br><g>Compared with</g> the previous year, turnover has risen.<br><g>Abgesehen von</g> kleinen Fehlern ist der Bericht gut.<br><g>Apart from</g> minor errors, the report is good.<br><g>Ausgehend von</g> den Zahlen planen wir zwei neue Stellen.<br><g>Based on</g> the figures, we are planning two new posts.<br><g>Gemessen an</g> der Erfahrung ist das Gehalt niedrig.<br><g>Measured against</g> the experience, the salary is low.<br><g>Angenommen</g>, der Kunde lehnt ab: Was machen wir dann?<br><g>Suppose</g> the client refuses: what do we do then?<br><g>Vorausgesetzt</g>, dass alle zustimmen, beginnen wir im Mai.<br><g>Provided</g> that everyone agrees, we will start in May.<br><br><b>4. Word order and comma</b><br>If the participial phrase comes at the beginning of the sentence, the conjugated verb follows directly (position 2): <g>Ehrlich gesagt</g> <b>finde</b> ich die Idee gut. With fixed expressions without a complement a comma may be used, but it is not required. After <g>angenommen</g> and <g>vorausgesetzt</g> there is always a comma, followed by a dass-clause or a clause with the verb in position 2.<br><br>Longer phrases with a complement can also stand in the middle of the sentence and are then separated by commas:<br>Die Kosten sind, <g>verglichen mit</g> dem Vorjahr, deutlich gesunken.<br>The costs have, <g>compared with</g> the previous year, fallen considerably.",
      "uk": "<b>1. Що таке дієприкметниковий зворот?</b><br>Дієприкметниковий зворот — це скорочена форма підрядного речення, найчастіше умовного. Підмет випадає, лишається дієприкметник ІІ з кількома словами.<br><br><g>Genau genommen</g> ist das kein Fehler.<br>= Wenn man es genau nimmt, ist das kein Fehler.<br><g>Строго кажучи</g>, це не помилка.<br><g>So gesehen</g> hat sie recht.<br>= Wenn man es so sieht, hat sie recht.<br><g>Якщо подивитися так</g>, вона має рацію.<br><br><b>2. Сталі вирази без доповнення</b><br><table><tr><th>Вираз</th><th>Значення</th></tr><tr><td><g>ehrlich gesagt</g></td><td>чесно кажучи</td></tr><tr><td><g>kurz gesagt</g></td><td>коротко кажучи</td></tr><tr><td><g>anders gesagt / ausgedrückt / formuliert</g></td><td>іншими словами</td></tr><tr><td><g>genau / streng genommen</g></td><td>строго кажучи</td></tr><tr><td><g>im Grunde genommen</g></td><td>по суті</td></tr><tr><td><g>so gesehen</g></td><td>з цього погляду</td></tr><tr><td><g>genauer / oberflächlich betrachtet</g></td><td>якщо придивитися / на перший погляд</td></tr><tr><td><g>grob geschätzt</g></td><td>приблизно</td></tr></table><br><br><b>3. Вирази з доповненням</b><br>Деякі звороти мають прийменникове доповнення або вводять речення.<br><br><g>Verglichen mit</g> dem Vorjahr ist der Umsatz gestiegen.<br><g>Порівняно з</g> минулим роком оборот зріс.<br><g>Abgesehen von</g> kleinen Fehlern ist der Bericht gut.<br><g>Якщо не брати до уваги</g> дрібні помилки, звіт добрий.<br><g>Ausgehend von</g> den Zahlen planen wir zwei neue Stellen.<br><g>Виходячи з</g> цифр, ми плануємо дві нові посади.<br><g>Gemessen an</g> der Erfahrung ist das Gehalt niedrig.<br><g>Якщо зважити на</g> досвід, зарплата низька.<br><g>Angenommen</g>, der Kunde lehnt ab: Was machen wir dann?<br><g>Припустімо</g>, клієнт відмовиться: що ми тоді робитимемо?<br><g>Vorausgesetzt</g>, dass alle zustimmen, beginnen wir im Mai.<br><g>За умови</g>, що всі погодяться, ми почнемо в травні.<br><br><b>4. Порядок слів і кома</b><br>Якщо зворот стоїть на початку речення, одразу за ним іде відмінюване дієслово (позиція 2): <g>Ehrlich gesagt</g> <b>finde</b> ich die Idee gut. Після сталих виразів без доповнення кому можна ставити, але не обовʼязково. Після <g>angenommen</g> і <g>vorausgesetzt</g> кома ставиться завжди, далі йде dass-речення або речення з дієсловом на позиції 2.<br><br>Довші звороти з доповненням можуть стояти й усередині речення, тоді їх виділяють комами:<br>Die Kosten sind, <g>verglichen mit</g> dem Vorjahr, deutlich gesunken.<br>Витрати, <g>порівняно з</g> минулим роком, суттєво знизилися.",
      "ru": "<b>1. Что такое причастный оборот?</b><br>Причастный оборот — это сокращённая форма придаточного предложения, чаще всего условного. Подлежащее опускается, остаётся причастие II с несколькими словами.<br><br><g>Genau genommen</g> ist das kein Fehler.<br>= Wenn man es genau nimmt, ist das kein Fehler.<br><g>Строго говоря</g>, это не ошибка.<br><g>So gesehen</g> hat sie recht.<br>= Wenn man es so sieht, hat sie recht.<br><g>Если посмотреть так</g>, она права.<br><br><b>2. Устойчивые выражения без дополнения</b><br><table><tr><th>Выражение</th><th>Значение</th></tr><tr><td><g>ehrlich gesagt</g></td><td>честно говоря</td></tr><tr><td><g>kurz gesagt</g></td><td>короче говоря</td></tr><tr><td><g>anders gesagt / ausgedrückt / formuliert</g></td><td>другими словами</td></tr><tr><td><g>genau / streng genommen</g></td><td>строго говоря</td></tr><tr><td><g>im Grunde genommen</g></td><td>по сути</td></tr><tr><td><g>so gesehen</g></td><td>с этой точки зрения</td></tr><tr><td><g>genauer / oberflächlich betrachtet</g></td><td>если присмотреться / на первый взгляд</td></tr><tr><td><g>grob geschätzt</g></td><td>приблизительно</td></tr></table><br><br><b>3. Выражения с дополнением</b><br>Некоторые обороты имеют предложное дополнение или вводят предложение.<br><br><g>Verglichen mit</g> dem Vorjahr ist der Umsatz gestiegen.<br><g>По сравнению с</g> прошлым годом оборот вырос.<br><g>Abgesehen von</g> kleinen Fehlern ist der Bericht gut.<br><g>Не считая</g> мелких ошибок, отчёт хороший.<br><g>Ausgehend von</g> den Zahlen planen wir zwei neue Stellen.<br><g>Исходя из</g> цифр, мы планируем две новые должности.<br><g>Gemessen an</g> der Erfahrung ist das Gehalt niedrig.<br><g>Если учесть</g> опыт, зарплата низкая.<br><g>Angenommen</g>, der Kunde lehnt ab: Was machen wir dann?<br><g>Предположим</g>, клиент откажется: что мы тогда будем делать?<br><g>Vorausgesetzt</g>, dass alle zustimmen, beginnen wir im Mai.<br><g>При условии</g>, что все согласятся, мы начнём в мае.<br><br><b>4. Порядок слов и запятая</b><br>Если оборот стоит в начале предложения, сразу за ним идёт спрягаемый глагол (позиция 2): <g>Ehrlich gesagt</g> <b>finde</b> ich die Idee gut. После устойчивых выражений без дополнения запятую можно ставить, но не обязательно. После <g>angenommen</g> и <g>vorausgesetzt</g> запятая ставится всегда, затем идёт dass-предложение или предложение с глаголом на позиции 2.<br><br>Более длинные обороты с дополнением могут стоять и в середине предложения, тогда их выделяют запятыми:<br>Die Kosten sind, <g>verglichen mit</g> dem Vorjahr, deutlich gesunken.<br>Расходы, <g>по сравнению с</g> прошлым годом, заметно снизились."
    }
  },
  {
    "id": "modalitaetsverben",
    "title": {"de": "Modalitätsverben", "en": "Verbs with modal meaning", "uk": "Дієслова з модальним значенням", "ru": "Глаголы с модальным значением"},
    "explanation": {
      "de": "<b>Modalitätsverben drücken wie Modalverben Möglichkeit, Notwendigkeit oder Einschätzung aus.</b><br>Sie bestehen aus einem Verb + <b>zu</b> + Infinitiv. <b>Sein + zu</b> = Passiv + können / müssen: Das Problem <g>ist zu lösen</g>. <b>Haben + zu</b> = müssen: Du <g>hast</g> das <g>zu tun</g>. <b>Brauchen + zu</b> (meist mit nicht / kein): Du <g>brauchst</g> nicht <g>zu kommen</g>. <b>Scheinen, drohen, pflegen, versprechen + zu</b> drücken Einschätzung oder Gewohnheit aus: Er <g>scheint</g> müde <g>zu sein</g>.<br>Beispiel: Das Problem <g>ist</g> sofort <g>zu lösen</g>.",
      "en": "<b>Like modal verbs, verbs of modality express possibility, necessity or assessment.</b><br>They consist of a verb + <b>zu</b> + infinitive. <b>Sein + zu</b> = passive + can / must: Das Problem <g>ist zu lösen</g>. <b>Haben + zu</b> = must: Du <g>hast</g> das <g>zu tun</g>. <b>Brauchen + zu</b> (mostly with nicht / kein): Du <g>brauchst</g> nicht <g>zu kommen</g>. <b>Scheinen, drohen, pflegen, versprechen + zu</b> express assessment or habit: Er <g>scheint</g> müde <g>zu sein</g>.<br>Example: Das Problem <g>ist</g> sofort <g>zu lösen</g>.<br>The problem has to be solved at once.",
      "uk": "<b>Дієслова модальності, як і модальні дієслова, виражають можливість, необхідність або оцінку.</b><br>Вони складаються з дієслова + <b>zu</b> + інфінітив. <b>Sein + zu</b> = пасив + можна / треба: Das Problem <g>ist zu lösen</g>. <b>Haben + zu</b> = мусити: Du <g>hast</g> das <g>zu tun</g>. <b>Brauchen + zu</b> (здебільшого з nicht / kein): Du <g>brauchst</g> nicht <g>zu kommen</g>. <b>Scheinen, drohen, pflegen, versprechen + zu</b> виражають оцінку або звичку: Er <g>scheint</g> müde <g>zu sein</g>.<br>Приклад: Das Problem <g>ist</g> sofort <g>zu lösen</g>.<br>Проблему треба негайно розвʼязати.",
      "ru": "<b>Глаголы модальности, как и модальные глаголы, выражают возможность, необходимость или оценку.</b><br>Они состоят из глагола + <b>zu</b> + инфинитив. <b>Sein + zu</b> = пассив + можно / нужно: Das Problem <g>ist zu lösen</g>. <b>Haben + zu</b> = быть должным: Du <g>hast</g> das <g>zu tun</g>. <b>Brauchen + zu</b> (в основном с nicht / kein): Du <g>brauchst</g> nicht <g>zu kommen</g>. <b>Scheinen, drohen, pflegen, versprechen + zu</b> выражают оценку или привычку: Er <g>scheint</g> müde <g>zu sein</g>.<br>Пример: Das Problem <g>ist</g> sofort <g>zu lösen</g>.<br>Проблему нужно немедленно решить."
    },
    "rule": {
      "de": "<b>1. Überblick</b><br><table><tr><th>Verb</th><th>Bedeutung</th></tr><tr><td><g>sein + zu</g></td><td>Passiv: können / müssen</td></tr><tr><td><g>haben + zu</g></td><td>aktiv: müssen</td></tr><tr><td><g>brauchen + zu</g></td><td>nur mit Verneinung: nicht müssen</td></tr><tr><td><g>scheinen / drohen / versprechen + zu</g></td><td>Einschätzung</td></tr><tr><td><g>pflegen + zu</g></td><td>Gewohnheit</td></tr></table><br><br><b>2. sein + zu + Infinitiv</b><br>Diese Konstruktion hat passive Bedeutung. Das Subjekt ist das Objekt des Verbs im Aktiv. Sie bedeutet <b>kann / muss … werden</b>; mit <g>nicht</g> bedeutet sie <b>kann / darf nicht … werden</b>. Sie ist nur bei transitiven Verben möglich.<br><br>Das Problem <g>ist</g> leicht <g>zu lösen</g>. (= kann gelöst werden)<br>Die Frist <g>ist</g> unbedingt <g>einzuhalten</g>. (= muss eingehalten werden)<br>Das <g>ist</g> nicht <g>zu schaffen</g>. (= kann nicht geschafft werden)<br><br><b>3. haben + zu + Infinitiv</b><br>Diese Konstruktion hat aktive Bedeutung und drückt eine Pflicht oder Aufgabe aus (<b>müssen</b>). Das Subjekt ist die handelnde Person. Auch <g>nichts zu tun haben</g> oder <g>viel zu erledigen haben</g> gehören hierher.<br><br>Sie <g>haben</g> die Unterlagen bis Montag <g>einzureichen</g>.<br>Ich <g>habe</g> heute noch viel <g>zu erledigen</g>.<br><br><b>4. brauchen + zu + Infinitiv</b><br><g>Brauchen</g> steht mit <g>zu</g> nur zusammen mit einer Verneinung oder Einschränkung (<g>nicht, kein, nur, kaum, erst, lediglich</g>). Es bedeutet <b>nicht müssen</b> beziehungsweise <b>es genügt</b>. Positiv sagt man <g>müssen</g>.<br><br>Du <g>brauchst</g> nicht <g>zu kommen</g>.<br>Du <g>brauchst</g> nur <g>zu fragen</g>.<br>Du <g>musst</g> das Formular ausfüllen. (nicht: brauchst … auszufüllen)<br><br><b>5. scheinen, drohen, versprechen, pflegen + zu</b><br><table><tr><th>Verb</th><th>Bedeutung und Beispiel</th></tr><tr><td><g>scheinen + zu</g></td><td>Vermutung:<br>Er <g>scheint</g> müde <g>zu sein</g>.</td></tr><tr><td><g>drohen + zu</g></td><td>negative Entwicklung:<br>Das Haus <g>droht</g> einzu<g>stürzen</g>.</td></tr><tr><td><g>versprechen + zu</g></td><td>positive Erwartung:<br>Das Konzert <g>verspricht</g> ein Erfolg <g>zu werden</g>.</td></tr><tr><td><g>pflegen + zu</g></td><td>Gewohnheit:<br>Er <g>pflegt</g> morgens spazieren <g>zu gehen</g>.</td></tr></table><br><br><g>Scheinen</g> kann man auch mit <g>dass</g> umschreiben: <g>Es scheint, dass er müde ist.</g> Mit <g>drohen</g> und <g>versprechen</g> steht das Verb im Infinitiv immer im Aktiv.<br><br><b>6. Weitere Verben mit zu</b><br>Es gibt weitere Verben mit passiver Bedeutung: <g>bleiben + zu</g> (<g>Das bleibt abzuwarten.</g> = muss abgewartet werden), <g>stehen + zu</g> (<g>Es steht zu erwarten, dass …</g>) und <g>gelten + zu</g> (<g>Es gilt, Fehler zu vermeiden.</g> = es ist nötig). Formelle Verben mit der Bedeutung <b>können</b> sind <g>vermögen</g> und <g>verstehen</g>: <g>Er versteht zu überzeugen.</g>",
      "en": "<b>1. Overview</b><br><table><tr><th>Verb</th><th>Meaning</th></tr><tr><td><g>sein + zu</g></td><td>passive: can / must</td></tr><tr><td><g>haben + zu</g></td><td>active: must</td></tr><tr><td><g>brauchen + zu</g></td><td>only with negation: need not</td></tr><tr><td><g>scheinen / drohen / versprechen + zu</g></td><td>assessment</td></tr><tr><td><g>pflegen + zu</g></td><td>habit</td></tr></table><br><br><b>2. sein + zu + infinitive</b><br>This construction has a passive meaning. The subject is the object of the verb in the active. It means <b>can / must be …</b>; with <g>nicht</g> it means <b>cannot / must not be …</b>. It is possible only with transitive verbs.<br><br>Das Problem <g>ist</g> leicht <g>zu lösen</g>. (= kann gelöst werden)<br>The problem is easy to solve.<br>Die Frist <g>ist</g> unbedingt <g>einzuhalten</g>. (= muss eingehalten werden)<br>The deadline must be met.<br>Das <g>ist</g> nicht <g>zu schaffen</g>. (= kann nicht geschafft werden)<br>That can't be done.<br><br><b>3. haben + zu + infinitive</b><br>This construction has an active meaning and expresses an obligation or task (<b>must</b>). The subject is the acting person. <g>Nichts zu tun haben</g> or <g>viel zu erledigen haben</g> also belong here.<br><br>Sie <g>haben</g> die Unterlagen bis Montag <g>einzureichen</g>.<br>You have to submit the documents by Monday.<br>Ich <g>habe</g> heute noch viel <g>zu erledigen</g>.<br>I still have a lot to do today.<br><br><b>4. brauchen + zu + infinitive</b><br><g>Brauchen</g> is used with <g>zu</g> only together with a negation or restriction (<g>nicht, kein, nur, kaum, erst, lediglich</g>). It means <b>need not</b> or <b>it is enough</b>. In positive sentences you say <g>müssen</g>.<br><br>Du <g>brauchst</g> nicht <g>zu kommen</g>.<br>You don't need to come.<br>Du <g>brauchst</g> nur <g>zu fragen</g>.<br>You only need to ask.<br>Du <g>musst</g> das Formular ausfüllen. (nicht: brauchst … auszufüllen)<br>You have to fill in the form.<br><br><b>5. scheinen, drohen, versprechen, pflegen + zu</b><br><table><tr><th>Verb</th><th>Meaning and example</th></tr><tr><td><g>scheinen + zu</g></td><td>assumption:<br>Er <g>scheint</g> müde <g>zu sein</g>.</td></tr><tr><td><g>drohen + zu</g></td><td>negative development:<br>Das Haus <g>droht</g> einzu<g>stürzen</g>.</td></tr><tr><td><g>versprechen + zu</g></td><td>positive expectation:<br>Das Konzert <g>verspricht</g> ein Erfolg <g>zu werden</g>.</td></tr><tr><td><g>pflegen + zu</g></td><td>habit:<br>Er <g>pflegt</g> morgens spazieren <g>zu gehen</g>.</td></tr></table><br><br><g>Scheinen</g> can also be paraphrased with <g>dass</g>: <g>Es scheint, dass er müde ist.</g> With <g>drohen</g> and <g>versprechen</g> the infinitive is always active.<br><br><b>6. More verbs with zu</b><br>There are further verbs with a passive meaning: <g>bleiben + zu</g> (<g>Das bleibt abzuwarten.</g> = has to be waited for), <g>stehen + zu</g> (<g>Es steht zu erwarten, dass …</g>) and <g>gelten + zu</g> (<g>Es gilt, Fehler zu vermeiden.</g> = it is necessary). Formal verbs meaning <b>can</b> are <g>vermögen</g> and <g>verstehen</g>: <g>Er versteht zu überzeugen.</g>",
      "uk": "<b>1. Огляд</b><br><table><tr><th>Дієслово</th><th>Значення</th></tr><tr><td><g>sein + zu</g></td><td>пасив: можна / треба</td></tr><tr><td><g>haben + zu</g></td><td>актив: мусити</td></tr><tr><td><g>brauchen + zu</g></td><td>лише із запереченням: не мусити</td></tr><tr><td><g>scheinen / drohen / versprechen + zu</g></td><td>оцінка</td></tr><tr><td><g>pflegen + zu</g></td><td>звичка</td></tr></table><br><br><b>2. sein + zu + інфінітив</b><br>Ця конструкція має пасивне значення. Підмет — це додаток дієслова в активі. Вона означає <b>може / має бути …</b>; з <g>nicht</g> означає <b>не може / не повинно бути …</b>. Вона можлива лише з перехідними дієсловами.<br><br>Das Problem <g>ist</g> leicht <g>zu lösen</g>. (= kann gelöst werden)<br>Цю проблему легко розвʼязати.<br>Die Frist <g>ist</g> unbedingt <g>einzuhalten</g>. (= muss eingehalten werden)<br>Термін неодмінно слід дотримати.<br>Das <g>ist</g> nicht <g>zu schaffen</g>. (= kann nicht geschafft werden)<br>Цього не можна встигнути.<br><br><b>3. haben + zu + інфінітив</b><br>Ця конструкція має активне значення й виражає обовʼязок або завдання (<b>мусити</b>). Підмет — це особа, що діє. Сюди належать і <g>nichts zu tun haben</g>, і <g>viel zu erledigen haben</g>.<br><br>Sie <g>haben</g> die Unterlagen bis Montag <g>einzureichen</g>.<br>Ви маєте подати документи до понеділка.<br>Ich <g>habe</g> heute noch viel <g>zu erledigen</g>.<br>Мені сьогодні ще багато треба зробити.<br><br><b>4. brauchen + zu + інфінітив</b><br><g>Brauchen</g> з <g>zu</g> вживається лише разом із запереченням або обмеженням (<g>nicht, kein, nur, kaum, erst, lediglich</g>). Воно означає <b>не мусити</b> або <b>досить</b>. У ствердних реченнях кажуть <g>müssen</g>.<br><br>Du <g>brauchst</g> nicht <g>zu kommen</g>.<br>Тобі не потрібно приходити.<br>Du <g>brauchst</g> nur <g>zu fragen</g>.<br>Тобі досить лише запитати.<br>Du <g>musst</g> das Formular ausfüllen. (nicht: brauchst … auszufüllen)<br>Ти маєш заповнити формуляр.<br><br><b>5. scheinen, drohen, versprechen, pflegen + zu</b><br><table><tr><th>Дієслово</th><th>Значення й приклад</th></tr><tr><td><g>scheinen + zu</g></td><td>припущення:<br>Er <g>scheint</g> müde <g>zu sein</g>.</td></tr><tr><td><g>drohen + zu</g></td><td>негативний розвиток:<br>Das Haus <g>droht</g> einzu<g>stürzen</g>.</td></tr><tr><td><g>versprechen + zu</g></td><td>позитивне очікування:<br>Das Konzert <g>verspricht</g> ein Erfolg <g>zu werden</g>.</td></tr><tr><td><g>pflegen + zu</g></td><td>звичка:<br>Er <g>pflegt</g> morgens spazieren <g>zu gehen</g>.</td></tr></table><br><br><g>Scheinen</g> можна перефразувати й через <g>dass</g>: <g>Es scheint, dass er müde ist.</g> З <g>drohen</g> і <g>versprechen</g> інфінітив завжди в активі.<br><br><b>6. Інші дієслова з zu</b><br>Є й інші дієслова з пасивним значенням: <g>bleiben + zu</g> (<g>Das bleibt abzuwarten.</g> = треба зачекати), <g>stehen + zu</g> (<g>Es steht zu erwarten, dass …</g>) та <g>gelten + zu</g> (<g>Es gilt, Fehler zu vermeiden.</g> = треба). Офіційні дієслова зі значенням <b>могти</b> — це <g>vermögen</g> і <g>verstehen</g>: <g>Er versteht zu überzeugen.</g>",
      "ru": "<b>1. Обзор</b><br><table><tr><th>Глагол</th><th>Значение</th></tr><tr><td><g>sein + zu</g></td><td>пассив: можно / нужно</td></tr><tr><td><g>haben + zu</g></td><td>актив: быть должным</td></tr><tr><td><g>brauchen + zu</g></td><td>только с отрицанием: не быть обязанным</td></tr><tr><td><g>scheinen / drohen / versprechen + zu</g></td><td>оценка</td></tr><tr><td><g>pflegen + zu</g></td><td>привычка</td></tr></table><br><br><b>2. sein + zu + инфинитив</b><br>Эта конструкция имеет пассивное значение. Подлежащее — это дополнение глагола в активе. Она означает <b>может / должно быть …</b>; с <g>nicht</g> означает <b>не может / не должно быть …</b>. Она возможна только с переходными глаголами.<br><br>Das Problem <g>ist</g> leicht <g>zu lösen</g>. (= kann gelöst werden)<br>Эту проблему легко решить.<br>Die Frist <g>ist</g> unbedingt <g>einzuhalten</g>. (= muss eingehalten werden)<br>Срок необходимо соблюдать.<br>Das <g>ist</g> nicht <g>zu schaffen</g>. (= kann nicht geschafft werden)<br>Этого не успеть.<br><br><b>3. haben + zu + инфинитив</b><br>Эта конструкция имеет активное значение и выражает обязанность или задачу (<b>быть должным</b>). Подлежащее — это действующее лицо. Сюда относятся и <g>nichts zu tun haben</g>, и <g>viel zu erledigen haben</g>.<br><br>Sie <g>haben</g> die Unterlagen bis Montag <g>einzureichen</g>.<br>Вы должны подать документы до понедельника.<br>Ich <g>habe</g> heute noch viel <g>zu erledigen</g>.<br>Мне сегодня ещё многое нужно сделать.<br><br><b>4. brauchen + zu + инфинитив</b><br><g>Brauchen</g> с <g>zu</g> употребляется только вместе с отрицанием или ограничением (<g>nicht, kein, nur, kaum, erst, lediglich</g>). Оно означает <b>не быть обязанным</b> или <b>достаточно</b>. В утвердительных предложениях говорят <g>müssen</g>.<br><br>Du <g>brauchst</g> nicht <g>zu kommen</g>.<br>Тебе не нужно приходить.<br>Du <g>brauchst</g> nur <g>zu fragen</g>.<br>Тебе достаточно только спросить.<br>Du <g>musst</g> das Formular ausfüllen. (nicht: brauchst … auszufüllen)<br>Ты должен заполнить формуляр.<br><br><b>5. scheinen, drohen, versprechen, pflegen + zu</b><br><table><tr><th>Глагол</th><th>Значение и пример</th></tr><tr><td><g>scheinen + zu</g></td><td>предположение:<br>Er <g>scheint</g> müde <g>zu sein</g>.</td></tr><tr><td><g>drohen + zu</g></td><td>негативное развитие:<br>Das Haus <g>droht</g> einzu<g>stürzen</g>.</td></tr><tr><td><g>versprechen + zu</g></td><td>положительное ожидание:<br>Das Konzert <g>verspricht</g> ein Erfolg <g>zu werden</g>.</td></tr><tr><td><g>pflegen + zu</g></td><td>привычка:<br>Er <g>pflegt</g> morgens spazieren <g>zu gehen</g>.</td></tr></table><br><br><g>Scheinen</g> можно перефразировать и через <g>dass</g>: <g>Es scheint, dass er müde ist.</g> С <g>drohen</g> и <g>versprechen</g> инфинитив всегда в активе.<br><br><b>6. Другие глаголы с zu</b><br>Есть и другие глаголы с пассивным значением: <g>bleiben + zu</g> (<g>Das bleibt abzuwarten.</g> = нужно подождать), <g>stehen + zu</g> (<g>Es steht zu erwarten, dass …</g>) и <g>gelten + zu</g> (<g>Es gilt, Fehler zu vermeiden.</g> = нужно). Официальные глаголы со значением <b>мочь</b> — это <g>vermögen</g> и <g>verstehen</g>: <g>Er versteht zu überzeugen.</g>"
    }
  }
];
